SCUM_FTP_PASS = os.getenv("SCUM_FTP_PASS", SCUM_FTP_PASS)

# Se a senha não estiver nas variáveis de ambiente, o bot tenta usar
# automaticamente a credencial salva no FileZilla deste mesmo Windows.
# Assim o Kill Feed não fica permanentemente desativado por falta de
# SCUM_FTP_PASS. Nenhuma senha é exibida no console.
def _decode_filezilla_value(value, encoding=None):
    value = (value or "").strip()
    if not value:
        return ""
    if (encoding or "").lower() == "base64":
        try:
            return base64.b64decode(value).decode("utf-8", errors="strict")
        except Exception:
            return ""
    return value


def _load_filezilla_ftp_credentials():
    target_host = os.getenv("SCUM_FTP_HOST", "172.240.53.83").strip()
    target_user = os.getenv("SCUM_FTP_USER", "172.240.153.61").strip()
    appdata = os.getenv("APPDATA", "")
    candidates = []
    if appdata:
        candidates.extend([
            os.path.join(appdata, "FileZilla", "sitemanager.xml"),
            os.path.join(appdata, "FileZilla", "recentservers.xml"),
        ])

    for path in candidates:
        try:
            if not os.path.isfile(path):
                continue
            root = ET.parse(path).getroot()
            for server in root.iter("Server"):
                host = (server.findtext("Host") or "").strip()
                user = (server.findtext("User") or "").strip()
                if host != target_host or user != target_user:
                    continue
                pass_node = server.find("Pass")
                if pass_node is None:
                    continue
                password = _decode_filezilla_value(
                    pass_node.text, pass_node.attrib.get("encoding")
                )
                if password:
                    return host, user, password
        except Exception:
            continue
    return "", "", ""


def _ensure_ftp_credentials():
    global SCUM_FTP_HOST, SCUM_FTP_USER, SCUM_FTP_PASS

    # Variáveis de ambiente continuam tendo prioridade.
    if SCUM_FTP_HOST and SCUM_FTP_USER and SCUM_FTP_PASS:
        return True

    host, user, password = _load_filezilla_ftp_credentials()
    if host and user and password:
        SCUM_FTP_HOST = host
        SCUM_FTP_USER = user
        SCUM_FTP_PASS = password
        print("KILL FEED: credenciais do FileZilla carregadas automaticamente.")
        return True

    return False
