def find_text_channel_anywhere(guild, name):
    return discord.utils.find(
        lambda c: isinstance(c, discord.TextChannel)
        and c.name == name,
        guild.text_channels
    )


async def move_channel_to_category(
    channel,
    category,
    position=0
):
    if channel is None:
        return

    try:
        await channel.edit(
            category=category,
            position=position,
            reason="Organização PRIMEIRO MUNDO"
        )
    except (
        discord.Forbidden,
        discord.HTTPException
    ):
        pass


async def send_if_empty(channel, content):
    """Publica conteúdo inicial sem duplicar mensagens."""
    try:
        async for msg in channel.history(limit=50):
            if msg.author == bot.user and msg.content.strip() == content.strip():
                return
            if not msg.author.bot:
                return
        await channel.send(content)
    except (discord.Forbidden, discord.HTTPException):
        pass


async def _live_ensure_announcement_panel(channel):
    """Mantém somente um aviso institucional; não toca em anúncios reais de lives."""
    content = (
        "🔴 **AO VIVO NO PRIMEIRO MUNDO**\n\n"
        "Aqui o bot anuncia lives aprovadas de criadores que estejam conectados ao nosso servidor SCUM. "
        "Cada transmissão recebe um único aviso @everyone.\n\n"
        "🎥 Para participar, use o botão no canal **🎥・cadastro-de-criadores**. "
        "A administração aprova ou recusa cada solicitação."
    )
    try:
        panels = []
        async for msg in channel.history(limit=200):
            if (msg.author.id == bot.user.id and msg.content.startswith("🔴 **AO VIVO NO PRIMEIRO MUNDO**")):
                panels.append(msg)
        if panels:
            keeper = panels[0]
            if keeper.content != content:
                await keeper.edit(content=content, allowed_mentions=discord.AllowedMentions.none())
            for duplicate in panels[1:]:
                await duplicate.delete()
        else:
            await channel.send(content, allowed_mentions=discord.AllowedMentions.none())
    except (discord.Forbidden, discord.HTTPException) as error:
        print(f"LIVES: painel de apresentação não atualizado: {type(error).__name__}: {error}")


async def update_insurance_panel(channel, content):
    """Atualiza o painel oficial de seguro sem criar duplicatas."""
    try:
        async for msg in channel.history(limit=50):
            if msg.author == bot.user:
                if msg.content.strip() != content.strip():
                    await msg.edit(content=content)
                return

        await channel.send(content)

    except (discord.Forbidden, discord.HTTPException):
        pass


def get_staff_roles(guild):
    roles = []

    for role_name in STAFF_ROLE_NAMES:
        role = discord.utils.get(
            guild.roles,
            name=role_name
        )

        if role:
            roles.append(role)

    return roles


def is_staff(member):
    if member.guild_permissions.administrator:
        return True

    return any(
        role.name in STAFF_ROLE_NAMES
        for role in member.roles
    )


async def send_technical_log(guild, message):
    """Erros operacionais ficam separados das entradas/saídas do Discord."""
    channel = discord.utils.get(guild.text_channels, name=TECH_LOG_CHANNEL_NAME)
    if channel is None:
        return
    try:
        await channel.send(str(message)[:1900], allowed_mentions=discord.AllowedMentions.none())
    except (discord.Forbidden, discord.HTTPException):
        pass


class _DiscordTechnicalErrorHandler(logging.Handler):
    """Encaminha erros do discord.py sem interceptar stdout nem gerar loops."""
    def __init__(self):
        super().__init__(level=logging.WARNING)
        self.last_sent = {}
        self.rate_limit_events = []
        self.rate_limit_alerted = False
        self.rate_limit_last = 0.0

    def emit(self, record):
        try:
            message = self.format(record)
            # A biblioteca recupera automaticamente de 429 isolados. Avisar
            # apenas se ocorrerem pelo menos 3 dentro de 5 minutos.
            if record.name.startswith('discord.http') and '429' in message:
                now = time.monotonic()
                self.rate_limit_events = [t for t in self.rate_limit_events if now - t < 300]
                self.rate_limit_events.append(now)
                self.rate_limit_last = now
                if len(self.rate_limit_events) < 3 or self.rate_limit_alerted:
                    return
                self.rate_limit_alerted = True
                message = ('Discord limitou repetidamente as requisições HTTP (429): '
                           f'{len(self.rate_limit_events)} ocorrências em até 5 minutos. '
                           'O discord.py está aplicando as esperas automáticas.')
            elif record.levelno < logging.ERROR:
                return

            key = ('discord-rate-limit' if record.name.startswith('discord.http') and self.rate_limit_alerted and '429' not in message else record.name, message[:220])
            now = time.monotonic()
            if now - self.last_sent.get(key, 0) < 600:
                return
            loop = bot.loop
            if loop.is_closed() or not bot.is_ready():
                return
            self.last_sent[key] = now
            for guild in bot.guilds:
                loop.call_soon_threadsafe(
                    lambda g=guild, m=message: asyncio.create_task(
                        send_technical_log(g, f'⚠️ **Erro técnico**\n```{m[:1750].replace(chr(96), chr(39))}```')
                    )
                )
        except Exception:
            pass


async def _technical_rate_limit_recovery_watch(handler):
    """Notifica recuperação apenas depois de um incidente 429 já comunicado."""
    await bot.wait_until_ready()
    while not bot.is_closed():
        await asyncio.sleep(60)
        if handler.rate_limit_alerted and time.monotonic() - handler.rate_limit_last >= 600:
            handler.rate_limit_alerted = False
            handler.rate_limit_events.clear()
            for guild in bot.guilds:
                await send_technical_log(guild, '🟢 **Discord recuperado**\nNenhum novo aviso HTTP 429 nos últimos 10 minutos.')


async def send_log(guild, message):
    channel = discord.utils.get(
        guild.text_channels,
        name=LOG_CHANNEL_NAME
    )

    if channel is None:
        return

    try:
        await channel.send(message)
    except (
        discord.Forbidden,
        discord.HTTPException
    ):
        pass


