def format_scum_status_embed(data):
    """Monta o painel sem declarar OFFLINE apenas porque uma fonte falhou."""
    online = bool(data.get("online"))
    stale = bool(data.get("stale"))
    source = data.get("source", "desconhecida")

    if online:
        if stale:
            title_status = "🟡 ONLINE — ÚLTIMA LEITURA"
            colour = discord.Colour.gold()
        else:
            title_status = "🟢 ONLINE"
            colour = discord.Colour.green()

        description = (
            f"{title_status}\n\n"
            f"🏝️ **{SERVER_NAME}**\n"
            "🎮 SCUM"
        )

        if stale:
            description += (
                "\n\n⚠️ O bot não conseguiu fazer uma nova consulta agora. "
                "Os dados abaixo são da última leitura válida."
            )

        embed = discord.Embed(
            title="📡 STATUS DO SERVIDOR",
            description=description,
            colour=colour
        )

        players_value = data.get("players")
        if players_value is None:
            players_display = f"— / {data.get('max_players', 48)}"
        else:
            players_display = f"{players_value} / {data.get('max_players', 48)}"

        embed.add_field(
            name="👥 Jogadores",
            value=f"**{players_display}**",
            inline=True
        )

        names = data.get("player_names") or []
        names_display = "\n".join(f"• {n}" for n in names) if names else "Nenhum jogador online"
        if len(names_display) > 1000:
            names_display = names_display[:997] + "..."
        embed.add_field(
            name="👤 Jogadores online agora",
            value=names_display,
            inline=True
        )
        embed.add_field(
            name="🕐 Horário no jogo",
            value=data.get("gametime") or "Indisponível",
            inline=True
        )
        embed.add_field(
            name="🗺️ Mapa",
            value=data.get("map") or "SCUM",
            inline=True
        )
        embed.add_field(
            name="🔢 Versão",
            value=data.get("version") or "Indisponível",
            inline=True
        )
        embed.add_field(
            name="🌐 Game",
            value=f"`{SCUM_HOST}:{SCUM_GAME_PORT}`",
            inline=True
        )
        embed.add_field(
            name="📡 Query",
            value=f"`{SCUM_HOST}:{SCUM_QUERY_PORT}`",
            inline=True
        )

        if data.get("ping") is not None:
            embed.add_field(
                name="📶 Ping",
                value=f"`{data['ping']} ms`",
                inline=True
            )

        embed.add_field(
            name="📊 Fonte",
            value=source,
            inline=True
        )

        if data.get("log_age") is not None:
            age_seconds = int(data["log_age"])
            if age_seconds < 60:
                age_display = f"{age_seconds}s"
            else:
                age_display = f"{age_seconds // 60}min {age_seconds % 60:02d}s"
            embed.add_field(
                name="💓 Heartbeat",
                value=f"`SCUM.log • {age_display}`",
                inline=True
            )

        scanned = data.get("fetched_at")
        if scanned:
            embed.add_field(
                name="🔄 Última leitura",
                value=scanned,
                inline=True
            )

        embed.set_footer(
            text="PRIMEIRO MUNDO • STATUS DIRETO FTP • 🔄 Ciclo FTP contínuo"
        )
        return embed

    # Só chegamos aqui quando não existe nenhuma leitura válida em cache.
    embed = discord.Embed(
        title="📡 STATUS DO SERVIDOR",
        description=(
            "🟠 **SEM RESPOSTA DE CONSULTA**\n\n"
            f"🏝️ **{SERVER_NAME}**\n"
            "🎮 SCUM\n\n"
            "O bot ainda não conseguiu obter uma leitura válida do servidor. "
            "Isso não significa necessariamente que o servidor esteja offline."
        ),
        colour=discord.Colour.orange()
    )

    embed.add_field(
        name="🌐 Game",
        value=f"`{SCUM_HOST}:{SCUM_GAME_PORT}`",
        inline=True
    )
    embed.add_field(
        name="📡 Query",
        value=f"`{SCUM_HOST}:{SCUM_QUERY_PORT}`",
        inline=True
    )
    embed.add_field(
        name="📊 Fonte",
        value=source,
        inline=True
    )

    embed.set_footer(
        text="PRIMEIRO MUNDO • STATUS DIRETO FTP • 🔄 Ciclo FTP contínuo"
    )
    return embed


def _first_match(text, patterns, default=""):
    for pattern in patterns:
        m = re.search(pattern, text, re.IGNORECASE | re.DOTALL)
        if m:
            return " ".join(m.group(1).split())
    return default



def _utc_scanned_to_brasilia(scanned_text):
    """Converte apenas o 'Last scanned' do Query.Games de UTC para Brasília."""
    if not scanned_text:
        return ""

    for fmt in ("%m/%d/%y, %I:%M %p", "%m/%d/%Y, %I:%M %p"):
        try:
            dt = datetime.strptime(scanned_text.strip(), fmt)
            dt -= timedelta(hours=3)
            return dt.strftime("%d/%m/%Y %H:%M")
        except ValueError:
            pass

    return scanned_text


def _parse_query_games_html(html):
    """Extrai os campos da página pública do Query.Games.

    A página pública é usada somente como fallback. A API oficial exige
    autenticação por API key.
    """
    soup = BeautifulSoup(html, "html.parser")
    text = soup.get_text(" ", strip=True)

    # Confirma que estamos realmente na página do servidor esperado.
    server_name = ""
    h1 = soup.find("h1")
    if h1:
        server_name = h1.get_text(" ", strip=True)

    ip_game = _first_match(
        text,
        [r"(\d{1,3}(?:\.\d{1,3}){3}:\d+)\s+Claim",
         r"(\d{1,3}(?:\.\d{1,3}){3}:\d+)\s+Server Info"]
    )

    query_addr = _first_match(
        text,
        [r"IP:Port \(Query\)\s*([0-9.]+:\d+)",
         r"IP:Port \(Query\)\s*`?([0-9.]+:\d+)`?"]
    )

    game_addr = _first_match(
        text,
        [r"IP:Port \(Game\)\s*([0-9.]+:\d+)",
         r"IP:Port \(Game\)\s*`?([0-9.]+:\d+)`?"]
    )

    version = _first_match(text, [r"Version\s+([0-9.]+)"])
    gametime = _first_match(text, [r"Server Time\s+([0-9]{1,2}:[0-9]{2})"])
    players_text = _first_match(text, [r"Players\s+(\d+\s*/\s*\d+)"])
    scanned = _utc_scanned_to_brasilia(_first_match(text, [r"Last scanned\s+([^ ]+\s+[^ ]+\s+(?:AM|PM))"]))

    # Query.Games pode manter uma ficha antiga e marcá-la como OFFLINE.
    # Essa página não deve ser tratada como uma confirmação de servidor online.
    if re.search(r"currently\s+offline", text, re.IGNORECASE):
        raise ValueError("Query.Games marcou o servidor como OFFLINE; ignorando leitura stale")

    if not players_text:
        players_text = _first_match(text, [r"Players\s+(\d+)\s*/\s*(\d+)"])

    if not query_addr or not players_text:
        raise ValueError("Não foi possível interpretar a página pública do Query.Games")

    parts = re.split(r"\s*/\s*", players_text)
    players = int(parts[0])
    max_players = int(parts[1]) if len(parts) > 1 else 0

    if not game_addr:
        game_addr = ip_game

    if not server_name:
        server_name = SERVER_NAME

    # O servidor exibido no site deve corresponder ao nosso servidor.
    if game_addr and not game_addr.startswith(f"{SCUM_HOST}:"):
        raise ValueError("Query.Games retornou outro servidor")
    if query_addr and not query_addr.startswith(f"{SCUM_HOST}:"):
        raise ValueError("Query.Games retornou outra Query")

    return {
        "online": True,
        "players": players,
        "max_players": max_players,
        "map": "",
        "version": version,
        "gametime": gametime,
        "ping": None,
        "source": "Query.Games (página pública)",
        # Última leitura = momento da consulta feita pelo próprio bot (Brasília).
        "fetched_at": datetime.now().strftime("%d/%m/%Y %H:%M:%S") or "disponível no Query.Games",
        "server_name": server_name,
        "stale": False,
    }


def _parse_query_games_api(data):
    if not isinstance(data, dict):
        raise ValueError("Resposta inválida da API Query.Games")

    server = data
    if "server" in data and isinstance(data["server"], dict):
        server = data["server"]

    if server.get("id") and int(server["id"]) != QUERY_GAMES_SERVER_ID:
        raise ValueError("API retornou outro servidor")

    return {
        "online": bool(server.get("online", False)),
        "players": int(server.get("players", 0)),
        "max_players": int(server.get("max_players", 0)),
        "map": server.get("map") or "",
        "version": server.get("version") or "",
        "gametime": server.get("gametime") or "",
        "ping": None,
        "source": "Query.Games API",
        "fetched_at": datetime.fromtimestamp(
            int(server["fetched_at"]), tz=timezone.utc
        ).strftime("%d/%m/%Y %H:%M UTC") if server.get("fetched_at") else "",
        "server_name": server.get("name") or SERVER_NAME,
        "stale": False,
    }


def _query_query_games_sync():
    """
    Query.Games:
    1) API by address when an API key is configured.
    2) Public Query.Games page searched by the NEW game address.
    The old numeric Server ID is intentionally not used because migration
    changed the server registration.
    """
    addr = f"{SCUM_HOST}:{SCUM_GAME_PORT}"
    query_addr = f"{SCUM_HOST}:{SCUM_QUERY_PORT}"

    if QUERY_GAMES_API_KEY:
        try:
            resp = requests.get(
                QUERY_GAMES_API_URL,
                params={"addr": addr},
                headers={"Authorization": f"Bearer {QUERY_GAMES_API_KEY}"},
                timeout=10,
            )
            resp.raise_for_status()
            data = resp.json()
            parsed = _parse_query_games_api(data)
            if parsed:
                return parsed
        except Exception as exc:
            print("SCUM Query.Games API ERROR:", type(exc).__name__, exc)

        try:
            resp = requests.get(
                QUERY_GAMES_API_URL,
                params={"addr": query_addr},
                headers={"Authorization": f"Bearer {QUERY_GAMES_API_KEY}"},
                timeout=10,
            )
            resp.raise_for_status()
            data = resp.json()
            parsed = _parse_query_games_api(data)
            if parsed:
                return parsed
        except Exception as exc:
            print("SCUM Query.Games API QUERY-ADDR ERROR:", type(exc).__name__, exc)

    # Public page search by the new IP. This avoids the obsolete old Server ID.
    search_url = "https://query.games/servers/scum"
    for search_term in (addr, SCUM_HOST):
        try:
            resp = requests.get(
                search_url,
                params={"search": search_term},
                timeout=12,
                headers={"User-Agent": "Mozilla/5.0"},
            )
            resp.raise_for_status()
            parsed = _parse_query_games_html(resp.text)
            if parsed:
                return parsed
        except Exception as exc:
            print("SCUM Query.Games WEB ERROR:", type(exc).__name__, exc)

    raise ValueError("Query.Games ainda não encontrou o novo endereço do servidor")

async def query_query_games():
    return await asyncio.to_thread(_query_query_games_sync)


def _ftp_scum_log_heartbeat_unsafe():
    """Consulta diretamente o SCUM.log por FTP.

    O status ONLINE/OFFLINE não depende de Query.Games.
    O próprio arquivo SCUM.log é usado como heartbeat:
    - MDTM = última alteração registrada pelo servidor.
    - SIZE = confirmação de que o arquivo existe e está acessível.
    Se o arquivo estiver sendo atualizado recentemente, consideramos o
    servidor ativo. Se estiver muito antigo, consideramos offline.
    """
    global SCUM_FTP_ACTIVE_LOG_PATH

    if not _ensure_ftp_credentials():
        return {
            "ok": False,
            "online": None,
            "players": None,
            "max_players": 48,
            "log_mdtm": None,
            "log_age": None,
            "path": None,
            "error": "credenciais FTP indisponíveis",
        }

    ftp = None
    paths = ["/SCUM/Saved/Logs"]
    # Preserva fallback caso a hospedagem altere o diretório.
    if SCUM_FTP_ACTIVE_LOG_PATH and SCUM_FTP_ACTIVE_LOG_PATH not in paths:
        paths.append(SCUM_FTP_ACTIVE_LOG_PATH)
    for candidate in SCUM_FTP_LOG_PATH_CANDIDATES:
        if candidate and candidate not in paths:
            paths.append(candidate)

    now_utc = datetime.now(timezone.utc)
    last_error = ""

    for path in paths:
        try:
            ftp = _ftp_connect()
            if ftp is None:
                last_error = "não foi possível conectar ao FTP"
                break

            ftp.cwd(path)

            size = ftp.size("SCUM.log")
            if size is None:
                raise RuntimeError("SIZE do SCUM.log não retornou valor")

            # Nem todo FTP da hospedagem aceita MDTM corretamente.
            # Por isso MDTM é apenas uma informação auxiliar.
            # A confirmação principal passa a ser a leitura REAL do SCUM.log.
            mdtm_text = ""
            log_dt = None
            try:
                mdtm = ftp.sendcmd("MDTM SCUM.log")
                mdtm_text = mdtm.split()[-1].strip()
                try:
                    log_dt = datetime.strptime(
                        mdtm_text, "%Y%m%d%H%M%S"
                    ).replace(tzinfo=timezone.utc)
                except ValueError:
                    log_dt = None
            except Exception as mdtm_error:
                _cargodrop_diag(
                    f"STATUS FTP: MDTM indisponível, usando conteúdo do log | "
                    f"{type(mdtm_error).__name__}: {mdtm_error}"
                )

            # Baixa somente o final do SCUM.log. Isso evita depender de MDTM
            # e ainda permite confirmar que o servidor está realmente gravando.
            tail_size = min(int(size), 256 * 1024)
            buffer = BytesIO()

            try:
                ftp.voidcmd("TYPE I")
            except Exception:
                pass

            rest = max(0, int(size) - tail_size)
            ftp.retrbinary(
                "RETR SCUM.log",
                buffer.write,
                blocksize=8192,
                rest=rest if rest > 0 else None
            )

            raw_tail = buffer.getvalue()
            text_tail = _decode_scum_log(raw_tail)

            # Timestamps do SCUM: [2026.09.12-09.30.15...]
            stamps = re.findall(
                r"(?:^|\n)\[?(\d{4}\.\d{2}\.\d{2}-\d{2}\.\d{2}\.\d{2})",
                text_tail
            )

            content_dt = None
            if stamps:
                try:
                    content_dt = datetime.strptime(
                        stamps[-1], "%Y.%m.%d-%H.%M.%S"
                    ).replace(tzinfo=timezone.utc)
                except ValueError:
                    content_dt = None

            # Usa a evidência mais recente disponível.
            heartbeat_dt = content_dt or log_dt

            if heartbeat_dt is None:
                raise ValueError(
                    "SCUM.log acessível, mas não foi possível encontrar "
                    "timestamp no final do arquivo"
                )

            age = max(0.0, (now_utc - heartbeat_dt).total_seconds())

            # 5 minutos de margem.
            online = age <= 300

            SCUM_FTP_ACTIVE_LOG_PATH = path

            _cargodrop_diag(
                f"STATUS FTP SCUM.log | PATH={path} | SIZE={size} | "
                f"MDTM={mdtm_text or 'indisponível'} | "
                f"TIMESTAMP_LOG={stamps[-1] if stamps else 'indisponível'} | "
                f"idade={age:.0f}s | "
                f"{'ONLINE' if online else 'OFFLINE'}"
            )

            return {
                "ok": True,
                "online": online,
                "players": None,
                "max_players": 48,
                "log_mdtm": heartbeat_dt,
                "log_age": age,
                "path": path,
                "error": "",
            }

        except Exception as error:
            last_error = f"{type(error).__name__}: {error}"
            print(f"STATUS HEARTBEAT FTP FALHOU | PATH={path} | {last_error}")
            continue
    print(f"STATUS HEARTBEAT SEM LEITURA | {last_error}")
    return {
        "ok": False,
        "online": None,
        "players": None,
        "max_players": 48,
        "log_mdtm": None,
        "log_age": None,
        "path": None,
        "error": last_error or "SCUM.log não encontrado no FTP",
    }


LOGIN_PLAYERS_LOG_PATTERN = re.compile(
    r"\b(?P<steamid>\d{10,20}):(?P<name>.*?)\(\d+\)"
    r"(?:['\"])?\s+logged\s+(?P<action>in|out)\b",
    re.IGNORECASE,
)
LOGIN_GAME_VERSION_RE = re.compile(
    r"Game\s+version:\s*(?P<version>[0-9.]+)",
    re.IGNORECASE,
)
LOGIN_LOG_FILENAME_RE = re.compile(r"^login(?:_[^/\\]*)?\.log$", re.IGNORECASE)


# TURISTA DA ILHA — sessões concluídas a partir do login.log já lido pelo Status.
# Persistência no mesmo SQLite do Railway; nenhuma conexão FTP adicional.
def _tourist_ingest_login(text):
    events = []
    stamp = None
    for line in text.splitlines():
        m = re.search(r"(?:^|\s|\[)(\d{4}[.-]\d{2}[.-]\d{2}[-_]\d{2}[.:]\d{2}[.:]\d{2})", line)
        if m:
            raw = re.sub(r'[^0-9]', '', m.group(1))
            try:
                stamp = datetime.strptime(raw, '%Y%m%d%H%M%S').replace(tzinfo=timezone.utc)
            except ValueError:
                stamp = None
        match = LOGIN_PLAYERS_LOG_PATTERN.search(line)
        if match and stamp:
            events.append((stamp.isoformat(), match.group('steamid'),
                           re.sub(r'\s+', ' ', match.group('name').strip())[:100],
                           match.group('action').lower()))
    if not events:
        return 0
    with _island_db_connect() as db:
        db.execute('''CREATE TABLE IF NOT EXISTS tourist_sessions (
            steam TEXT PRIMARY KEY, name TEXT NOT NULL, start_at TEXT NOT NULL)''')
        db.execute('''CREATE TABLE IF NOT EXISTS tourist_records (
            steam TEXT PRIMARY KEY, name TEXT NOT NULL, longest_seconds INTEGER NOT NULL DEFAULT 0,
            total_seconds INTEGER NOT NULL DEFAULT 0, completed INTEGER NOT NULL DEFAULT 0)''')
        db.execute('''CREATE TABLE IF NOT EXISTS tourist_seen (
            event_key TEXT PRIMARY KEY)''')
        count = 0
        for stamp, steam, name, action in events:
            key = hashlib.sha256(f'{stamp}|{steam}|{action}'.encode()).hexdigest()
            if not db.execute('INSERT OR IGNORE INTO tourist_seen VALUES (?)', (key,)).rowcount:
                continue
            count += 1
            previous = db.execute('SELECT start_at FROM tourist_sessions WHERE steam=?', (steam,)).fetchone()
            if action == 'in':
                # Duplicated login without logout: previous session cannot be verified.
                db.execute('INSERT OR REPLACE INTO tourist_sessions VALUES (?,?,?)', (steam,name,stamp))
            elif previous:
                duration = int((datetime.fromisoformat(stamp)-datetime.fromisoformat(previous[0])).total_seconds())
                # Ignore inconsistent clock, missing logout and implausibly long sessions.
                if 0 < duration <= 86400:
                    db.execute('''INSERT INTO tourist_records VALUES (?,?,?,?,1)
                        ON CONFLICT(steam) DO UPDATE SET name=excluded.name,
                        longest_seconds=MAX(tourist_records.longest_seconds,excluded.longest_seconds),
                        total_seconds=tourist_records.total_seconds+excluded.total_seconds,
                        completed=tourist_records.completed+1''', (steam,name,duration,duration))
                db.execute('DELETE FROM tourist_sessions WHERE steam=?', (steam,))
    # Reaproveita os mesmos eventos já lidos; falhas deste módulo não afetam o Status.
    try:
        _access_ingest(events)
    except (sqlite3.Error, OSError, ValueError) as error:
        print(f'ACESSOS: armazenamento indisponível | {type(error).__name__}: {error}')
    return count


def _tourist_best():
    with _island_db_connect() as db:
        db.execute('''CREATE TABLE IF NOT EXISTS tourist_records (
            steam TEXT PRIMARY KEY, name TEXT NOT NULL, longest_seconds INTEGER NOT NULL DEFAULT 0,
            total_seconds INTEGER NOT NULL DEFAULT 0, completed INTEGER NOT NULL DEFAULT 0)''')
        return db.execute('SELECT name,longest_seconds,completed FROM tourist_records WHERE longest_seconds>0 ORDER BY longest_seconds DESC,steam LIMIT 1').fetchone()


def _parse_login_log_players(text: str):
    """Reconstrói os jogadores online a partir do login log do SCUM.

    Aceita as variações reais do SCUM, inclusive a aspa entre ')' e
    'logged in/out'. Mantém o último evento de cada SteamID.
    """
    active = {}
    version = ""
    last_event_stamp = ""
    total_events = 0

    for line in text.splitlines():
        if not version:
            vm = LOGIN_GAME_VERSION_RE.search(line)
            if vm:
                version = vm.group("version").strip()

        stamp_match = re.search(
            r"(?:^|\s|\[)(?P<stamp>\d{4}[.-]\d{2}[.-]\d{2}[-_]\d{2}[.:]\d{2}[.:]\d{2})",
            line,
        )
        if stamp_match:
            last_event_stamp = stamp_match.group("stamp")

        # SteamID:Nome(26)' logged in / logged out
        match = LOGIN_PLAYERS_LOG_PATTERN.search(line)
        if not match:
            # Fallback mais permissivo para mudanças de formatação do SCUM.
            match = re.search(
                r"(?P<steamid>\d{10,20}):(?P<name>.*?)\(\d+\)\s*['\"]?\s*logged\s+(?P<action>in|out)\b",
                line,
                re.IGNORECASE,
            )
        if not match:
            continue

        total_events += 1
        steamid = match.group("steamid").strip()
        name = re.sub(r"\s+", " ", match.group("name").strip())
        action = match.group("action").lower()

        if action == "in":
            active[steamid] = name
        else:
            active.pop(steamid, None)

    # A leitura existente do Status alimenta o histórico, sem nova leitura FTP.
    try:
        _tourist_ingest_login(text)
    except (sqlite3.Error, OSError, ValueError) as error:
        print(f'TURISTA: importação do login.log indisponível | {type(error).__name__}: {error}')

    return {
        "players": len(active),
        "player_names": sorted(active.values(), key=str.casefold),
        "steam_ids": sorted(active),
        "version": version,
        "last_event_stamp": last_event_stamp,
        "events": total_events,
    }


def _ftp_read_login_players_unsafe():
    """Lê o log de login mais recente diretamente pelo mesmo FTP do SCUM."""
    global SCUM_FTP_ACTIVE_LOG_PATH

    ftp = _ftp_connect()
    if ftp is None:
        return {
            "ok": False, "players": None, "max_players": 48,
            "version": "", "player_names": [], "events": 0,
            "login_file": "", "error": "FTP indisponível",
        }

    paths = []
    if SCUM_FTP_ACTIVE_LOG_PATH:
        paths.append(SCUM_FTP_ACTIVE_LOG_PATH)
    paths.extend(SCUM_FTP_LOG_PATH_CANDIDATES)
    paths.extend([
        "/SCUM/Saved/SaveFiles/Logs",
        "/SCUM/Saved/Logs",
        "/1586712/SCUM/Saved/SaveFiles/Logs",
        "/1586712/SCUM/Saved/Logs",
    ])

    last_error = ""
    for path in dict.fromkeys(p for p in paths if p):
        try:
            ftp.cwd(path)
            names = [x.rsplit("/", 1)[-1] for x in ftp.nlst()]
            login_files = [
                n for n in names
                if LOGIN_LOG_FILENAME_RE.match(n)
            ]
            if not login_files:
                continue

            # Prioriza nomes com data/hora no próprio nome; caso contrário,
            # usa o MDTM do FTP para escolher o arquivo mais novo.
            def name_key(n):
                m = re.search(r"(\d{4}[.-]\d{2}[.-]\d{2}[-_]\d{2}[.:]\d{2}[.:]\d{2})", n)
                return m.group(1) if m else ""

            dated = [n for n in login_files if name_key(n)]
            filename = max(dated, key=name_key) if dated else login_files[-1]

            if not dated and len(login_files) > 1:
                stamped = []
                for n in login_files:
                    try:
                        raw = ftp.sendcmd(f"MDTM {n}").split()[-1]
                        stamped.append((raw, n))
                    except Exception:
                        pass
                if stamped:
                    filename = max(stamped, key=lambda x: x[0])[1]

            ftp.voidcmd("TYPE I")
            size = ftp.size(filename)
            if size is None:
                raise RuntimeError(f"SIZE não retornou valor para {filename}")

            # O estado online depende do histórico de log. Tenta ler o arquivo
            # inteiro; só limita em 25 MB para proteger o bot de arquivo anormal.
            max_bytes = 25 * 1024 * 1024
            take = min(int(size), max_bytes)
            rest = max(0, int(size) - take)
            buffer = BytesIO()
            ftp.retrbinary(
                "RETR " + filename,
                buffer.write,
                blocksize=8192,
                rest=rest,
            )
            text = _decode_scum_log(buffer.getvalue())
            parsed = _parse_login_log_players(text)
            parsed.update({
                "ok": True,
                "max_players": 48,
                "login_file": filename,
                "path": path,
                "size": int(size),
                "error": "",
            })

            _cargodrop_diag(
                f"STATUS PLAYERS FTP | PATH={path} | FILE={filename} | "
                f"SIZE={size} | eventos={parsed['events']} | "
                f"jogadores={parsed['players']}/48 | "
                f"nomes={', '.join(parsed['player_names']) or 'nenhum'} | "
                f"versão={parsed['version'] or 'indisponível'}"
            )
            return parsed

        except Exception as error:
            last_error = f"{type(error).__name__}: {error}"
            continue

    return {
        "ok": False, "players": None, "max_players": 48,
        "version": "", "player_names": [], "events": 0,
        "login_file": "",
        "error": last_error or "Nenhum login*.log encontrado no FTP",
    }



# ============================================================
# PROTEÇÃO DE CONCORRÊNCIA DO FTP
# ============================================================
# As rotinas abaixo reutilizam a mesma sessão FTP. O lock impede
# que duas tasks usem ftplib ao mesmo tempo e corrompam a sessão.
def _ftp_scum_log_heartbeat(*args, **kwargs):
    with SCUM_FTP_IO_LOCK:
        return _ftp_scum_log_heartbeat_unsafe(*args, **kwargs)

def _ftp_read_login_players(*args, **kwargs):
    with SCUM_FTP_IO_LOCK:
        return _ftp_read_login_players_unsafe(*args, **kwargs)

def _ftp_find_kill_path(*args, **kwargs):
    with SCUM_FTP_IO_LOCK:
        return _ftp_find_kill_path_unsafe(*args, **kwargs)

def _ftp_list_event_kill_files(*args, **kwargs):
    with SCUM_FTP_IO_LOCK:
        return _ftp_list_event_kill_files_unsafe(*args, **kwargs)

def _ftp_download_file(*args, **kwargs):
    with SCUM_FTP_IO_LOCK:
        return _ftp_download_file_unsafe(*args, **kwargs)

async def query_scum_server():
    """Status 100% baseado nos logs do servidor via FTP.

    Fontes:
      - SCUM.log -> heartbeat / ONLINE-OFFLINE
      - login_*.log -> jogadores online + versão do jogo

    A2S e Query.Games ficam fora do Status para evitar depender de consultas
    externas que já demonstraram não responder para este servidor.
    """
    global LAST_SCUM_STATUS, LAST_SCUM_STATUS_AT, LIVE_ONLINE_STEAM_IDS, LIVE_ONLINE_CHECKED_AT, LIVE_LOGIN_LOG_STARTED_AT

    # Status lê SCUM.log + login.log como uma operação única.
    # Isso impede Kill Feed/Cargo Drop de entrar no meio da consulta do Status
    # e reduz o risco de uma sessão FTP compartilhada ficar em estado inconsistente.
    def _read_status_bundle():
        with SCUM_FTP_IO_LOCK:
            ftp_data = _ftp_scum_log_heartbeat_unsafe()
            login_data = _ftp_read_login_players_unsafe()
            return ftp_data, login_data

    ftp_data, login_data = await asyncio.to_thread(_read_status_bundle)
    if not ftp_data["ok"]:
        print(f"STATUS FTP: primeira tentativa falhou: {ftp_data.get('error')}; repetindo consulta")
        await asyncio.sleep(2)
        ftp_data, login_data = await asyncio.to_thread(_read_status_bundle)
        if not ftp_data["ok"]:
            print(f"STATUS FTP: segunda tentativa falhou: {ftp_data.get('error')}")

    if ftp_data["ok"]:
        online = bool(ftp_data["online"])
        players = login_data.get("players") if login_data.get("ok") else None
        version = login_data.get("version", "") if login_data.get("ok") else ""
        player_names = login_data.get("player_names", []) if login_data.get("ok") else []

        data = {
            "online": online,
            "players": players if players is not None else 0,
            "max_players": 48,
            "map": "SCUM",
            "version": version,
            "player_names": player_names,
            "gametime": "",
            "ping": None,
            "source": (
                "FTP • SCUM.log + login.log"
                if login_data.get("ok")
                else "FTP • SCUM.log"
            ),
            "fetched_at": datetime.now(BRASILIA_TZ).strftime("%d/%m/%Y %H:%M:%S"),
            "server_name": SERVER_NAME,
            "stale": False,
            "log_age": ftp_data["log_age"],
        }

        if online and login_data.get("ok"):
            LIVE_ONLINE_STEAM_IDS = set(login_data.get("steam_ids", []))
            LIVE_ONLINE_CHECKED_AT = datetime.now(timezone.utc)
            # A data no nome do arquivo identifica um novo ciclo do SCUM.
            # Nao presumir reset se o nome nao possuir timestamp valido.
            filename = login_data.get("login_file", "")
            match = re.search(r"login_(\d{8})(\d{6})\.log$", filename, re.IGNORECASE)
            if match:
                try:
                    LIVE_LOGIN_LOG_STARTED_AT = datetime.strptime(
                        match.group(1) + match.group(2), "%Y%m%d%H%M%S"
                    ).replace(tzinfo=timezone.utc)
                except ValueError:
                    LIVE_LOGIN_LOG_STARTED_AT = None
            else:
                LIVE_LOGIN_LOG_STARTED_AT = None
        else:
            LIVE_ONLINE_STEAM_IDS = set()
            LIVE_ONLINE_CHECKED_AT = None
            LIVE_LOGIN_LOG_STARTED_AT = None
        LAST_SCUM_STATUS = data.copy()
        LAST_SCUM_STATUS_AT = datetime.now(BRASILIA_TZ)

        print(
            f"SCUM STATUS FTP DIRETO: "
            f"{'ONLINE' if online else 'OFFLINE'} | "
            f"players={data['players']}/{data['max_players']} | "
            f"version={version or 'indisponível'} | "
            f"log_age={ftp_data['log_age']:.0f}s"
        )
        return data

    if LAST_SCUM_STATUS:
        data = LAST_SCUM_STATUS.copy()
        data["stale"] = True
        data["source"] = (
            f"{data.get('source', 'FTP')} • última leitura válida"
        )
        if LAST_SCUM_STATUS_AT:
            data["fetched_at"] = LAST_SCUM_STATUS_AT.strftime(
                "%d/%m/%Y %H:%M:%S"
            )
        return data

    return {
        "online": False,
        "players": 0,
        "max_players": 48,
        "map": "SCUM",
        "version": "",
        "player_names": [],
        "gametime": "",
        "ping": None,
        "source": "FTP • SCUM.log sem resposta inicial",
        "fetched_at": "",
        "server_name": SERVER_NAME,
        "stale": False,
        "log_age": None,
    }


async def find_or_create_status_channel(guild):
    inicio = discord.utils.get(
        guild.categories,
        name="🏝️ INÍCIO"
    )

    if inicio is None:
        return None

    channel = find_text_channel_anywhere(
        guild,
        STATUS_CHANNEL_NAME
    )

    if channel is None:
        channel = await get_or_create_text(
            guild,
            inicio,
            STATUS_CHANNEL_NAME,
            topic="Status automático do servidor SCUM"
        )
    else:
        await move_channel_to_category(
            channel,
            inicio,
            position=1
        )

    return channel


STATUS_PANEL_UPDATE_LOCK = asyncio.Lock()

async def update_status_panel(guild):
    async with STATUS_PANEL_UPDATE_LOCK:
        return await _update_status_panel_serial(guild)

async def _update_status_panel_serial(guild):
    channel = await find_or_create_status_channel(guild)

    if channel is None:
        return

    data = await query_scum_server()
    embed = format_scum_status_embed(data)

    panel = None

    try:
        async for msg in channel.history(limit=50):
            if (
                msg.author == bot.user
                and msg.embeds
                and msg.embeds[0].title == "📡 STATUS DO SERVIDOR"
            ):
                panel = msg
                break

        if panel:
            await panel.edit(embed=embed)
        else:
            await channel.send(embed=embed)

    except (
        discord.Forbidden,
        discord.HTTPException
    ) as error:
        print(f"STATUS DISCORD FALHA | {type(error).__name__}: {error}")

    if data["online"]:
        await bot.change_presence(
            activity=discord.Game(
                name=(
                    f"SCUM | "
                    f"{data['players'] if data.get('players') is not None else '—'}/{data['max_players']}"
                )
            )
        )
    else:
        await bot.change_presence(
            activity=discord.Game(
                name="SCUM | CONSULTANDO..."
            )
        )


async def scum_status_loop():
    await bot.wait_until_ready()

    while not bot.is_closed():
        for guild in bot.guilds:
            try:
                await update_status_panel(guild)
            except Exception as error:
                print(
                    f"ERRO STATUS {guild.name}: "
                    f"{type(error).__name__}: {error}"
                )

        await asyncio.sleep(
            SCUM_STATUS_UPDATE_SECONDS
        )


# ============================================================
# KILL FEED — LEITURA DOS LOGS
# ============================================================

KILL_EVENT_RE = re.compile(
    r"Died:\s*(?P<victim>.*?)\s*\((?P<victim_id>\d+)\),\s*"
    r"Killer:\s*(?P<killer>.*?)\s*\((?P<killer_id>[^)]*)\)\s*"
    # SCUM 1.3.3.4 usa S[KillerLoc; versões anteriores podem usar S:[KillerLoc.
    r"Weapon:\s*(?P<weapon>.*?)\s*S\s*:?\s*\[KillerLoc\s*:\s*"
    r"(?P<kx>-?\d+(?:\.\d+)?),\s*(?P<ky>-?\d+(?:\.\d+)?),\s*(?P<kz>-?\d+(?:\.\d+)?)\s+"
    r"VictimLoc\s*:\s*(?P<vx>-?\d+(?:\.\d+)?),\s*(?P<vy>-?\d+(?:\.\d+)?),\s*(?P<vz>-?\d+(?:\.\d+)?)\s*,\s*"
    r"Distance:\s*(?P<distance>[-\d.]+)\s*m\]"
)

KILL_TIMESTAMP_RE = re.compile(
    r"^(?:\[)?(?P<stamp>\d{4}\.\d{2}\.\d{2}-\d{2}\.\d{2}\.\d{2})(?:[:\]])?"
)


def _decode_scum_log(raw: bytes) -> str:
    for encoding in ("utf-16", "utf-8", "cp1252"):
        try:
            return raw.decode(encoding).replace("\x00", "")
        except UnicodeDecodeError:
            continue
    return raw.decode("utf-8", errors="replace").replace("\x00", "")


def _load_killfeed_state():
    try:
        with open(SCUM_KILLFEED_STATE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            raise ValueError("estado inválido")
        data.setdefault("version", 3)
        data.setdefault("seen", [])
        return data
    except (FileNotFoundError, json.JSONDecodeError, OSError, ValueError):
        return {"version": 3, "seen": []}


def _save_killfeed_state(state):
    os.makedirs(os.path.dirname(os.path.abspath(SCUM_KILLFEED_STATE_FILE)), exist_ok=True)
    temp = f"{SCUM_KILLFEED_STATE_FILE}.tmp"
    with open(temp, "w", encoding="utf-8") as f:
        json.dump(state, f, ensure_ascii=False, indent=2)
    os.replace(temp, SCUM_KILLFEED_STATE_FILE)


def _event_key(event):
    """Chave estável do acontecimento, independente do arquivo em que ele esteja."""
    base = "|".join([
        event.get("stamp", ""),
        event.get("victim_id", ""),
        event.get("victim", ""),
        event.get("killer_id", ""),
        event.get("killer", ""),
        event.get("weapon", ""),
        f"{event.get('distance', 0.0):.2f}",
        f"{event.get('vx', 0.0):.2f}",
        f"{event.get('vy', 0.0):.2f}",
        f"{event.get('vz', 0.0):.2f}",
    ])
    return hashlib.sha256(base.encode("utf-8", errors="ignore")).hexdigest()


def _parse_kill_events(text: str):
    events = []

    for line in text.splitlines():
        if "Died:" not in line or "Killer:" not in line or "Weapon:" not in line:
            continue

        match = KILL_EVENT_RE.search(line)
        if not match:
            continue

        stamp_match = KILL_TIMESTAMP_RE.search(line)
        stamp = stamp_match.group("stamp") if stamp_match else ""
        raw = match.groupdict()

        try:
            event_dt = datetime.strptime(
                stamp, "%Y.%m.%d-%H.%M.%S"
            ) if stamp else None
        except ValueError:
            event_dt = None

        def fnum(value):
            try:
                return float(value)
            except (TypeError, ValueError):
                return 0.0

        event = {
            "stamp": stamp,
            "event_dt": event_dt,
            "victim": raw["victim"].strip(),
            "victim_id": raw["victim_id"].strip(),
            "killer": raw["killer"].strip(),
            "killer_id": raw["killer_id"].strip(),
            "weapon": raw["weapon"].strip(),
            "kx": fnum(raw["kx"]),
            "ky": fnum(raw["ky"]),
            "kz": fnum(raw["kz"]),
            "vx": fnum(raw["vx"]),
            "vy": fnum(raw["vy"]),
            "vz": fnum(raw["vz"]),
            "distance": fnum(raw["distance"]),
        }
        event["key"] = _event_key(event)
        events.append(event)

    return events


def _close_persistent_ftp():
    global SCUM_FTP_CONNECTION
    ftp = SCUM_FTP_CONNECTION
    SCUM_FTP_CONNECTION = None
    if ftp is not None:
        try:
            ftp.quit()
        except Exception:
            try:
                ftp.close()
            except Exception:
                pass


def _ftp_connect():
    """Gerenciador único de sessão FTP do PRIMEIRO MUNDO.

    Regra V21:
      - conecta uma vez;
      - STATUS/KILL FEED/CARGO DROP reutilizam a mesma sessão;
      - antes de usar, testa a sessão com NOOP;
      - só abre login novamente se a sessão tiver caído;
      - não fica relendo o FileZilla a cada ciclo;
      - após uma falha de conexão, respeita cooldown antes de tentar de novo.
    """
    global SCUM_FTP_HOST, SCUM_FTP_USER, SCUM_FTP_PASS, SCUM_FTP_CONNECTION
    global SCUM_FTP_LAST_CONNECT_ATTEMPT, SCUM_FTP_LAST_CONNECT_ERROR

    # 1) Sessão existente: apenas valida. Se estiver viva, não faz novo login.
    if SCUM_FTP_CONNECTION is not None:
        try:
            with SCUM_FTP_IO_LOCK:
                SCUM_FTP_CONNECTION.voidcmd("NOOP")
            return SCUM_FTP_CONNECTION
        except Exception as error:
            print(
                f"FTP: sessão perdida ({type(error).__name__}: {error}). "
                "Será reconectada quando o cooldown permitir."
            )
            logging.getLogger('primeiro_mundo.ftp').error('Sessão FTP perdida: %s: %s', type(error).__name__, error)
            _close_persistent_ftp()

    # 2) Se ainda estamos dentro do cooldown de uma falha REAL de conexão,
    # não martelamos o servidor.
    now_mono = time.monotonic()
    if (
        SCUM_FTP_LAST_CONNECT_ERROR
        and now_mono - SCUM_FTP_LAST_CONNECT_ATTEMPT < SCUM_FTP_RECONNECT_COOLDOWN_SECONDS
    ):
        return None

    # 3) Resolve credenciais SOMENTE quando não temos uma sessão.
    # Mantém a mesma lógica validada da V5: .env/ambiente primeiro e
    # FileZilla apenas como fallback quando falta senha.
    if not all([SCUM_FTP_HOST, SCUM_FTP_USER, SCUM_FTP_PASS]):
        _ensure_ftp_credentials()

    if not all([SCUM_FTP_HOST, SCUM_FTP_USER, SCUM_FTP_PASS]):
        SCUM_FTP_LAST_CONNECT_ERROR = "credenciais FTP indisponíveis"
        SCUM_FTP_LAST_CONNECT_ATTEMPT = time.monotonic()
        return None

    SCUM_FTP_LAST_CONNECT_ATTEMPT = time.monotonic()
    try:
        ftp = ftplib.FTP()
        ftp.connect(SCUM_FTP_HOST, SCUM_FTP_PORT, timeout=20)
        ftp.login(SCUM_FTP_USER, SCUM_FTP_PASS)
        ftp.set_pasv(True)
        SCUM_FTP_CONNECTION = ftp
        SCUM_FTP_LAST_CONNECT_ERROR = ""
        print(
            f"FTP: CONEXÃO ESTABELECIDA | host={SCUM_FTP_HOST} | "
            f"porta={SCUM_FTP_PORT} | sessão persistente V21"
        )
        _cargodrop_diag("FTP V21: conexão estabelecida; sessão será reutilizada.")
        return ftp
    except Exception as error:
        _close_persistent_ftp()
        SCUM_FTP_LAST_CONNECT_ERROR = f"{type(error).__name__}: {error}"
        print(f"FTP CONEXÃO ERRO: {SCUM_FTP_LAST_CONNECT_ERROR}")
        _cargodrop_diag(f"FTP V21: falha de conexão | {SCUM_FTP_LAST_CONNECT_ERROR}")
        return None


def _ftp_find_kill_path_unsafe():
    global SCUM_FTP_ACTIVE_LOG_PATH

    if SCUM_FTP_ACTIVE_LOG_PATH:
        return SCUM_FTP_ACTIVE_LOG_PATH

    ftp = None
    try:
        ftp = _ftp_connect()
        if ftp is None:
            print("KILL FEED: credenciais FTP não configuradas.")
            return None

        for path in SCUM_FTP_LOG_PATH_CANDIDATES:
            try:
                ftp.cwd(path)
                names = ftp.nlst()
                kill_files = [
                    name.rsplit("/", 1)[-1]
                    for name in names
                    if name.rsplit("/", 1)[-1].lower().startswith("kill_")
                    and name.rsplit("/", 1)[-1].lower().endswith(".log")
                ]
                if kill_files:
                    SCUM_FTP_ACTIVE_LOG_PATH = path
                    print(
                        f"KILL FEED: pasta encontrada: {path} | "
                        f"arquivos: {len(kill_files)}"
                    )
                    return path
            except Exception:
                continue

        print(
            "KILL FEED: não encontrei kill_*.log nas pastas FTP testadas."
        )
        return None
    except Exception as error:
        print(
            f"ERRO CONEXÃO FTP KILL FEED: {type(error).__name__}: {error}"
        )
        return None
    finally:
        # _ftp_connect() devolve a sessão persistente compartilhada.
        # Não fechamos aqui, pois Kill Feed/Cargo Drop/Status reutilizam a mesma sessão.
        pass


def _ftp_list_event_kill_files_unsafe():
    global SCUM_FTP_ACTIVE_LOG_PATH

    if not all([SCUM_FTP_HOST, SCUM_FTP_USER, SCUM_FTP_PASS]):
        return []

    ftp = None
    try:
        ftp = _ftp_connect()
        if ftp is None:
            return []

        paths = []
        if SCUM_FTP_ACTIVE_LOG_PATH:
            paths.append(SCUM_FTP_ACTIVE_LOG_PATH)
        paths.extend(
            path for path in SCUM_FTP_LOG_PATH_CANDIDATES
            if path not in paths
        )

        for path in paths:
            try:
                ftp.cwd(path)
                names = ftp.nlst()
                found = []
                for name in names:
                    base = name.rsplit("/", 1)[-1]
                    if (
                        base.lower().startswith("kill_")
                        and base.lower().endswith(".log")
                    ):
                        found.append(base)

                if found:
                    SCUM_FTP_ACTIVE_LOG_PATH = path
                    found.sort()
                    print(
                        f"KILL FEED FTP: {path} | {len(found)} arquivo(s)"
                    )
                    return found
            except Exception:
                continue

        print("KILL FEED FTP: nenhum kill_*.log encontrado.")
        return []
    except Exception as error:
        print(
            f"ERRO LISTAGEM FTP KILL FEED: {type(error).__name__}: {error}"
        )
        return []
    finally:
        # Mantém a sessão persistente aberta para os demais módulos FTP.
        pass


def _ftp_download_file_unsafe(filename: str):
    """Baixa um log do SCUM por FTP.

    Kill Feed e Cargo Drop usam o mesmo FTP, mas o SCUM.log pode não estar
    no mesmo caminho que foi descoberto pelo Kill Feed. Por isso, quando o
    arquivo solicitado é SCUM.log, testamos explicitamente todos os caminhos
    candidatos até encontrar o arquivo.
    """
    from io import BytesIO

    if not all([SCUM_FTP_HOST, SCUM_FTP_USER, SCUM_FTP_PASS]):
        return None

    global SCUM_FTP_ACTIVE_LOG_PATH

    if filename.lower() == "scum.log":
        # Caminho confirmado no Railway. Manter alternativas somente como fallback.
        paths = ["/SCUM/Saved/Logs"]
        for candidate in (SCUM_FTP_ACTIVE_LOG_PATH, *SCUM_FTP_LOG_PATH_CANDIDATES):
            if candidate and candidate not in paths:
                paths.append(candidate)
    else:
        path = SCUM_FTP_ACTIVE_LOG_PATH or _ftp_find_kill_path()
        if not path:
            return None
        paths = [path]

    for path in paths:
        ftp = None
        buffer = BytesIO()

        try:
            ftp = _ftp_connect()
            if ftp is None:
                return None

            try:
                ftp.cwd(path)
            except Exception as error:
                print(
                    f"SCUM LOG FTP CAMINHO IGNORADO: {path} | "
                    f"{type(error).__name__}: {error}"
                )
                continue

            try:
                ftp.voidcmd("NOOP")
            except Exception:
                pass

            # Alguns hosts SCUM permitem LIST/RETR, mas bloqueiam SIZE (550 SIZE not allowed).
            # Portanto a leitura não depende de SIZE: tentamos RETR diretamente.
            print(
                f"SCUM LOG FTP: tentando RETR {filename} | PATH={path} | sem SIZE"
            )

            try:
                mdtm = ftp.sendcmd(f"MDTM {filename}")
                print(
                    f"SCUM LOG FTP LEITURA: {filename} | "
                    f"PATH={path} | {mdtm}"
                )
            except Exception:
                pass

            try:
                ftp.voidcmd("TYPE I")
            except Exception:
                pass

            ftp.retrbinary(
                f"RETR {filename}",
                buffer.write,
                blocksize=8192
            )

            raw = buffer.getvalue()

            if filename.lower().startswith("kill_"):
                print(
                    f"KILL FEED FTP RETR OK: {filename} | PATH={path} | bytes={len(raw)}"
                )

            print(
                f"SCUM LOG FTP LEITURA CONCLUÍDA: {filename} | "
                f"PATH={path} | bytes={len(raw)}"
            )
            if filename.lower() == "scum.log":
                _cargodrop_diag(
                    f"FTP SCUM.log OK | PATH={path} | bytes={len(raw)}"
                )

            if filename.lower() == "scum.log":
                SCUM_FTP_ACTIVE_LOG_PATH = path

            return raw

        except Exception as error:
            print(
                f"SCUM LOG FTP ERRO: {filename} | "
                f"PATH={path} | {type(error).__name__}: {error}"
            )
            if filename.lower() == "scum.log":
                _cargodrop_diag(
                    f"FTP SCUM.log ERRO | PATH={path} | {type(error).__name__}: {error}"
                )

    return None


def _format_weapon_name(weapon: str) -> str:
    value = weapon.strip()
    value = value.replace("Weapon_", "")
    value = value.replace("_C", "")
    value = value.replace("[Projectile]", "[Tiro]")
    value = value.replace("[Melee]", "[Corpo a corpo]")
    value = re.sub(r"_\d{10,}$", "", value)
    return value.strip()


def _is_npc(killer_id: str, killer_name: str) -> bool:
    return killer_id.strip().upper() == "NPC" or killer_name.strip().startswith("BP_")


def _short_actor_name(name: str, npc=False) -> str:
    value = name.strip()
    if npc and value.startswith("BP_"):
        value = value[3:]
        value = re.sub(r"_C_\d+$", "", value)
        value = re.sub(r"_C$", "", value)
        value = value.replace("_", " ")
        value = re.sub(r"\s+Lvl\s+", " Lv. ", value, flags=re.I)
        return value.strip()
    return value


