def _weapon_icon_url(weapon: str):
    name = _format_weapon_name(weapon)

    # Normalização dos nomes que podem aparecer no SCUM.log.
    aliases = {
        "AK-47": "AK47",
        "AK 47": "AK47",
        "AK-15": "AK15",
        "AK 15": "AK15",
        "Hunter85": "Hunter85_V2",
        "Hunter 85": "Hunter85_V2",
        "Hunter85_V2": "Hunter85_V2",
        "Hunter 85 V2": "Hunter85_V2",
        "M1911 Gold": "M1911",
        "M1911 Engraved": "M1911",
        "M1911 JayW": "M1911",
        "HS9": "HS-9",
        "HS 9": "HS-9",
        "UMP-45": "UMP45",
        "UMP 45": "UMP45",
        "VHS 2": "VHS2",
        "VHS-2": "VHS2",
        "VHS 2 CT": "VHS2",
        "VHS2 CT": "VHS2",
        "MK-18": "MK18",
        "RPK-74": "RPK-74",
        "RPK 74": "RPK-74",
    }
    name = aliases.get(name, name)

    # Remove o modo de disparo.
    base = re.sub(
        r"\s*\[(?:Tiro|Corpo a corpo|Projectile|Melee)\]\s*$",
        "",
        name,
        flags=re.I
    ).strip()

    # Aceita também IDs de blueprint/item caso algum log futuro os entregue.
    base = re.sub(r"^BP_", "", base, flags=re.I)
    base = re.sub(r"^Weapon_", "", base, flags=re.I)
    base = aliases.get(base, base)

    url = WEAPON_ICON_URLS.get(base)
    if not url or url.endswith('/hash/'):
        return None
    return url


def _build_kill_embed(event):
    npc = _is_npc(event["killer_id"], event["killer"])
    killer_name = _short_actor_name(event["killer"], npc=npc)

    if npc:
        title = "☠️ MORTE — NPC"
        killer_label = "🤖 NPC"
    else:
        title = "⚔️ KILL — PvP"
        killer_label = "🔫 Jogador"

    embed = discord.Embed(
        title=title,
        colour=discord.Colour.red()
    )

    embed.add_field(
        name="💀 Vítima",
        value=f"**{event['victim']}**",
        inline=True
    )
    embed.add_field(
        name=killer_label,
        value=f"**{killer_name}**",
        inline=True
    )
    weapon_display = _format_weapon_name(event["weapon"])
    embed.add_field(
        name="🔫 Arma",
        value=f"`{weapon_display}`",
        inline=True
    )

    # Mostra o ícone real da arma quando temos correspondência.
    # Se não houver ícone cadastrado, o Kill Feed continua exatamente igual,
    # sem quebrar a publicação do evento.
    weapon_icon = _weapon_icon_url(event["weapon"])
    if weapon_icon:
        embed.set_thumbnail(url=weapon_icon)
    embed.add_field(
        name="📏 Distância",
        value=f"`{event['distance']:.2f} m`",
        inline=True
    )
    embed.add_field(
        name="📍 Local",
        value=(
            f"X `{event['vx']:.2f}`\n"
            f"Y `{event['vy']:.2f}`\n"
            f"Z `{event['vz']:.2f}`"
        ),
        inline=True
    )
    embed.add_field(
        name="🕐 Hora",
        value=f"`{_cargodrop_display_time(event["stamp"])} (Brasília)`",
        inline=True
    )
    return embed


async def _read_kill_file(filename):
    try:
        if SCUM_KILLFEED_LOCAL_FILE:
            with open(filename, "rb") as f:
                raw = f.read()
        else:
            raw = await asyncio.to_thread(_ftp_download_file, filename)

        if raw is None:
            return None
        return _decode_scum_log(raw)
    except Exception as error:
        print(
            f"ERRO LEITURA KILL FEED: {type(error).__name__}: {error}"
        )
        return None


async def _cleanup_old_killfeed_panel(channel):
    """Remove somente o antigo painel automático do bot; não toca em mensagens humanas."""
    try:
        async for msg in channel.history(limit=30):
            if msg.author != bot.user:
                continue
            content = (msg.content or "").strip()
            if (
                content.startswith("# ☠️ KILL FEED")
                and (
                    "kill_*.log" in content.lower()
                    or "acontecimentos relacionados" in content.lower()
                    or "sistema automático" in content.lower()
                    or "sistema automatico" in content.lower()
                )
            ):
                await msg.delete()
    except Exception as error:
        print(
            f"KILL FEED: não foi possível limpar painel antigo: "
            f"{type(error).__name__}: {error}"
        )


# KILL FEED COMPLEMENTAR — leitura pelo FTP V21 existente, sem conexão paralela.
# A fonte primária continua sendo kill_*.log; SCUM.log só cobre eventos ausentes.
MYSTERY_TITLES = (
    "💀 MAIS UM FOI DE BASE!", "⚰️ BAIXA MISTERIOSA NA ILHA!",
    "🌴 A ILHA COBROU MAIS UMA VÍTIMA!", "👀 ALGUÉM DEU MOLE!",
    "☠️ SOBREVIVÊNCIA NÃO É PARA AMADORES!", "📢 PLANTÃO PRIMEIRO MUNDO!",
    "🤣 MAIS UM MOMENTO VERGONHOSO!", "🚨 O ADM RECEBEU UMA NOTÍCIA!",
)
MYSTERY_BODIES = (
    "{player} teve seus planos interrompidos pela ilha.",
    "{player} foi promovido a espectador por tempo indeterminado.",
    "{player} resolveu testar a sorte. A sorte não compareceu.",
    "{player} ganhou uma passagem só de ida para o respawn.",
    "{player} encerrou a expedição antes do previsto.",
    "{player} descobriu que confiança demais também dá trabalho.",
    "{player} acaba de entrar para as estatísticas do Primeiro Mundo.",
    "{player} teve um pequeno desentendimento com a sobrevivência. Ela venceu.",
)
MYSTERY_ENDINGS = (
    "Os detalhes serão preservados para evitar vergonha pública. 🤣",
    "O ADM não vai contar onde foi. O vexame já basta! 🤫",
    "O Departamento de Vergonha Alheia arquivou o caso. 📁",
    "Pedimos um minuto de silêncio... ou de risadas. 😂",
    "A família pediu discrição. Os amigos pediram replay. 👀",
    "Quem sabe o que aconteceu, finja que não viu. 🤐",
    "A dignidade já sofreu o suficiente por hoje. 😅",
    "Não perguntaremos o que estava fazendo. Melhor assim! 🤣",
)
MYSTERY_RECENT_COMBINATIONS = []


def _draw_mystery_combination():
    import random
    combinations = len(MYSTERY_TITLES) * len(MYSTERY_BODIES) * len(MYSTERY_ENDINGS)
    available = [i for i in range(combinations) if i not in MYSTERY_RECENT_COMBINATIONS]
    index = random.SystemRandom().choice(available)
    MYSTERY_RECENT_COMBINATIONS.append(index)
    del MYSTERY_RECENT_COMBINATIONS[:-20]
    title_i, rest = divmod(index, len(MYSTERY_BODIES) * len(MYSTERY_ENDINGS))
    body_i, ending_i = divmod(rest, len(MYSTERY_ENDINGS))
    return MYSTERY_TITLES[title_i], MYSTERY_BODIES[body_i], MYSTERY_ENDINGS[ending_i]


SCUM_DEATH_RE = re.compile(r"\[(?P<stamp>\d{4}\.\d{2}\.\d{2}-\d{2}\.\d{2}\.\d{2}):\d+\].*Updating profile deletion because prisoner died\.")
SCUM_PROFILE_RE = re.compile(r"Update profile deletion - userProfileId:\s*(\d+)")
SCUM_POSSESSION_RE = re.compile(r"HandlePossessedBy:\s*\d+,\s*(\d+),\s*(.+?)\s*$")


def _parse_scum_death_candidates(log_text):
    # Mapeamento por identificador de perfil, nunca por jogador padrão.
    # Só usa um nome quando o próprio log associa explicitamente perfil e nome,
    # sem nomes conflitantes para o mesmo perfil na sessão analisada.
    names = {}
    lines = log_text.splitlines()
    for line in lines:
        match = SCUM_POSSESSION_RE.search(line)
        if match:
            profile, name = match.group(1), match.group(2).strip()
            if name:
                names.setdefault(profile, set()).add(name)
    events = []
    for i, line in enumerate(lines):
        match = SCUM_DEATH_RE.search(line)
        if not match:
            continue
        profile = None
        if i + 1 < len(lines):
            profile_match = SCUM_PROFILE_RE.search(lines[i + 1])
            if profile_match:
                profile = profile_match.group(1)
        stamp = match.group('stamp')
        try:
            when = datetime.strptime(stamp, '%Y.%m.%d-%H.%M.%S')
        except ValueError:
            continue
        candidates = names.get(profile, set())
        victim = next(iter(candidates)) if len(candidates) == 1 else None
        events.append({'stamp': stamp, 'event_dt': when, 'profile': profile,
                       'victim': victim, 'key': hashlib.sha256((stamp + '|' + str(profile)).encode()).hexdigest()})
    return events


def _mystery_embed(event):
    title, body, ending = _draw_mystery_combination()
    victim = event.get('victim')
    player = discord.utils.escape_markdown(victim) if victim else 'Um sobrevivente misterioso'
    description = body.format(player='**' + player + '**') + '\n\n' + ending
    embed = discord.Embed(title=title, description=description, colour=discord.Colour.orange())
    embed.set_footer(text='PRIMEIRO MUNDO • Registro complementar de morte')
    return embed


async def _process_scum_death_fallback(channel, detailed_events):
    # A primeira leitura é só referência: nunca republicar mortes antigas.
    # Uma janela de 90 segundos permite ao kill.log receber o evento detalhado.
    try:
        raw = await asyncio.to_thread(_ftp_download_file, 'SCUM.log')
        if not raw:
            return
        candidates = _parse_scum_death_candidates(_decode_scum_log(raw))
        state = _load_killfeed_state()
        seen = set(state.get('mystery_seen', []))
        if not state.get('mystery_bootstrapped'):
            state['mystery_seen'] = [e['key'] for e in candidates][-KILLFEED_MAX_SEEN:]
            state['mystery_bootstrapped'] = True
            _save_killfeed_state(state)
            print(f'KILL FEED COMPLEMENTAR: histórico inicial ignorado ({len(candidates)} registros).')
            return
        # Só eventos recentes na ordem do log; evita publicações retroativas.
        for event in candidates:
            if event['key'] in seen:
                continue
            elapsed = (datetime.now() - event['event_dt']).total_seconds()
            if elapsed < 90:
                continue
            if elapsed > 900:
                seen.add(event['key'])
                continue
            # Um registro detalhado do kill.log prevalece, inclusive se o nome divergir.
            # O registro complementar não possui identidade confiável.
            # Uma morte detalhada no mesmo instante prevalece, mesmo que
            # o nome histórico do SCUM.log seja diferente.
            detailed = any(k.get('event_dt') and abs((k['event_dt'] - event['event_dt']).total_seconds()) <= 3
                           for k in detailed_events)
            if detailed:
                seen.add(event['key'])
                continue
            await channel.send(embed=_mystery_embed(event))
            seen.add(event['key'])
            print(f"KILL FEED COMPLEMENTAR: morte publicada | perfil={event['profile']} | {event['stamp']}")
        state['mystery_seen'] = list(seen)[-KILLFEED_MAX_SEEN:]
        _save_killfeed_state(state)
    except Exception as error:
        print(f'KILL FEED COMPLEMENTAR: {type(error).__name__}: {error}')


async def process_killfeed_for_guild(guild):
    channel = find_text_channel_anywhere(guild, KILLFEED_CHANNEL_NAME)
    if channel is None:
        print(f"KILL FEED: canal não encontrado em {guild.name}")
        return

    await _cleanup_old_killfeed_panel(channel)

    if SCUM_KILLFEED_LOCAL_FILE:
        filenames = [SCUM_KILLFEED_LOCAL_FILE]
    else:
        try:
            filenames = await asyncio.to_thread(_ftp_list_event_kill_files)
        except Exception as error:
            print(
                f"ERRO LISTAGEM FTP KILL FEED: "
                f"{type(error).__name__}: {error}"
            )
            return

    if not filenames:
        await _process_scum_death_fallback(channel, [])
        return

    # V6: não depende somente do último nome de arquivo.
    # O SCUM pode continuar acrescentando mortes ao kill_*.log ativo,
    # e alguns hosts podem manter mais de um arquivo na pasta.
    state = _load_killfeed_state()
    seen = set(state.get("seen", []))

    all_events = []
    files_with_events = []

    for filename in filenames:
        text = await _read_kill_file(filename)
        if text is None:
            continue

        events_file = _parse_kill_events(text)
        if events_file:
            files_with_events.append(filename)
            all_events.extend(events_file)
            print(
                f"KILL FEED: {filename} | eventos={len(events_file)} | "
                f"bytes de texto={len(text)}"
            )

    if not all_events:
        print("KILL FEED: nenhum evento válido encontrado nos logs.")
        await _process_scum_death_fallback(channel, [])
        return

    # Ordena pelo horário do acontecimento e elimina qualquer duplicação
    # acidental entre arquivos.
    unique_events = {}
    for event in all_events:
        unique_events[event["key"]] = event
    events = sorted(
        unique_events.values(),
        key=lambda e: e["event_dt"] or datetime.min
    )

    print(
        f"KILL FEED: total={len(events)} | já publicados={len(seen)} | "
        f"arquivos com eventos={len(files_with_events)}"
    )

    new_events = [event for event in events if event["key"] not in seen]

    # Compatibilidade com o estado antigo V2, que guardava hashes por arquivo.
    old_files = state.get("files", {})
    if not seen and isinstance(old_files, dict):
        for old_file in old_files.values():
            if isinstance(old_file, dict):
                seen.update(old_file.get("seen", []))
        new_events = [event for event in events if event["key"] not in seen]

    # Na primeira leitura de um estado novo, todos os eventos existentes
    # são históricos: jamais publicar o último como se fosse novo.
    if not state.get("bootstrapped", False):
        seen.update(event["key"] for event in events)
        state["seen"] = list(seen)[-KILLFEED_MAX_SEEN:]
        state["bootstrapped"] = True
        _save_killfeed_state(state)
        print(f"KILL FEED: estado inicial persistido em {SCUM_KILLFEED_STATE_FILE}; "
              f"{len(events)} eventos históricos ignorados.")
        await _process_scum_death_fallback(channel, events)
        return

    new_events.sort(key=lambda e: e["event_dt"] or datetime.min)

    for event in new_events:
        try:
            await channel.send(embed=_build_kill_embed(event))
            seen.add(event["key"])
            print(
                f"KILL FEED PUBLICADO: {event['victim']} <- "
                f"{event['killer']} | {event['stamp']}"
            )
        except Exception as error:
            print(
                f"ERRO PUBLICAÇÃO KILL FEED: {type(error).__name__}: {error}"
            )

    # Mesmo que não haja novo evento, salva o estado para persistência.
    state["seen"] = list(seen)[-KILLFEED_MAX_SEEN:]
    state["files"] = {
        filename: {"last_event_key": events[-1]["key"]}
        for filename in files_with_events
    }
    _save_killfeed_state(state)
    await _process_scum_death_fallback(channel, events)


async def scum_killfeed_loop():
    await bot.wait_until_ready()

    print(
        f"KILL FEED INICIANDO | intervalo: {SCUM_KILLFEED_POLL_SECONDS}s"
    )

    while not bot.is_closed():
        if SCUM_KILLFEED_LOCAL_FILE:
            ftp_ready = True
        else:
            ftp_ready = _ensure_ftp_credentials()

        if ftp_ready:
            print_once_key = getattr(bot, "_killfeed_ready_logged", False)
            if not print_once_key:
                print("KILL FEED ATIVO | FTP pronto para consulta.")
                bot._killfeed_ready_logged = True

            for guild in bot.guilds:
                try:
                    await process_killfeed_for_guild(guild)
                except Exception as error:
                    print(
                        f"ERRO KILL FEED {guild.name}: "
                        f"{type(error).__name__}: {error}"
                    )
        else:
            # Não encerra o loop. Se a configuração aparecer depois,
            # o bot tenta novamente automaticamente no próximo ciclo.
            if not getattr(bot, "_killfeed_waiting_logged", False):
                print(
                    "KILL FEED AGUARDANDO CREDENCIAIS: "
                    "tentando localizar automaticamente no FileZilla."
                )
                bot._killfeed_waiting_logged = True

        await asyncio.sleep(SCUM_KILLFEED_POLL_SECONDS)


# ============================================================
# CARGO DROP FEED — SCUM.log
# ============================================================
# O SCUM registra o nascimento do Cargo Drop no SCUM.log com a linha:
#   LogTemp: Cargo drop spawned at: X, Y, Z
# A leitura usa uma sessão FTP persistente compartilhada com o Kill Feed.
# O estado é separado para nunca republicar eventos.

CARGODROP_LOG_FILENAME = "SCUM.log"
CARGODROP_POLL_SECONDS = 10
CARGODROP_STATE_FILE = os.getenv(
    "SCUM_CARGODROP_STATE_FILE",
    "/data/cargodrop_state.json" if os.path.isdir("/data") else "cargodrop_state.json"
).strip()
CARGODROP_MAX_SEEN = 500
CARGODROP_IMAGE_FILENAME = "cargo_drop_aviso.png"
CARGODROP_IMAGE_PATH = os.path.join(
    os.path.dirname(os.path.abspath(__file__)),
    CARGODROP_IMAGE_FILENAME
)

CARGODROP_DIAG_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "diagnostico_logs")
CARGODROP_DIAG_FILE = os.path.join(CARGODROP_DIAG_DIR, "cargodrop_monitor.log")
os.makedirs(CARGODROP_DIAG_DIR, exist_ok=True)

def _cargodrop_diag(message):
    try:
        stamp = datetime.now().strftime("%d/%m/%Y %H:%M:%S")
        with open(CARGODROP_DIAG_FILE, "a", encoding="utf-8") as f:
            f.write(f"[{stamp}] {message}\n")
    except Exception:
        pass
    print(message, flush=True)

CARGODROP_EVENT_RE = re.compile(
    r"Cargo\s+drop\s+spawned\s+at:\s*"
    r"(?P<x>-?\d+(?:\.\d+)?)\s*,\s*"
    r"(?P<y>-?\d+(?:\.\d+)?)\s*,\s*"
    r"(?P<z>-?\d+(?:\.\d+)?)",
    re.IGNORECASE
)


def _load_cargodrop_state():
    try:
        with open(CARGODROP_STATE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            raise ValueError("estado inválido")
        data.setdefault("version", 1)
        data.setdefault("seen", [])
        return data
    except (FileNotFoundError, json.JSONDecodeError, OSError, ValueError):
        return {"version": 1, "seen": []}


def _save_cargodrop_state(state):
    temp = f"{CARGODROP_STATE_FILE}.tmp"
    with open(temp, "w", encoding="utf-8") as f:
        json.dump(state, f, ensure_ascii=False, indent=2)
    os.replace(temp, CARGODROP_STATE_FILE)


def _cargodrop_event_key(event):
    base = "|".join([
        event.get("stamp", ""),
        f"{event.get('x', 0.0):.3f}",
        f"{event.get('y', 0.0):.3f}",
        f"{event.get('z', 0.0):.3f}",
    ])
    return hashlib.sha256(base.encode("utf-8", errors="ignore")).hexdigest()


def _parse_cargodrop_events(text: str):
    events = []

    for line in text.splitlines():
        if "cargo drop spawned at:" not in line.lower():
            continue

        match = CARGODROP_EVENT_RE.search(line)
        if not match:
            continue

        stamp_match = KILL_TIMESTAMP_RE.search(line)
        stamp = stamp_match.group("stamp") if stamp_match else ""

        try:
            event_dt = datetime.strptime(
                stamp, "%Y.%m.%d-%H.%M.%S"
            ) if stamp else None
        except ValueError:
            event_dt = None

        # O timestamp gravado pelo SCUM no log vem em UTC.
        # Para exibição, convertemos explicitamente para Brasília (UTC-3).
        # O timestamp UTC original continua separado para deduplicação/rastreio.
        display_stamp = stamp
        display_iso = ""
        if event_dt is not None:
            try:
                from zoneinfo import ZoneInfo
                event_utc = event_dt.replace(tzinfo=ZoneInfo("UTC"))
                event_local = event_utc.astimezone(ZoneInfo("America/Sao_Paulo"))
                display_stamp = event_local.strftime("%d/%m/%Y %H:%M:%S")
                display_iso = event_local.isoformat(timespec="seconds")
            except Exception:
                display_stamp = stamp

        event = {
            "stamp": display_stamp,
            "event_dt": event_dt,
            "raw_stamp": stamp,
            "display_iso": display_iso,
            "x": float(match.group("x")),
            "y": float(match.group("y")),
            "z": float(match.group("z")),
        }
        event["key"] = _cargodrop_event_key(event)
        events.append(event)

    unique = {}
    for event in events:
        unique[event["key"]] = event

    return sorted(
        unique.values(),
        key=lambda e: e["event_dt"] or datetime.min
    )


async def _read_scum_main_log():
    try:
        raw = await asyncio.to_thread(
            _ftp_download_file,
            CARGODROP_LOG_FILENAME
        )
        if raw is None:
            return None
        return _decode_scum_log(raw)
    except Exception as error:
        print(
            f"ERRO LEITURA CARGO DROP: {type(error).__name__}: {error}"
        )
        return None



def _scum_sector_from_coords(x, y):
    """Converte coordenadas SCUM para o setor 5x5 (ex.: B0).

    SCUM usa 5 colunas (4,3,2,1,0) de oeste para leste e
    5 linhas (D,C,B,A,Z) de norte para sul.
    """
    try:
        x = float(x)
        y = float(y)

        # Limites conhecidos da ilha / divisão em 5 setores.
        x_max = 619646.8573
        y_max = 619659.7258
        sector_size = 304803.45056

        col_index = int((x_max - x) // sector_size)
        row_index = int((y_max - y) // sector_size)

        col_index = max(0, min(4, col_index))
        row_index = max(0, min(4, row_index))

        columns = ["4", "3", "2", "1", "0"]
        rows = ["D", "C", "B", "A", "Z"]

        return f"{rows[row_index]}{columns[col_index]}"
    except (TypeError, ValueError, OverflowError):
        return "—"


def _cargodrop_display_time(stamp):
    """Converte o timestamp do log do SCUM (UTC) para Brasília (UTC-3)."""
    try:
        from datetime import timedelta

        dt_utc = datetime.strptime(
            stamp, "%Y.%m.%d-%H.%M.%S"
        )
        dt_br = dt_utc - timedelta(hours=3)

        return dt_br.strftime("%d/%m/%Y %H:%M:%S")
    except Exception:
        return stamp


def _build_cargodrop_embed(event):
    embed = discord.Embed(
        title="📦 CARGO DROP — INICIADO",
        description=(
            "Um novo carregamento foi lançado no mundo!\n"
            "Prepare-se para disputar o loot."
        ),
        colour=discord.Colour.orange()
    )

    sector = _scum_sector_from_coords(
        event["x"],
        event["y"]
    )

    embed.add_field(
        name="📍 Local do Drop",
        value=(
            f"🗺️ **Setor:** `{sector}`\n"
            f"X `{event['x']:.2f}`\n"
            f"Y `{event['y']:.2f}`\n"
            f"Z `{event['z']:.2f}`"
        ),
        inline=True
    )
    embed.add_field(
        name="🕐 Horário",
        value=f"`{_cargodrop_display_time(event["stamp"])} (Brasília)`",
        inline=True
    )
    embed.add_field(
        name="🎁 Evento",
        value="**Cargo Drop ativo**",
        inline=True
    )
    # A imagem é enviada como anexo pelo próprio bot e exibida no embed.
    # Assim não dependemos de hospedagem externa e a imagem é sempre a
    # original fornecida para o Cargo Drop.
    if os.path.isfile(CARGODROP_IMAGE_PATH):
        embed.set_image(url=f"attachment://{CARGODROP_IMAGE_FILENAME}")

    embed.set_footer(
        text="PRIMEIRO MUNDO • Cargo Drop Feed V12"
    )
    return embed


async def process_cargodrop_for_guild(guild):
    channel = find_text_channel_anywhere(
        guild,
        CARGODROP_CHANNEL_NAME
    )
    if channel is None:
        print(
            f"CARGO DROP: canal não encontrado em {guild.name}"
        )
        return

    text = await _read_scum_main_log()
    if text is None:
        return

    events = _parse_cargodrop_events(text)
    if not events:
        print("CARGO DROP: SCUM.log lido, mas nenhum spawn foi identificado.")
        return

    state = _load_cargodrop_state()
    seen = set(state.get("seen", []))

    # Primeira leitura após perda/ausência de estado: nunca descartar um drop
    # recente silenciosamente. Recupera somente eventos dos últimos 15 minutos
    # e registra os anteriores como histórico, sem republicá-los.
    if not state.get("initialized", False):
        cutoff = datetime.now(timezone.utc).replace(tzinfo=None) - timedelta(minutes=15)
        recent = [event for event in events
                  if event.get("event_dt") is not None and event["event_dt"] >= cutoff]
        seen.update(event["key"] for event in events if event not in recent)
        state["initialized"] = True
        state["seen"] = list(seen)[-CARGODROP_MAX_SEEN:]
        _save_cargodrop_state(state)
        print(f"CARGO DROP: estado inicializado | históricos={len(events)-len(recent)} "
              f"| recentes pendentes={len(recent)} | arquivo={CARGODROP_STATE_FILE}")
        # Continua para a publicação dos eventos recentes, em vez de retornar.

    new_events = [
        event for event in events
        if event["key"] not in seen
    ]

    if new_events:
        print(
            f"CARGO DROP: {len(new_events)} novo(s) detectado(s) "
            f"sem reiniciar o bot."
        )

    for event in new_events:
        try:
            embed = _build_cargodrop_embed(event)

            if os.path.isfile(CARGODROP_IMAGE_PATH):
                file = discord.File(
                    CARGODROP_IMAGE_PATH,
                    filename=CARGODROP_IMAGE_FILENAME
                )
                await channel.send(embed=embed, file=file)
            else:
                print(
                    "CARGO DROP: imagem não encontrada; publicando sem imagem: "
                    f"{CARGODROP_IMAGE_PATH}"
                )
                await channel.send(embed=embed)

            seen.add(event["key"])
            state["seen"] = list(seen)[-CARGODROP_MAX_SEEN:]
            _save_cargodrop_state(state)
            _cargodrop_diag(
                "CARGO DROP PUBLICADO SEM REINICIAR: "
                f"{event['stamp']} | X={event['x']:.2f} Y={event['y']:.2f} Z={event['z']:.2f}"
            )
        except Exception as error:
            print(
                f"ERRO PUBLICAÇÃO CARGO DROP: "
                f"{type(error).__name__}: {error}"
            )

    state["seen"] = list(seen)[-CARGODROP_MAX_SEEN:]
    _save_cargodrop_state(state)


async def scum_cargodrop_loop():
    await bot.wait_until_ready()

    _cargodrop_diag("CARGO DROP INICIANDO | intervalo: 10s | FTP persistente V12")
    _cargodrop_diag(f"CARGO DROP DIAGNÓSTICO: {CARGODROP_DIAG_FILE}")
    _cargodrop_diag(
        "CARGO DROP IMAGEM: "
        + (f"ATIVA | {CARGODROP_IMAGE_PATH}" if os.path.isfile(CARGODROP_IMAGE_PATH)
           else f"NÃO ENCONTRADA | {CARGODROP_IMAGE_PATH}")
    )

    ciclo = 0

    while not bot.is_closed():
        ciclo += 1

        try:
            # A conexão FTP é reutilizada entre os ciclos; só reconecta se necessário.
            # Uma falha nunca pode encerrar a task.
            if SCUM_KILLFEED_LOCAL_FILE:
                ftp_ready = True
            else:
                ftp_ready = _ensure_ftp_credentials()

            if ftp_ready:
                for guild in bot.guilds:
                    try:
                        await process_cargodrop_for_guild(guild)
                    except Exception as error:
                        print(
                            f"ERRO CARGO DROP {guild.name}: "
                            f"{type(error).__name__}: {error}"
                        )

                if ciclo % 5 == 0:
                    _cargodrop_diag(
                        f"CARGO DROP MONITORANDO | ciclos={ciclo} | próxima leitura em 3s"
                    )
            else:
                _cargodrop_diag("CARGO DROP AGUARDANDO FTP | nova tentativa em 10s.")

        except Exception as error:
            # Fundamental: uma exceção de FTP/credencial/IO não pode matar
            # a task. O loop permanece vivo e tenta novamente.
            _cargodrop_diag(
                f"CARGO DROP LOOP RECUPERADO: {type(error).__name__}: {error}"
            )

        await asyncio.sleep(CARGODROP_POLL_SECONDS)


