async def create_ticket_from_interaction(interaction, ticket_type_key):
    guild = interaction.guild
    member = interaction.user

    # Responde imediatamente para evitar o erro "O aplicativo não responde a tempo".
    if not interaction.response.is_done():
        await interaction.response.defer(ephemeral=True)

    if guild is None:
        await interaction.followup.send(
            "❌ Não foi possível identificar o servidor.",
            ephemeral=True
        )
        return

    ticket_type = TICKET_TYPES.get(ticket_type_key)
    if ticket_type is None:
        await interaction.followup.send(
            "❌ Tipo de atendimento inválido.",
            ephemeral=True
        )
        return

    existing = discord.utils.find(
        lambda channel: channel.name == f"ticket-{member.id}",
        guild.text_channels
    )

    if existing:
        await interaction.followup.send(
            f"⚠️ Você já possui um ticket aberto: {existing.mention}",
            ephemeral=True
        )
        return

    category = discord.utils.get(
        guild.categories,
        name=ATTENDANCE_CATEGORY_NAME
    )

    if category is None:
        await interaction.followup.send(
            "❌ Categoria de atendimento não encontrada.",
            ephemeral=True
        )
        return

    staff_roles = get_staff_roles(guild)

    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=False),
        member: discord.PermissionOverwrite(
            view_channel=True,
            send_messages=True,
            read_message_history=True,
            attach_files=True,
            embed_links=True
        )
    }

    if guild.me:
        overwrites[guild.me] = discord.PermissionOverwrite(
            view_channel=True,
            send_messages=True,
            read_message_history=True,
            manage_channels=True,
            manage_messages=True
        )

    for role in staff_roles:
        overwrites[role] = discord.PermissionOverwrite(
            view_channel=True,
            send_messages=True,
            read_message_history=True,
            attach_files=True,
            embed_links=True,
            manage_messages=True
        )

    try:
        ticket = await guild.create_text_channel(
            name=f"ticket-{member.id}",
            category=category,
            overwrites=overwrites,
            topic=(
                f"Ticket | Proprietário: {member.id} | "
                f"Tipo: {ticket_type['label']}"
            ),
            reason=f"Ticket aberto por {member}"
        )
    except discord.Forbidden:
        await interaction.followup.send(
            "❌ Não tenho permissão para criar o ticket.",
            ephemeral=True
        )
        return
    except discord.HTTPException as error:
        await interaction.followup.send(
            f"❌ Discord recusou a criação do ticket: {error}",
            ephemeral=True
        )
        return

    await interaction.followup.send(
        f"✅ Ticket criado: {ticket.mention}",
        ephemeral=True
    )

    embed = discord.Embed(
        title="🎫 ATENDIMENTO — PRIMEIRO MUNDO",
        description=(
            f"Olá {member.mention}!\n\n"
            f"**Tipo de atendimento:** {ticket_type['emoji']} {ticket_type['label']}\n\n"
            "Explique seu problema com o máximo de detalhes.\n\n"
            "A Staff responderá neste ticket."
        )
    )
    embed.set_footer(text="PRIMEIRO MUNDO • Atendimento")

    await ticket.send(
        content=member.mention,
        embed=embed,
        view=CloseTicketView()
    )

    await send_log(
        guild,
        f"🎫 **Ticket aberto**\n"
        f"👤 {member.mention} (`{member.id}`)\n"
        f"📂 Tipo: **{ticket_type['label']}**\n"
        f"📁 {ticket.mention}"
    )


class TicketSelect(discord.ui.Select):

    def __init__(self):
        options = [
            discord.SelectOption(
                label=data["label"],
                value=key,
                emoji=data["emoji"],
                description=data["description"]
            )
            for key, data in TICKET_TYPES.items()
        ]

        super().__init__(
            placeholder="Selecione o tipo de atendimento...",
            min_values=1,
            max_values=1,
            options=options,
            custom_id="primeiro_mundo_ticket_select"
        )

    async def callback(self, interaction):
        await create_ticket_from_interaction(
            interaction,
            self.values[0]
        )


class TicketView(discord.ui.View):

    def __init__(self):
        super().__init__(timeout=None)
        self.add_item(TicketSelect())


