# FECHAR TICKET
# ============================================================

class CloseTicketView(discord.ui.View):

    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(
        label="FECHAR TICKET",
        emoji="🔴",
        style=discord.ButtonStyle.red,
        custom_id="primeiro_mundo_fechar_ticket"
    )
    async def fechar_ticket(
        self,
        interaction,
        button
    ):
        channel = interaction.channel
        member = interaction.user

        if channel is None:
            return

        if not channel.name.startswith("ticket-"):
            await interaction.response.send_message(
                "❌ Este botão só funciona dentro de tickets.",
                ephemeral=True
            )
            return

        try:
            owner_id = int(
                channel.name.replace(
                    "ticket-",
                    "",
                    1
                )
            )
        except ValueError:
            owner_id = None

        if (
            owner_id is not None
            and member.id != owner_id
            and not is_staff(member)
        ):
            await interaction.response.send_message(
                "❌ Você não pode fechar este ticket.",
                ephemeral=True
            )
            return

        await interaction.response.send_message(
            "🔴 Ticket será fechado em 5 segundos.",
            ephemeral=True
        )

        await send_log(
            interaction.guild,
            f"🔴 **Ticket fechado**\n"
            f"👤 Fechado por: {member.mention}\n"
            f"📁 #{channel.name}"
        )

        await asyncio.sleep(5)

        try:
            await channel.delete(
                reason=f"Ticket fechado por {member}"
            )
        except (
            discord.Forbidden,
            discord.HTTPException
        ):
            pass


