# ============================================================
# BUNKERS — painel independente, leitura do gameplay_*.log
# ============================================================
BUNKERS_CHANNEL_NAME = "🔐・bunkers"
BUNKERS_LOG_RE = re.compile(r"^gameplay_.*\.log$", re.IGNORECASE)
BUNKERS_LINE_RE = re.compile(
    r"^(?P<stamp>\d{4}\.\d{2}\.\d{2}-\d{2}\.\d{2}\.\d{2}):.*?"
    r"(?P<sector>[A-D][0-4]) Bunker is (?P<status>Active|Locked)\."
    r"(?P<details>.*)$", re.IGNORECASE
)
BUNKERS_NEXT_RE = re.compile(r"next Activation in (\d+)h (\d+)m (\d+)s", re.IGNORECASE)
BUNKERS_LAST_SNAPSHOT = None
BUNKERS_EXPECTED_SECTORS = frozenset(('A1', 'A3', 'C4', 'D1'))
BUNKERS_SETTLE_SECONDS = 30
BUNKERS_EVENT_RE = re.compile(
    r"^(?P<stamp>\d{4}\.\d{2}\.\d{2}-\d{2}\.\d{2}\.\d{2}):.*?"
    r"(?P<sector>A1|A3|C4|D1) Bunker (?P<action>Activated|Deactivated)\b",
    re.IGNORECASE
)
BUNKERS_REPORT_RE = re.compile(
    r"^\d{4}\.\d{2}\.\d{2}-\d{2}\.\d{2}\.\d{2}:.*?"
    r"\[LogBunkerLock\] Bunker activations:", re.IGNORECASE
)

def _parse_bunker_log(text):
    """Lê o último relatório completo, incluindo a seção Locked bunkers.

    Não transforma ausência de informação em fechamento nem mistura relatórios.
    Eventos posteriores são aplicados apenas quando explicitamente reconhecidos.
    """
    reports = []
    current = None
    section = None
    events = []

    def finish_report():
        nonlocal current
        if current is not None:
            if current['saw_locked'] and set(current['states']) == BUNKERS_EXPECTED_SECTORS:
                reports.append(current)
            current = None

    for raw in text.splitlines():
        line = raw.strip()
        event = BUNKERS_EVENT_RE.search(line)
        if event:
            stamp = datetime.strptime(event.group('stamp'), '%Y.%m.%d-%H.%M.%S').replace(tzinfo=timezone.utc)
            events.append((stamp, event.group('sector').upper(), event.group('action').lower()))
        if BUNKERS_REPORT_RE.search(line):
            finish_report()
            current = {'states': {}, 'stamp': None, 'saw_locked': False}
            section = 'active'
            continue
        if current is None:
            continue
        if '[LogBunkerLock] Locked bunkers:' in line:
            current['saw_locked'] = True
            section = 'locked'
            continue
        match = BUNKERS_LINE_RE.search(line)
        if match:
            stamp = datetime.strptime(match.group('stamp'), '%Y.%m.%d-%H.%M.%S').replace(tzinfo=timezone.utc)
            sector = match.group('sector').upper()
            status = match.group('status').lower()
            # A linha e a seção devem concordar: divergência não é estado confirmado.
            if status != section or sector in current['states']:
                current['invalid'] = True
                continue
            timer = BUNKERS_NEXT_RE.search(match.group('details'))
            remaining = (timedelta(hours=int(timer.group(1)), minutes=int(timer.group(2)),
                                   seconds=int(timer.group(3))) if timer and status == 'locked' else None)
            current['states'][sector] = {'status': status, 'stamp': stamp,
                                          'next': stamp + remaining if remaining else None}
            current['stamp'] = stamp
        elif current['saw_locked'] and current['states'] and '[LogBunkerLock]' not in line:
            # Fim da seção de relatório; não aceitar fragmentos de outros ciclos.
            finish_report()
            section = None
    finish_report()
    reports = [r for r in reports if not r.get('invalid')]
    if not reports:
        return {'states': {}, 'confirmed': False,
                'reason': 'Nenhum relatório completo com os quatro estados foi encontrado.'}
    report = reports[-1]
    states = {key: dict(value) for key, value in report['states'].items()}
    report_stamp = report['stamp']
    subsequent = [event for event in events if event[0] > report_stamp]
    for stamp, sector, action in subsequent:
        states[sector] = {'status': 'active' if action == 'activated' else 'locked',
                          'stamp': stamp, 'next': None}
    last_stamp = max((event[0] for event in subsequent), default=report_stamp)
    settling = bool(subsequent and 0 <= (datetime.now(timezone.utc) - last_stamp).total_seconds() < BUNKERS_SETTLE_SECONDS)
    return {'states': states, 'confirmed': not settling,
            'reason': 'Rotação em andamento: aguardando estabilização dos eventos.' if settling else '',
            'stamp': last_stamp, 'reconstructed': bool(subsequent),
            'active': sum(v['status'] == 'active' for v in states.values())}

def _read_bunker_snapshot_sync():
    # Usa a mesma sessão e o mesmo lock V21, sem abrir outra conexão.
    with SCUM_FTP_IO_LOCK:
        ftp = _ftp_connect()
        if ftp is None:
            return None
        ftp.cwd(SCUM_FTP_LOG_PATH)
        names = [name.rsplit('/', 1)[-1] for name in ftp.nlst()]
        candidates = sorted((name for name in names if BUNKERS_LOG_RE.match(name)), reverse=True)
        if not candidates:
            return None
        filename = candidates[0]
        buffer = BytesIO()
        ftp.voidcmd('TYPE I')
        ftp.retrbinary('RETR ' + filename, buffer.write, blocksize=8192)
        return filename, _parse_bunker_log(_decode_scum_log(buffer.getvalue()))


def _format_bunker_panel(snapshot):
    filename, result = snapshot
    states = result['states']
    embed = discord.Embed(title='🔐 BUNKERS — PRIMEIRO MUNDO', colour=discord.Colour.blue())
    if not states:
        embed.description = '⏳ Aguardando relatório de estado dos bunkers no gameplay.log.'
        return embed
    latest = result.get('stamp') or max(item['stamp'] for item in states.values())
    age = datetime.now(timezone.utc) - latest
    if not result['confirmed'] or age > timedelta(hours=6, minutes=10):
        embed.description = ('⚠️ **ESTADO ATUAL NÃO CONFIRMADO**\n'
                             + (result['reason'] or 'Última leitura desatualizada.')
                             + '\nA lista anterior não será apresentada como situação atual.')
        embed.add_field(name='🕐 Último registro', value='<t:%d:F> · <t:%d:R>' %
                        (int(latest.timestamp()), int(latest.timestamp())), inline=False)
        embed.set_footer(text='Fonte: %s • aguardando confirmação do SCUM' % filename)
        return embed
    active = sum(info['status'] == 'active' for info in states.values())
    total = len(states)
    source = ('Estado reconstruído dos eventos do SCUM' if result['reconstructed']
              else 'Estado confirmado pelo relatório do SCUM')
    embed.description = f'📡 {source} • **{active} de {total} bunkers ativos**.'
    for status, title in (('active', '🔓 ABERTOS'), ('locked', '🔒 FECHADOS')):
        lines = []
        for sector, info in sorted(states.items()):
            if info['status'] != status:
                continue
            detail = ''
            if info['next']:
                detail = ' · previsão registrada: <t:%d:F> (<t:%d:R>)' % (int(info['next'].timestamp()), int(info['next'].timestamp()))
            lines.append('**%s**%s' % (sector, detail))
        embed.add_field(name=title, value='\n'.join(lines) or 'Nenhum', inline=False)
    embed.add_field(name='🕐 Último registro', value='<t:%d:F> · <t:%d:R>' %
                    (int(latest.timestamp()), int(latest.timestamp())), inline=False)
    embed.set_footer(text='Fonte: %s • UTC convertido pelo Discord' % filename)
    return embed


async def process_bunkers_for_guild(guild):
    global BUNKERS_LAST_SNAPSHOT
    channel = find_text_channel_anywhere(guild, BUNKERS_CHANNEL_NAME)
    if channel is None:
        category = discord.utils.get(guild.categories, name='🎯 GAMEPLAY')
        if category is None:
            return
        channel = await get_or_create_text(guild, category, BUNKERS_CHANNEL_NAME, topic='Estado dos bunkers conforme gameplay.log do SCUM')
    try:
        snapshot = await asyncio.to_thread(_read_bunker_snapshot_sync)
        if snapshot is not None:
            BUNKERS_LAST_SNAPSHOT = snapshot
    except Exception as error:
        print('BUNKERS FTP:', type(error).__name__, error)
    if BUNKERS_LAST_SNAPSHOT is None:
        return
    embed = _format_bunker_panel(BUNKERS_LAST_SNAPSHOT)
    try:
        async for message in channel.history(limit=50):
            if message.author == bot.user and message.embeds and message.embeds[0].title == embed.title:
                if message.embeds[0].to_dict() != embed.to_dict():
                    await message.edit(embed=embed)
                return
        await channel.send(embed=embed)
    except (discord.Forbidden, discord.HTTPException) as error:
        print('BUNKERS DISCORD:', type(error).__name__, error)


# ============================================================
# SUPERVISOR FTP ÚNICO — V21
# ============================================================

V21_STAGE_PAUSE_SECONDS = 10
V21_INITIAL_FTP_WAIT_SECONDS = 3

async def _v21_run_stage(label, func):
    """Executa uma etapa inteira sem permitir que uma exceção mate o supervisor."""
    print(f"[FTP V21] INICIANDO {label}")
    try:
        await asyncio.wait_for(func(), timeout=45)
        print(f"[FTP V21] FINALIZANDO {label}")
    except asyncio.TimeoutError:
        print(f"[FTP V21] TIMEOUT {label} — supervisor continua vivo.")
    except Exception as error:
        print(
            f"[FTP V21] ERRO {label}: {type(error).__name__}: {error}"
        )


async def scum_v21_supervisor_loop():
    """Ciclo único: uma sessão FTP, três módulos, zero concorrência FTP."""
    await bot.wait_until_ready()

    print("=" * 60)
    print("FTP V21 SUPERVISOR ATIVO")
    print("STATUS → 10s → KILL FEED → 10s → CARGO DROP → 10s")
    print("Regra: conecta uma vez; só reconecta se perder a sessão.")
    print("=" * 60)

    # Primeira conexão: uma única tentativa normal. O primeiro estágio
    # também pode conectar se a hospedagem ainda não estiver pronta.
    try:
        await asyncio.to_thread(_ftp_connect)
    except Exception as error:
        print(f"[FTP V21] Pré-conexão falhou: {type(error).__name__}: {error}")

    await asyncio.sleep(V21_INITIAL_FTP_WAIT_SECONDS)

    while not bot.is_closed():
        async def stage_status():
            for guild in bot.guilds:
                try:
                    await update_status_panel(guild)
                except Exception as error:
                    print(
                        f"ERRO STATUS {guild.name}: "
                        f"{type(error).__name__}: {error}"
                    )

        async def stage_killfeed():
            for guild in bot.guilds:
                try:
                    await process_killfeed_for_guild(guild)
                except Exception as error:
                    print(
                        f"ERRO KILL FEED {guild.name}: "
                        f"{type(error).__name__}: {error}"
                    )

        async def stage_cargodrop():
            for guild in bot.guilds:
                try:
                    await process_cargodrop_for_guild(guild)
                except Exception as error:
                    print(
                        f"ERRO CARGO DROP {guild.name}: "
                        f"{type(error).__name__}: {error}"
                    )

        await _v21_run_stage("STATUS", stage_status)
        await asyncio.sleep(V21_STAGE_PAUSE_SECONDS)

        await _v21_run_stage("KILL FEED", stage_killfeed)
        await asyncio.sleep(V21_STAGE_PAUSE_SECONDS)

        await _v21_run_stage("CARGO DROP", stage_cargodrop)
        await asyncio.sleep(V21_STAGE_PAUSE_SECONDS)

        async def stage_bunkers():
            for guild in bot.guilds:
                await process_bunkers_for_guild(guild)

        await _v21_run_stage("BUNKERS", stage_bunkers)
        await asyncio.sleep(V21_STAGE_PAUSE_SECONDS)

        async def stage_lockpick():
            for guild in bot.guilds:
                await process_lockpick_for_guild(guild)

        await _v21_run_stage("LOCKPICK", stage_lockpick)
        await asyncio.sleep(V21_STAGE_PAUSE_SECONDS)


# ============================================================
# LOCKPICK — gameplay_*.log; somente objetos reais, sem treino
# ============================================================
LOCKPICK_ALERT_CHANNEL = "🔓・alertas-lockpick"
LOCKPICK_RANK_CHANNEL = "🏆・ranking-lockpick"
LOCKPICK_EVENT_RE = re.compile(
    r"^(?P<stamp>\d{4}\.\d{2}\.\d{2}-\d{2}\.\d{2}\.\d{2}): "
    r"\[LogMinigame\] \[LockpickingMinigame_C\] User: "
    r"(?P<name>.*?) \((?P<character>\d+), (?P<steam>\d{10,20})\)\. "
    r"Success: (?P<success>Yes|No)\. Elapsed time: (?P<elapsed>[\d.]+)\. "
    r"Failed attempts: (?P<failed>\d+)\. Target object: "
    r"(?P<target>.*?)\(ID: (?P<object_id>.*?)\)\. Lock type: "
    r"(?P<difficulty>.*?)\. User owner: (?P<owner>.*?)\. "
    r"Location: X=(?P<x>-?[\d.]+) Y=(?P<y>-?[\d.]+) Z=(?P<z>-?[\d.]+)$"
)
LOCKPICK_TRAINING_RE = re.compile(r"train|practice|tutorial|dummy|skill.?test", re.I)
LOCKPICK_LABELS = {
    'BPLockpick_Weapon_Locker_Police_C': 'Armário policial',
    'BPLockpick_Weapon_Locker_Military_C': 'Armário militar',
    'BPLockpick_CargoDrop_01_ArmoryBox_C': 'Caixa de armamento — Cargo Drop',
}
# As imagens acompanham o bot no repositorio, na pasta imagens/.
# O campo Lock type do SCUM e dificuldade, nao prova o metal.
LOCKPICK_IMAGE_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'imagens')
LOCKPICK_TYPE_IMAGES = {'Ferro': 'ferro.png', 'Prata': 'prata.png',
                        'Ouro': 'ouro.png', 'Dial Lock': 'dial_lock.png'}

# Correspondencias especificas confirmadas pelo administrador do servidor.
# A dificuldade do minigame nao determina o metal da fechadura.
LOCKPICK_CONFIRMED_TYPES = {
    'bplockpick_medical_container_tec01_c': 'Ferro',
    'bplockpick_hazmat_suit_locker_02_c': 'Ferro',
    'bplockpick_weapon_locker_military_c': 'Ferro',
    'bplockpick_cargodrop_01_armorybox_c': 'Ferro',
}

def _lockpick_identify_type(target, difficulty):
    target_key = str(target or '').strip().lower()
    if target_key in LOCKPICK_CONFIRMED_TYPES:
        return LOCKPICK_CONFIRMED_TYPES[target_key]
    raw = f'{target} {difficulty}'.lower()
    if re.search(r'dial[ _-]?lock|combination[ _-]?(?:lock|padlock)', raw):
        return 'Dial Lock'
    for label, pattern in (
        ('Ouro', r'(?<![a-z])(?:gold|golden|ouro)(?![a-z])'),
        ('Prata', r'(?<![a-z])(?:silver|prata)(?![a-z])'),
        ('Ferro', r'(?<![a-z])(?:iron|ferro)(?![a-z])'),
    ):
        if re.search(pattern, raw):
            return label
    return 'Não identificado no log'

LOCKPICK_RANK_TITLE = '🏆 RANKING LOCKPICK — PRIMEIRO MUNDO'


def _lockpick_db():
    os.makedirs(os.path.dirname(os.path.abspath(ISLAND_DB_PATH)), exist_ok=True)
    db = sqlite3.connect(ISLAND_DB_PATH, timeout=15)
    db.execute('PRAGMA busy_timeout=15000')
    db.execute('''CREATE TABLE IF NOT EXISTS lockpick_events (
        event_id TEXT PRIMARY KEY, stamp TEXT NOT NULL, steam TEXT NOT NULL,
        player TEXT NOT NULL, success INTEGER NOT NULL, target TEXT NOT NULL,
        difficulty TEXT, elapsed REAL, failed_attempts INTEGER,
        owner TEXT, x REAL, y REAL, z REAL, alert_sent INTEGER NOT NULL DEFAULT 0
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS lockpick_meta
        (name TEXT PRIMARY KEY, value TEXT NOT NULL)''')
    return db


def _lockpick_parse(text, filename):
    events = []
    candidates = 0
    for raw_line in text.splitlines():
        line = raw_line.strip().lstrip('\\ufeff')
        if 'LockpickingMinigame_C' not in line or 'Target object:' not in line:
            continue
        candidates += 1
        m = LOCKPICK_EVENT_RE.match(line)
        if not m:
            # O SCUM pode incluir prefixos ou espaços adicionais no log.
            # Não inventar evento quando os campos necessários estiverem ausentes.
            normalized = re.sub(r"^.*?(?=\\d{4}\\.\\d{2}\\.\\d{2}-\\d{2}\\.\\d{2}\\.\\d{2}: \\[LogMinigame\\])", "", line)
            m = LOCKPICK_EVENT_RE.match(normalized)
        if not m:
            continue
        d = m.groupdict()
        if LOCKPICK_TRAINING_RE.search(d['target']):
            continue
        d['event_id'] = hashlib.sha256((filename + '\\n' + line).encode('utf-8')).hexdigest()
        events.append(d)
    if candidates and not events:
        print(f'LOCKPICK DIAGNÓSTICO: {filename} | {candidates} linhas candidatas, 0 eventos compatíveis; conferir formato do gameplay.log')
    return events


def _lockpick_read_sync():
    # Mesma sessão e mesmo lock FTP do V21; não abre uma conexão paralela.
    with SCUM_FTP_IO_LOCK:
        ftp = _ftp_connect()
        if ftp is None:
            print('LOCKPICK DIAGNÓSTICO: conexão FTP indisponível')
            return []
        paths = list(dict.fromkeys(p for p in
            (SCUM_FTP_ACTIVE_LOG_PATH, SCUM_FTP_LOG_PATH,
             '/SCUM/Saved/SaveFiles/Logs', '/SCUM/Saved/Logs') if p))
        for path in paths:
            try:
                ftp.cwd(path)
                names = [n.rsplit('/', 1)[-1] for n in ftp.nlst()]
                candidates = sorted((n for n in names if BUNKERS_LOG_RE.match(n)), reverse=True)
                if not candidates:
                    continue
                snapshots = []
                for filename in candidates[:4]:
                    try:
                        buffer = BytesIO()
                        ftp.voidcmd('TYPE I')
                        ftp.retrbinary('RETR ' + filename, buffer.write, blocksize=8192)
                        snapshots.append((filename, _decode_scum_log(buffer.getvalue())))
                    except Exception as error:
                        print(f'LOCKPICK DIAGNÓSTICO: falha ao ler {filename}: {type(error).__name__}: {error}')
                print(f'LOCKPICK DIAGNÓSTICO: PATH={path} | encontrados={len(candidates)} | lidos={len(snapshots)}')
                return snapshots
            except Exception as error:
                print(f'LOCKPICK DIAGNÓSTICO: PATH={path} | {type(error).__name__}: {error}')
        print('LOCKPICK DIAGNÓSTICO: nenhum gameplay_*.log acessível')
        return []


def _lockpick_import(filename, content):
    events = _lockpick_parse(content, filename)
    with _lockpick_db() as db:
        initialized = db.execute("SELECT value FROM lockpick_meta WHERE name='initialized'").fetchone()
        new = []
        for e in events:
            cursor = db.execute('''INSERT OR IGNORE INTO lockpick_events
                (event_id, stamp, steam, player, success, target, difficulty,
                 elapsed, failed_attempts, owner, x, y, z, alert_sent)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)''',
                (e['event_id'], e['stamp'], e['steam'], e['name'],
                 int(e['success'] == 'Yes'), e['target'], e['difficulty'],
                 float(e['elapsed']), int(e['failed']), e['owner'],
                 float(e['x']), float(e['y']), float(e['z']),
                 0 if initialized else 1))
            if cursor.rowcount and initialized:
                new.append(e)
        db.execute("INSERT OR IGNORE INTO lockpick_meta(name,value) VALUES('initialized','1')")
        # Persistência do envio por evento, inclusive entre reinícios.
        pending = db.execute('''SELECT event_id, stamp, steam, player, success, target,
            difficulty, elapsed, failed_attempts, owner, x, y, z
            FROM lockpick_events WHERE alert_sent=0 ORDER BY stamp, event_id LIMIT 30''').fetchall()
        rank = db.execute('''SELECT steam, MAX(player), COUNT(*), SUM(success),
            SUM(CASE WHEN success=0 THEN 1 ELSE 0 END)
            FROM lockpick_events GROUP BY steam ORDER BY SUM(success) DESC, COUNT(*) DESC LIMIT 15''').fetchall()
    return len(events), pending, rank


def _lockpick_rank_embed(rank):
    embed = discord.Embed(title=LOCKPICK_RANK_TITLE, colour=discord.Colour.gold())
    if not rank:
        embed.description = 'Aguardando aberturas reais registradas no gameplay.log.'
    else:
        embed.description = '\n'.join(
            f'**{i}. {discord.utils.escape_markdown(name)}** — 🔓 {success} sucessos | '
            f'❌ {fail} falhas | {total} eventos | {success/total:.0%} aproveitamento'
            for i, (_, name, total, success, fail) in enumerate(rank, 1)
        )
    embed.set_footer(text='Treinamento excluído • dados reais do gameplay.log')
    return embed


async def process_lockpick_for_guild(guild):
    category = discord.utils.get(guild.categories, name='🏝️ INÍCIO')
    if category is None:
        category = await get_or_create_category(guild, '🏝️ INÍCIO')
    alerts = find_text_channel_anywhere(guild, LOCKPICK_ALERT_CHANNEL)
    if alerts is None:
        alerts = await get_or_create_text(guild, category, LOCKPICK_ALERT_CHANNEL,
                                          topic='Lockpick real: sucessos e falhas; treino excluído')
    ranking = find_text_channel_anywhere(guild, LOCKPICK_RANK_CHANNEL)
    if ranking is None:
        ranking = await get_or_create_text(guild, category, LOCKPICK_RANK_CHANNEL,
                                           topic='Ranking de aberturas reais do SCUM')
    snapshots = await asyncio.to_thread(_lockpick_read_sync)
    if not snapshots:
        return
    total = 0
    pending = []
    rank = []
    for filename, content in snapshots:
        count, _, rank = await asyncio.to_thread(_lockpick_import, filename, content)
        total += count
    # Os alertas pendentes são consultados uma única vez após a importação.
    with _lockpick_db() as db:
        pending = db.execute("""SELECT event_id, stamp, steam, player, success, target,
            difficulty, elapsed, failed_attempts, owner, x, y, z
            FROM lockpick_events WHERE alert_sent=0 ORDER BY stamp, event_id LIMIT 30""").fetchall()
    for event in pending:
        event_id, stamp, steam, player, success, target, difficulty, elapsed, failed, owner, x, y, z = event
        label = LOCKPICK_LABELS.get(target, target)
        lock_type = _lockpick_identify_type(target, difficulty)
        embed = discord.Embed(title='🔓 LOCKPICK — ABERTO' if success else '❌ LOCKPICK — FALHOU',
                              colour=discord.Colour.green() if success else discord.Colour.orange())
        embed.description = (f'**Jogador:** {discord.utils.escape_markdown(player)}\n'
                             f'**Alvo:** `{label}`\n**Tipo de fechadura:** {lock_type}\n'
                             f'**Tempo:** {elapsed:.2f}s | **Falhas internas:** {failed}\n'
                             f'**Proprietário:** {owner}\n**Local:** X={x:.0f} Y={y:.0f} Z={z:.0f}')
        embed.set_footer(text=f'Gameplay UTC: {stamp} • PRIMEIRO MUNDO')
        image_name = LOCKPICK_TYPE_IMAGES.get(lock_type)
        image_path = os.path.join(LOCKPICK_IMAGE_DIR, image_name) if image_name else None
        if image_path and os.path.isfile(image_path):
            # Mesmo metodo de exibicao do Cargo Drop: imagem anexada no embed.
            embed.set_image(url=f'attachment://{image_name}')
            await alerts.send(embed=embed, file=discord.File(image_path, filename=image_name))
        else:
            print(f'LOCKPICK IMAGEM: sem imagem | tipo={lock_type} | path={image_path or "sem tipo identificado"}', flush=True)
            await alerts.send(embed=embed)
        await asyncio.to_thread(_lockpick_mark_sent, event_id)
    panel = None
    async for msg in ranking.history(limit=30):
        if msg.author == bot.user and msg.embeds and msg.embeds[0].title == LOCKPICK_RANK_TITLE:
            panel = msg
            break
    embed = _lockpick_rank_embed(rank)
    if panel:
        await panel.edit(embed=embed)
    else:
        await ranking.send(embed=embed)
    print(f'LOCKPICK: {len(snapshots)} arquivos | {total} eventos válidos | {len(pending)} alertas pendentes | ranking={len(rank)} jogadores')


def _lockpick_mark_sent(event_id):
    with _lockpick_db() as db:
        db.execute('UPDATE lockpick_events SET alert_sent=1 WHERE event_id=?', (event_id,))

# ============================================================
# OBITUÁRIO DA ILHA — somente histórico de mensagens do Discord.
# Sem FTP adicional, sem coordenadas, sem depender de arquivos efêmeros.
# Resumo do dia anterior às 00:10 (horário de Brasília).
# ============================================================
OBITUARY_CHANNEL_NAME = "💀・obituario-da-ilha"
OBITUARY_DAILY_HOUR = 0
OBITUARY_DAILY_MINUTE = 10


def _obituary_victim_from_embed(embed):
    """Conta só mensagens de morte emitidas pelo próprio bot."""
    footer = (getattr(getattr(embed, "footer", None), "text", None) or "")
    if footer == "PRIMEIRO MUNDO • Registro complementar de morte":
        description = embed.description or ""
        match = re.search(r"\*\*(.+?)\*\*", description)
        if not match:
            return None  # morte anônima: computada separadamente
        return discord.utils.remove_markdown(match.group(1)).strip() or None
    if embed.title in ("☠️ MORTE — NPC", "⚔️ KILL — PvP"):
        for field in embed.fields:
            if field.name == "💀 Vítima":
                return discord.utils.remove_markdown(field.value).strip() or None
    return None


def _obituary_is_death(embed):
    footer = (getattr(getattr(embed, "footer", None), "text", None) or "")
    return footer == "PRIMEIRO MUNDO • Registro complementar de morte" or embed.title in ("☠️ MORTE — NPC", "⚔️ KILL — PvP")


async def _publish_obituary_for_guild(guild, day):
    from collections import Counter
    source = find_text_channel_anywhere(guild, KILLFEED_CHANNEL_NAME)
    if source is None:
        print("OBITUÁRIO: canal Kill Feed ausente; resumo não publicado.")
        return
    target = find_text_channel_anywhere(guild, OBITUARY_CHANNEL_NAME)
    if target is None:
        target = await get_or_create_text(
            guild, source.category, OBITUARY_CHANNEL_NAME,
            topic="Resumo diário das mortes registradas no PRIMEIRO MUNDO."
        ) if source.category else await guild.create_text_channel(
            OBITUARY_CHANNEL_NAME, reason="Obituário diário PRIMEIRO MUNDO"
        )
    # Confere o próprio canal: não repete boletins após reinício/deploy.
    signature = f"OBITUÁRIO • {day:%Y-%m-%d}"
    async for message in target.history(limit=100):
        if message.author.id == bot.user.id and any(
            (getattr(e.footer, "text", None) or "") == signature for e in message.embeds
        ):
            return
    start = datetime(day.year, day.month, day.day, tzinfo=BRASILIA_TZ)
    end = start + timedelta(days=1)
    counts = Counter()
    anonymous = 0
    total = 0
    # O histórico do Discord é a fonte, não o arquivo de estado do Railway.
    async for message in source.history(limit=None, after=start.astimezone(timezone.utc), before=end.astimezone(timezone.utc), oldest_first=True):
        if message.author.id != bot.user.id:
            continue
        for embed in message.embeds:
            if not _obituary_is_death(embed):
                continue
            total += 1
            name = _obituary_victim_from_embed(embed)
            if name:
                counts[name] += 1
            else:
                anonymous += 1
    if not total:
        print(f"OBITUÁRIO: {day:%Y-%m-%d} sem mortes publicadas; nada enviado.")
        return
    rows = [f"⚰️ **{discord.utils.escape_markdown(name)}** — {amount} morte(s)" for name, amount in counts.most_common(15)]
    if len(counts) > 15:
        rows.append(f"…e mais {len(counts)-15} sobrevivente(s) registrados.")
    if anonymous:
        rows.append(f"👤 **Não identificadas** — {anonymous} morte(s)")
    embed = discord.Embed(
        title="💀 OBITUÁRIO DA ILHA",
        description=(f"**Boletim de {day:%d/%m/%Y}**\n\n" + "\n".join(rows) +
                     f"\n\n**Total de mortes publicadas:** {total}\n\n"
                     "*A ilha agradece a participação. O respawn segue funcionando normalmente.* 😂"),
        colour=discord.Colour.orange(),
    )
    embed.set_footer(text=signature)
    await target.send(embed=embed)
    print(f"OBITUÁRIO: publicado {day:%Y-%m-%d} | mortes={total} | jogadores={len(counts)}")


async def scum_obituary_loop():
    await bot.wait_until_ready()
    while not bot.is_closed():
        now = datetime.now(BRASILIA_TZ)
        if (now.hour, now.minute) >= (OBITUARY_DAILY_HOUR, OBITUARY_DAILY_MINUTE):
            day = (now - timedelta(days=1)).date()
            for guild in bot.guilds:
                try:
                    await _publish_obituary_for_guild(guild, day)
                except Exception as error:
                    print(f"OBITUÁRIO: {guild.name}: {type(error).__name__}: {error}")
        await asyncio.sleep(600)



# ============================================================
# RANKING E ESTATÍSTICAS — leitura do histórico Discord, sem FTP.
# Publicações: estatísticas 00:20; ranking semanal segunda 00:30 BRT.
# ============================================================
from collections import Counter

RANKING_CHANNEL_NAME = "🏆・ranking-sobreviventes"
ISLAND_STATS_CHANNEL_NAME = "📊・estatisticas-da-ilha"


def _island_field(embed, label):
    for field in embed.fields:
        if field.name == label:
            return discord.utils.remove_markdown(field.value).strip()
    return ""


async def _island_history(channel, start, end):
    if channel is None:
        return
    async for message in channel.history(
        limit=None, after=start.astimezone(timezone.utc),
        before=end.astimezone(timezone.utc), oldest_first=True
    ):
        if message.author.id == bot.user.id:
            for embed in message.embeds:
                yield embed


async def _island_collect(guild, start, end):
    kills = Counter()
    deaths = Counter()
    anonymous = 0
    pvp = 0
    total = 0
    drops = 0
    source = find_text_channel_anywhere(guild, KILLFEED_CHANNEL_NAME)
    async for embed in _island_history(source, start, end):
        if not _obituary_is_death(embed):
            continue
        total += 1
        victim = _obituary_victim_from_embed(embed)
        if victim:
            deaths[victim] += 1
        else:
            anonymous += 1
        if embed.title == "⚔️ KILL — PvP":
            killer = _island_field(embed, "🔫 Jogador")
            if killer and victim and killer.casefold() != victim.casefold():
                kills[killer] += 1
                pvp += 1
    cargo = find_text_channel_anywhere(guild, CARGODROP_CHANNEL_NAME)
    async for embed in _island_history(cargo, start, end):
        if embed.title == "📦 CARGO DROP — INICIADO":
            drops += 1
    return kills, deaths, anonymous, pvp, total, drops


async def _island_target(guild, name, topic):
    existing = find_text_channel_anywhere(guild, name)
    if existing:
        return existing
    source = find_text_channel_anywhere(guild, KILLFEED_CHANNEL_NAME)
    if source and source.category:
        return await get_or_create_text(guild, source.category, name, topic=topic)
    return await guild.create_text_channel(name, topic=topic, reason="Painel PRIMEIRO MUNDO")


async def _island_publish(guild, day, weekly=False):
    start = datetime(day.year, day.month, day.day, tzinfo=BRASILIA_TZ)
    end = start + timedelta(days=7 if weekly else 1)
    signature = ("RANKING SEMANAL" if weekly else "ESTATÍSTICAS DIÁRIAS") + f" • {day:%Y-%m-%d}"
    name = RANKING_CHANNEL_NAME if weekly else ISLAND_STATS_CHANNEL_NAME
    target = await _island_target(guild, name, "Resumo automático com arquivo histórico persistente, quando configurado.")
    async for message in target.history(limit=100):
        if message.author.id == bot.user.id and any(
            (getattr(e.footer, "text", None) or "") == signature for e in message.embeds
        ):
            return
    if ISLAND_DB_READY:
        try:
            await _island_archive_guild(guild)
            kills, deaths, anonymous, pvp, total, drops = await asyncio.to_thread(
                _island_db_collect, guild.id, start, end)
        except Exception as error:
            print(f"HISTÓRICO: fallback Discord: {type(error).__name__}: {error}")
            kills, deaths, anonymous, pvp, total, drops = await _island_collect(guild, start, end)
    else:
        kills, deaths, anonymous, pvp, total, drops = await _island_collect(guild, start, end)
    if weekly:
        if not total:
            print(f"RANKING: {day} sem registros; boletim não publicado.")
            return
        rows = []
        for i, (player, amount) in enumerate(kills.most_common(10), 1):
            d = deaths[player]
            kd = f"{amount / d:.2f}" if d else "— (sem mortes registradas)"
            rows.append(f"**{i}º** {discord.utils.escape_markdown(player)} — 🎯 {amount} | 💀 {d} | K/D {kd}")
        description = (f"**Período: {start:%d/%m} a {(end-timedelta(days=1)):%d/%m/%Y}**\n\n"
                       + ("\n".join(rows) if rows else "Nenhuma eliminação PvP confirmada no período.")
                       + f"\n\n**Mortes registradas:** {total} | **PvP confirmado:** {pvp}"
                       + "\n*Dados extraídos das publicações detalhadas; mortes sem identificação não geram eliminações.*")
        # Lendas da Ilha: títulos derivados somente dos registros confirmados.
        # Não inferir tempo de sobrevivência ou causas de morte.
        legends = []
        if kills:
            top_kills = max(kills.values())
            names = sorted((n for n, v in kills.items() if v == top_kills), key=str.casefold)
            legends.append("⚔️ **Carrasco da Semana:** " + ", ".join(discord.utils.escape_markdown(n) for n in names) + f" — {top_kills} eliminações PvP confirmadas")
        if deaths:
            top_deaths = max(deaths.values())
            names = sorted((n for n, v in deaths.items() if v == top_deaths), key=str.casefold)
            legends.append("⚰️ **Cliente do Cemitério:** " + ", ".join(discord.utils.escape_markdown(n) for n in names) + f" — {top_deaths} mortes registradas")
        if legends:
            description += "\n\n**🏝️ LENDAS DA ILHA**\n" + "\n".join(legends)
        description += "\n*O título Imortal depende de histórico confiável de tempo de sobrevivência e não é calculado nesta versão.*"
        title = "🏆 RANKING DOS SOBREVIVENTES"
    else:
        description = (f"**Boletim de {day:%d/%m/%Y}**\n\n"
                       f"💀 Mortes publicadas: **{total}**\n"
                       f"⚔️ Eliminações PvP confirmadas: **{pvp}**\n"
                       f"📦 Cargo Drops publicados: **{drops}**\n"
                       f"👤 Mortes sem identificação: **{anonymous}**\n\n"
                       "*Contagem das publicações reais arquivadas pelo bot. "
                       "Jogadores únicos, pico e horas online não são estimados sem histórico confiável.*")
        title = "📊 A ILHA EM NÚMEROS"
    embed = discord.Embed(title=title, description=description, colour=discord.Colour.blue())
    embed.set_footer(text=signature)
    await target.send(embed=embed)
    print(f"ILHA: {signature} publicado | mortes={total} | pvp={pvp} | drops={drops}")


async def scum_island_reports_loop():
    await bot.wait_until_ready()
    while not bot.is_closed():
        now = datetime.now(BRASILIA_TZ)
        for guild in bot.guilds:
            try:
                if (now.hour, now.minute) >= (0, 20):
                    await _island_publish(guild, (now-timedelta(days=1)).date())
                if now.weekday() == 0 and (now.hour, now.minute) >= (0, 30):
                    await _island_publish(guild, (now-timedelta(days=7)).date(), weekly=True)
            except Exception as error:
                print(f"RELATÓRIOS ILHA: {guild.name}: {type(error).__name__}: {error}")
        await asyncio.sleep(600)


# ============================================================
# ARQUIVO HISTÓRICO — SQLite em volume persistente do Railway.
# Espelha as mensagens reais, sem consultas FTP adicionais.
# ============================================================
import sqlite3

ISLAND_DB_PATH = os.getenv("ISLAND_DB_PATH", "/data/primeiro_mundo.sqlite3").strip()
ISLAND_DB_READY = False


def _island_db_connect():
    connection = sqlite3.connect(ISLAND_DB_PATH, timeout=15)
    connection.execute("PRAGMA busy_timeout=15000")
    connection.execute("PRAGMA journal_mode=WAL")
    connection.execute("""CREATE TABLE IF NOT EXISTS island_events (
        guild_id INTEGER NOT NULL, message_id INTEGER NOT NULL,
        kind TEXT NOT NULL, occurred_at TEXT NOT NULL,
        victim TEXT, killer TEXT, PRIMARY KEY (guild_id, message_id, kind)
    )""")
    connection.execute("CREATE INDEX IF NOT EXISTS island_event_time ON island_events(guild_id, occurred_at)")
    connection.execute("""CREATE TABLE IF NOT EXISTS island_daily_totals (
        guild_id INTEGER NOT NULL, day TEXT NOT NULL, kind TEXT NOT NULL,
        total INTEGER NOT NULL, PRIMARY KEY(guild_id, day, kind)
    )""")
    connection.execute("""CREATE TABLE IF NOT EXISTS island_daily_players (
        guild_id INTEGER NOT NULL, day TEXT NOT NULL, player TEXT NOT NULL,
        role TEXT NOT NULL, total INTEGER NOT NULL,
        PRIMARY KEY(guild_id, day, player, role)
    )""")
    connection.execute("""CREATE TABLE IF NOT EXISTS island_maintenance (
        name TEXT PRIMARY KEY, value TEXT NOT NULL
    )""")
    return connection


def _island_db_init():
    global ISLAND_DB_READY
    if not ISLAND_DB_PATH.startswith("/data/") and os.getenv("RAILWAY_ENVIRONMENT"):
        print("HISTÓRICO: ATENÇÃO: configure ISLAND_DB_PATH dentro do volume persistente.")
    try:
        os.makedirs(os.path.dirname(os.path.abspath(ISLAND_DB_PATH)), exist_ok=True)
        with _island_db_connect():
            pass
        ISLAND_DB_READY = True
        print(f"HISTÓRICO: banco ativo em {ISLAND_DB_PATH}; confira volume persistente montado.")
    except Exception as error:
        ISLAND_DB_READY = False
        print(f"HISTÓRICO: banco indisponível ({type(error).__name__}: {error}); módulos originais preservados.")


def _island_db_write(rows):
    if not ISLAND_DB_READY or not rows:
        return
    with _island_db_connect() as db:
        db.executemany("INSERT OR IGNORE INTO island_events VALUES (?,?,?,?,?,?)", rows)


async def _island_archive_guild(guild):
    if not ISLAND_DB_READY:
        return
    rows = []
    for channel_name in (KILLFEED_CHANNEL_NAME, CARGODROP_CHANNEL_NAME):
        channel = find_text_channel_anywhere(guild, channel_name)
        if channel is None:
            continue
        # A janela sobreposta cobre indisponibilidades curtas e deploys.
        # A chave única impede que uma mesma mensagem seja contada duas vezes.
        since = datetime.now(timezone.utc) - timedelta(days=8)
        async for message in channel.history(limit=None, after=since, oldest_first=True):
            if message.author.id != bot.user.id:
                continue
            for embed in message.embeds:
                kind = None
                victim = killer = None
                if channel_name == CARGODROP_CHANNEL_NAME and embed.title == "📦 CARGO DROP — INICIADO":
                    kind = "drop"
                elif channel_name == KILLFEED_CHANNEL_NAME and _obituary_is_death(embed):
                    kind = "pvp" if embed.title == "⚔️ KILL — PvP" else "death"
                    victim = _obituary_victim_from_embed(embed)
                    if kind == "pvp":
                        killer = _island_field(embed, "🔫 Jogador")
                        if not (killer and victim and killer.casefold() != victim.casefold()):
                            kind = "death"
                            killer = None
                if kind:
                    rows.append((guild.id, message.id, kind, message.created_at.isoformat(), victim, killer))
    await asyncio.to_thread(_island_db_write, rows)
    print(f"HISTÓRICO: {guild.name} | {len(rows)} registros examinados (duplicatas ignoradas).")


def _island_db_collect(guild_id, start, end):
    kills, deaths = Counter(), Counter()
    anonymous = pvp = total = drops = 0
    with _island_db_connect() as db:
        entries = db.execute("SELECT kind, victim, killer FROM island_events WHERE guild_id=? AND occurred_at>=? AND occurred_at<?",
                             (guild_id, start.astimezone(timezone.utc).isoformat(), end.astimezone(timezone.utc).isoformat()))
        for kind, victim, killer in entries:
            if kind == "drop":
                drops += 1
            else:
                total += 1
                if victim:
                    deaths[victim] += 1
                else:
                    anonymous += 1
                if kind == "pvp" and killer:
                    kills[killer] += 1
                    pvp += 1
    return kills, deaths, anonymous, pvp, total, drops


# Retenção: os eventos individuais ficam por 30 dias; totais diários e
# estatísticas de jogadores são consolidados antes da exclusão.
ISLAND_RETENTION_DAYS = 30


def _island_db_maintenance():
    if not ISLAND_DB_READY:
        return
    now = datetime.now(timezone.utc)
    cutoff = (now - timedelta(days=ISLAND_RETENTION_DAYS)).isoformat()
    day = now.date().isoformat()
    with _island_db_connect() as db:
        last = db.execute("SELECT value FROM island_maintenance WHERE name='last_cleanup'").fetchone()
        if last and last[0] == day:
            return
        count = db.execute("SELECT COUNT(*) FROM island_events WHERE occurred_at < ?", (cutoff,)).fetchone()[0]
        # Uma cópia recuperável antes de apagar dados; nunca toca em logs FTP.
        if count:
            backup_path = os.path.join(os.path.dirname(os.path.abspath(ISLAND_DB_PATH)),
                                       "primeiro_mundo_pre_cleanup.sqlite3")
            backup = sqlite3.connect(backup_path, timeout=15)
            try:
                db.backup(backup)
            finally:
                backup.close()
        db.execute("BEGIN IMMEDIATE")
        try:
            # UPSERT não é incremental: recalcula a partir dos eventos ainda presentes.
            # Dias antigos já consolidados nunca são reprocessados.
            db.execute("""INSERT INTO island_daily_totals(guild_id,day,kind,total)
                SELECT guild_id,substr(occurred_at,1,10),kind,COUNT(*)
                FROM island_events WHERE occurred_at < ?
                GROUP BY guild_id,substr(occurred_at,1,10),kind
                ON CONFLICT(guild_id,day,kind) DO UPDATE SET total=excluded.total""", (cutoff,))
            db.execute("""INSERT INTO island_daily_players(guild_id,day,player,role,total)
                SELECT guild_id,substr(occurred_at,1,10),victim,'death',COUNT(*)
                FROM island_events WHERE occurred_at < ? AND kind != 'drop' AND victim IS NOT NULL
                GROUP BY guild_id,substr(occurred_at,1,10),victim
                ON CONFLICT(guild_id,day,player,role) DO UPDATE SET total=excluded.total""", (cutoff,))
            db.execute("""INSERT INTO island_daily_players(guild_id,day,player,role,total)
                SELECT guild_id,substr(occurred_at,1,10),killer,'kill',COUNT(*)
                FROM island_events WHERE occurred_at < ? AND kind='pvp' AND killer IS NOT NULL
                GROUP BY guild_id,substr(occurred_at,1,10),killer
                ON CONFLICT(guild_id,day,player,role) DO UPDATE SET total=excluded.total""", (cutoff,))
            db.execute("DELETE FROM island_events WHERE occurred_at < ?", (cutoff,))
            db.execute("INSERT OR REPLACE INTO island_maintenance(name,value) VALUES('last_cleanup',?)", (day,))
            db.commit()
        except Exception:
            db.rollback()
            raise
        # Incremental checkpoint only; do not VACUUM while the bot is active.
        db.execute("PRAGMA wal_checkpoint(PASSIVE)")
    print(f"HISTÓRICO: limpeza diária concluída | retenção={ISLAND_RETENTION_DAYS} dias | removidos={count} | consolidados preservados.")


async def scum_island_maintenance_loop():
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            await asyncio.to_thread(_island_db_maintenance)
        except Exception as error:
            print(f"HISTÓRICO: falha na manutenção: {type(error).__name__}: {error}")
        await asyncio.sleep(3600)


async def scum_island_archive_loop():
    await bot.wait_until_ready()
    _island_db_init()
    while not bot.is_closed():
        for guild in bot.guilds:
            try:
                await _island_archive_guild(guild)
            except Exception as error:
                print(f"HISTÓRICO: falha em {guild.name}: {type(error).__name__}: {error}")
        await asyncio.sleep(300)


# ============================================================
# INTERAÇÃO DA ILHA — somente dados confirmados no SQLite/Discord.
# Sem novas consultas FTP; mensagens idempotentes por período.
# ============================================================
ISLAND_JOURNAL = "📰・jornal-da-ilha"
ISLAND_RIVALRIES = "⚔️・rivalidades-da-ilha"
ISLAND_CHALLENGES = "🎯・desafios-da-semana"
ISLAND_RADAR = "📦・radar-de-atividades"


def _island_db_events(guild_id, start, end):
    with _island_db_connect() as db:
        return db.execute(
            "SELECT kind, victim, killer, occurred_at FROM island_events "
            "WHERE guild_id=? AND occurred_at>=? AND occurred_at<? ORDER BY occurred_at",
            (guild_id, start.astimezone(timezone.utc).isoformat(),
             end.astimezone(timezone.utc).isoformat())
        ).fetchall()


async def _island_send_once(guild, channel_name, topic, signature, title, description):
    target = await _island_target(guild, channel_name, topic)
    async for message in target.history(limit=100):
        if message.author.id == bot.user.id and any(
            (getattr(embed.footer, "text", None) or "") == signature
            for embed in message.embeds
        ):
            return
    embed = discord.Embed(title=title, description=description[:4000], colour=discord.Colour.blue())
    embed.set_footer(text=signature)
    await target.send(embed=embed)
    print(f"INTERAÇÃO ILHA: {signature} publicado em {guild.name}")


async def _island_interactions_guild(guild, now):
    if not ISLAND_DB_READY:
        return
    yesterday = (now - timedelta(days=1)).date()
    day_start = datetime(yesterday.year, yesterday.month, yesterday.day, tzinfo=BRASILIA_TZ)
    day_end = day_start + timedelta(days=1)
    if (now.hour, now.minute) >= (0, 40):
        await _island_archive_guild(guild)
        events = await asyncio.to_thread(_island_db_events, guild.id, day_start, day_end)
        kills, deaths, anonymous, pvp, total, drops = await asyncio.to_thread(
            _island_db_collect, guild.id, day_start, day_end)
        notes = [f"💀 Mortes registradas: **{total}**",
                 f"⚔️ Eliminações PvP confirmadas: **{pvp}**",
                 f"📦 Cargo Drops anunciados: **{drops}**"]
        if deaths:
            amount = max(deaths.values())
            names = sorted((n for n, v in deaths.items() if v == amount), key=str.casefold)
            notes.append("⚰️ Mais aparições no obituário: " + ", ".join(discord.utils.escape_markdown(n) for n in names[:5]) + f" ({amount})")
        if not events:
            notes.append("Sem eventos arquivados no período; não significa que a ilha esteve vazia.")
        notes.append("*Resumo de publicações reais do bot; não revela locais nem presume causas de morte.*")
        await _island_send_once(guild, ISLAND_JOURNAL, "Noticiário diário com registros confirmados.",
            f"JORNAL DA ILHA • {yesterday:%Y-%m-%d}", "📰 JORNAL DO APOCALIPSE — PRIMEIRO MUNDO",
            f"**Boletim de {yesterday:%d/%m/%Y}**\n\n" + "\n".join(notes))
    if now.weekday() == 0 and (now.hour, now.minute) >= (0, 45):
        week_end = datetime(now.year, now.month, now.day, tzinfo=BRASILIA_TZ)
        week_start = week_end - timedelta(days=7)
        events = await asyncio.to_thread(_island_db_events, guild.id, week_start, week_end)
        pairs = Counter()
        for kind, victim, killer, _ in events:
            if kind == "pvp" and victim and killer and victim.casefold() != killer.casefold():
                pairs[(killer, victim)] += 1
        rows = [f"⚔️ {discord.utils.escape_markdown(k)} → {discord.utils.escape_markdown(v)}: **{n}** eliminações confirmadas"
                for (k, v), n in pairs.most_common(10)]
        await _island_send_once(guild, ISLAND_RIVALRIES, "Confrontos PvP reais, sem coordenadas.",
            f"RIVALIDADES • {week_start:%Y-%m-%d}", "⚔️ RIVALIDADES DA ILHA",
            f"**{week_start:%d/%m} a {(week_end-timedelta(days=1)):%d/%m/%Y}**\n\n" +
            ("\n".join(rows) if rows else "Nenhum confronto entre jogadores confirmado no período.") +
            "\n\n*Contagem de eliminações registradas; não representa placar de disputa combinada.*")
    # Painel vivo da semana: atualiza a mesma mensagem a cada ciclo, inclusive
    # depois de reinícios do bot. Não cria consultas FTP nem eventos fictícios.
    week_day = now.date() - timedelta(days=now.weekday())
    week_start = datetime(week_day.year, week_day.month, week_day.day, tzinfo=BRASILIA_TZ)
    week_end = week_start + timedelta(days=7)
    kills, deaths, anonymous, pvp, total, drops = await asyncio.to_thread(
        _island_db_collect, guild.id, week_start, week_end)
    signature = f"DESAFIOS • {week_start:%Y-%m-%d}"
    top_kills = sorted(kills.items(), key=lambda item: (-item[1], item[0].casefold()))[:5]
    top_deaths = sorted(deaths.items(), key=lambda item: (-item[1], item[0].casefold()))[:5]
    def _challenge_names(items):
        return "\n".join(
            f"• {discord.utils.escape_markdown(name)}: **{count}**"
            for name, count in items
        ) if items else "Nenhum registro identificado até agora."
    description = (
        f"**{week_start:%d/%m} a {(week_end-timedelta(days=1)):%d/%m/%Y}**\n\n"
        f"⚔️ **Confrontos PvP confirmados:** **{pvp}**\n"
        f"{_challenge_names(top_kills)}\n\n"
        f"📦 **Cargo Drops anunciados:** **{drops}**\n\n"
        f"💀 **Mortes registradas:** **{total}**\n"
        f"{_challenge_names(top_deaths)}\n"
        + (f"• Mortes sem identificação: **{anonymous}**\n" if anonymous else "")
        + f"\n🔄 Atualizado em **{now:%d/%m/%Y às %H:%M}** • Brasília (UTC−3)\n\n"
        "*Acompanhamento comunitário, sem recompensa automática. "
        "Os números refletem somente eventos confirmados e arquivados pelo bot; "
        "não comprovam participação individual em drops, exploração ou tempo vivo.*"
    )
    target = await _island_target(guild, ISLAND_CHALLENGES, "Desafios comunitários verificáveis.")
    current = None
    async for message in target.history(limit=100):
        if message.author.id == bot.user.id and any(
            (getattr(embed.footer, "text", None) or "") == signature
            for embed in message.embeds
        ):
            current = message
            break
    embed = discord.Embed(title="🎯 DESAFIOS DA SEMANA", description=description,
                          colour=discord.Colour.blue())
    embed.set_footer(text=signature)
    if current is None:
        await target.send(embed=embed)
        print(f"DESAFIOS: painel semanal criado | {guild.name} | {signature}")
    elif not current.embeds or current.embeds[0].description != description:
        await current.edit(embed=embed)
        print(f"DESAFIOS: painel semanal atualizado | {guild.name} | PvP={pvp} drops={drops} mortes={total}")
    if (now.hour, now.minute) >= (18, 0):
        today = now.date()
        start = datetime(today.year, today.month, today.day, tzinfo=BRASILIA_TZ)
        end = start + timedelta(days=1)
        _, _, _, pvp, total, drops = await asyncio.to_thread(_island_db_collect, guild.id, start, end)
        await _island_send_once(guild, ISLAND_RADAR, "Painel de atividades registradas; sem rastrear jogadores.",
            f"RADAR • {today:%Y-%m-%d}", "📦 RADAR DE ATIVIDADES",
            f"**Parcial de {today:%d/%m/%Y}, até {now:%H:%M} (Brasília)**\n\n"
            f"📦 Cargo Drops anunciados: **{drops}**\n"
            f"⚔️ Eliminações PvP confirmadas: **{pvp}**\n"
            f"💀 Mortes registradas: **{total}**\n\n"
            "*Painel de publicações, não é um radar de localização. "
            "Jogadores online não são estimados sem amostragem confiável.*")


async def scum_island_interactions_loop():
    await bot.wait_until_ready()
    while not bot.is_closed():
        now = datetime.now(BRASILIA_TZ)
        for guild in bot.guilds:
            try:
                await _island_interactions_guild(guild, now)
            except Exception as error:
                print(f"INTERAÇÃO ILHA: {guild.name}: {type(error).__name__}: {error}")
        await asyncio.sleep(600)


# ============================================================
# CRÔNICAS DA ILHA — Hall da Fama e da Vergonha
# Apenas registros verificáveis. Nenhuma pontuação simulada.
# ============================================================
# ============================================================
# DESLOCAMENTO A PE — famepoints.log (indice, nao km nem corrida isolada)
# ============================================================
WALK_LOG_RE = re.compile(r"^famepoints_.*\.log$", re.I)
WALK_PLAYER_RE = re.compile(r"^Player (.+?)\((\d{17})\) was awarded ", re.I)
WALK_VALUE_RE = re.compile(r"^DistanceTraveledOnFoot:\s*([0-9]+(?:\.[0-9]+)?)$", re.I)
WALK_STAMP_RE = re.compile(r"^(\d{4}\.\d{2}\.\d{2}-\d{2}\.\d{2}\.\d{2}):")


def _walk_db():
    db = _island_db_connect()
    db.execute("""CREATE TABLE IF NOT EXISTS walk_fame_events (
        event_id TEXT PRIMARY KEY, stamp TEXT NOT NULL, steam TEXT NOT NULL,
        player TEXT NOT NULL, metric REAL NOT NULL, source TEXT NOT NULL
    )""")
    db.execute("CREATE INDEX IF NOT EXISTS idx_walk_stamp ON walk_fame_events(stamp)")
    return db


def _walk_parse(filename, raw):
    text = _decode_scum_log(raw)
    stamp = player = steam = None
    events = []
    for line in text.splitlines():
        line = line.strip().lstrip('\ufeff')
        match = WALK_STAMP_RE.match(line)
        if match:
            stamp = match.group(1)
            player = steam = None
            continue
        match = WALK_PLAYER_RE.match(line)
        if match:
            player, steam = match.groups()
            continue
        match = WALK_VALUE_RE.match(line)
        if match and stamp and steam:
            metric = float(match.group(1))
            if metric < 0 or not metric < float('inf'):
                continue
            identity = hashlib.sha256((filename + '\n' + stamp + '\n' + steam + '\n' + line).encode()).hexdigest()
            events.append((identity, stamp, steam, player, metric, filename))
    return events


def _walk_read_sync():
    # Compartilha a sessao e o lock FTP; sem nova conexao paralela.
    with SCUM_FTP_IO_LOCK:
        ftp = _ftp_connect()
        if ftp is None:
            return None
        ftp.cwd(SCUM_FTP_ACTIVE_LOG_PATH or SCUM_FTP_LOG_PATH)
        names = [name.rsplit('/', 1)[-1] for name in ftp.nlst()]
        candidates = sorted((name for name in names if WALK_LOG_RE.match(name)), reverse=True)
        if not candidates:
            return None
        filename = candidates[0]
        buffer = BytesIO()
        ftp.voidcmd('TYPE I')
        ftp.retrbinary('RETR ' + filename, buffer.write, blocksize=8192)
        return filename, buffer.getvalue()


def _walk_import(snapshot):
    if snapshot is None:
        return 0
    filename, raw = snapshot
    events = _walk_parse(filename, raw)
    with _walk_db() as db:
        db.executemany("""INSERT OR IGNORE INTO walk_fame_events
            (event_id, stamp, steam, player, metric, source) VALUES (?,?,?,?,?,?)""", events)
    return len(events)


def _walk_ranks(now):
    local = now.astimezone(CHRONICLES_TZ)
    week = (local - timedelta(days=local.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    cutoff = week.strftime('%Y.%m.%d-%H.%M.%S')
    with _walk_db() as db:
        general = db.execute("""SELECT steam, MAX(player), SUM(metric), COUNT(*) FROM walk_fame_events
            GROUP BY steam ORDER BY SUM(metric) DESC, steam LIMIT 5""").fetchall()
        weekly = db.execute("""SELECT steam, MAX(player), SUM(metric), COUNT(*) FROM walk_fame_events
            WHERE stamp>=? GROUP BY steam ORDER BY SUM(metric) DESC, steam LIMIT 5""", (cutoff,)).fetchall()
    return general, weekly


# CRONICAS — contadores reais do banco SCUM (somente leitura)
# ============================================================
SCUM_STATS_FIELDS = {
    'food_eaten': ('🍖 Bucho de Aço', 'consumo registrado'),
    'total_calories_intake': ('🔥 Calorias na Conta', 'calorias'),
    'total_defecations': ('💩 Rei do Trono', 'vezes'),
    'total_urinations': ('🚽 Bexiga de Aço', 'vezes'),
    'liquid_drank': ('🥤 Sede Sem Fim', 'consumo registrado'),
    'distance_travelled_by_foot': ('🏃 Maratonistas da Ilha', 'distância do SCUM'),
    'distance_travelled_in_vehicle': ('🚗 Rei do Asfalto', 'distância do SCUM'),
    'vomits': ('🤮 Estômago Revoltado', 'vezes'),
    'diarrheas': ('🚨 Emergência Sanitária', 'vezes'),
    'starvation': ('🥴 Fome de Leão', 'ocorrências registradas'),
    'distance_travelled_swimming': ('🏊 Peixe Fora d’Água', 'distância registrada'),
    'times_caught_by_shark': ('🦈 Cardápio do Tubarão', 'capturas'),
    'times_mauled_by_bear': ('🐻 Abraço de Urso', 'ataques'),
    'wounds_patched': ('🩹 Enfermeiro da Ilha', 'ferimentos tratados'),
    'puppets_killed': ('🧟 Exterminador da Ilha', 'zumbis eliminados'),
    'animals_killed': ('🐗 Caçador da Ilha', 'animais abatidos'),
    'boars_killed': ('🐗 Caçador de Javalis', 'javalis abatidos'),
    'bears_killed': ('🐻 Caçador de Ursos', 'ursos abatidos'),
    'wolves_killed': ('🐺 Caçador de Lobos', 'lobos abatidos'),
}
SCUM_STATS_PATH = '/SCUM/Saved/SaveFiles'
SCUM_STATS_FTP_ENABLED = os.getenv('SCUM_STATS_FTP_ENABLED', '1').strip() == '1'
SCUM_STATS_LOCAL_PATH = os.getenv('SCUM_STATS_LOCAL_PATH', '').strip()


def _stats_db():
    db = _island_db_connect()
    db.execute("""CREATE TABLE IF NOT EXISTS scum_stat_samples (
        steam TEXT NOT NULL, metric TEXT NOT NULL, raw REAL NOT NULL,
        offset REAL NOT NULL DEFAULT 0, updated_at TEXT NOT NULL,
        name TEXT NOT NULL, PRIMARY KEY(steam,metric))""")
    db.execute("""CREATE TABLE IF NOT EXISTS scum_stat_deltas (
        steam TEXT NOT NULL, metric TEXT NOT NULL, week TEXT NOT NULL,
        amount REAL NOT NULL DEFAULT 0, PRIMARY KEY(steam,metric,week))""")
    return db


def _stats_validated_rows(db_path):
    # URI mode=ro, sem PRAGMA que altera o arquivo do jogo.
    source = sqlite3.connect('file:' + urllib.parse.quote(os.path.abspath(db_path)) + '?mode=ro', uri=True, timeout=10)
    try:
        if source.execute('PRAGMA quick_check').fetchone()[0] != 'ok':
            raise ValueError('snapshot SCUM SQLite inconsistente')
        fields = ','.join('s.' + k for k in SCUM_STATS_FIELDS)
        rows = source.execute('SELECT p.user_id, COALESCE(p.name,p.user_id), ' + fields +
            ' FROM survival_stats s JOIN user_profile p ON p.id=s.user_profile_id').fetchall()
        return rows
    finally:
        source.close()


def _stats_import_rows(rows, now=None):
    now = now or datetime.now(timezone.utc)
    local = now.astimezone(CHRONICLES_TZ)
    week = (local - timedelta(days=local.weekday())).strftime('%Y-%m-%d')
    stamp = now.isoformat()
    changed = 0
    with _stats_db() as db:
        for steam, name, *values in rows:
            if not steam or not str(steam).isdigit():
                continue
            for metric, value in zip(SCUM_STATS_FIELDS, values):
                if value is None: continue
                try: value = float(value)
                except (ValueError, TypeError): continue
                if not (0 <= value < float('inf')): continue
                prev = db.execute('SELECT raw,offset FROM scum_stat_samples WHERE steam=? AND metric=?',
                                  (steam, metric)).fetchone()
                if prev is None:
                    # Importação inicial: histórico real, semana começa em zero.
                    offset, delta = 0.0, 0.0
                elif value >= prev[0]:
                    offset, delta = prev[1], value - prev[0]
                else:
                    # Reset de contadores do SCUM: mantém histórico já observado.
                    offset, delta = prev[1] + prev[0], value
                db.execute("""INSERT INTO scum_stat_samples(steam,metric,raw,offset,updated_at,name)
                    VALUES (?,?,?,?,?,?) ON CONFLICT(steam,metric) DO UPDATE SET
                    raw=excluded.raw,offset=excluded.offset,updated_at=excluded.updated_at,name=excluded.name""",
                    (steam,metric,value,offset,stamp,str(name)[:100]))
                if delta:
                    db.execute("""INSERT INTO scum_stat_deltas(steam,metric,week,amount) VALUES(?,?,?,?)
                        ON CONFLICT(steam,metric,week) DO UPDATE SET amount=amount+excluded.amount""",
                        (steam,metric,week,delta))
                    changed += 1
    return changed


def _stats_read_ftp():
    # Isolamento completo do Supervisor V21; nenhuma escrita no banco do jogo.
    import tempfile
    if not all((SCUM_FTP_HOST, SCUM_FTP_USER, SCUM_FTP_PASS)):
        raise RuntimeError('Credenciais FTP das Crônicas indisponíveis')
    last_error = None
    for attempt in range(1, 4):
        try:
            with ftplib.FTP() as ftp:
                ftp.connect(SCUM_FTP_HOST, SCUM_FTP_PORT, timeout=25)
                ftp.login(SCUM_FTP_USER, SCUM_FTP_PASS)
                ftp.set_pasv(True)
                ftp.cwd(SCUM_STATS_PATH)
                names = set(n.rsplit('/', 1)[-1] for n in ftp.nlst())
                if 'SCUM.db' not in names:
                    raise FileNotFoundError('SCUM.db não encontrado')
                with tempfile.TemporaryDirectory(prefix='scum_cronicas_') as folder:
                    def fetch(name, dest=None):
                        path = os.path.join(folder, dest or name)
                        with open(path, 'wb') as out:
                            ftp.retrbinary('RETR ' + name, out.write, blocksize=65536)
                        return path
                    # WAL inicial e final idênticos: não misturar gerações de arquivos.
                    wal = 'SCUM.db-wal' in names
                    before = fetch('SCUM.db-wal', 'before-wal') if wal else None
                    dbpath = fetch('SCUM.db')
                    if wal:
                        after = fetch('SCUM.db-wal', 'SCUM.db-wal')
                        with open(before, 'rb') as f: first_hash = hashlib.sha256(f.read()).digest()
                        with open(after, 'rb') as f: final_hash = hashlib.sha256(f.read()).digest()
                        if first_hash != final_hash:
                            raise ValueError('WAL alterado durante a coleta')
                    rows = _stats_validated_rows(dbpath)
                    print(f'CRÔNICAS DB: snapshot SQLite validado | tentativa={attempt} | jogadores={len(rows)}')
                    return rows
        except (ValueError, sqlite3.DatabaseError, ftplib.all_errors, OSError) as error:
            last_error = error
            print(f'CRÔNICAS DB: tentativa {attempt}/3 sem snapshot válido | {type(error).__name__}: {error}')
            if attempt < 3:
                time.sleep(12)
    raise RuntimeError(f'Nenhuma amostra consistente em 3 tentativas: {last_error}')


def _chronicles_collection_slot(now):
    # Reinícios às 06, 14 e 22 BRT. Janela conservadora após cada reinício.
    local = now.astimezone(CHRONICLES_TZ)
    if local.hour in (6, 14, 22) and 3 <= local.minute < 18:
        return local.strftime('%Y-%m-%d %H')
    return None


async def _chronicles_read_only(guild, channel):
    # Apenas canais das Crônicas; não modifica permissões globais nem de outros módulos.
    if channel is None:
        return
    everyone = guild.default_role
    current = channel.overwrites_for(everyone)
    desired = {'view_channel': True, 'send_messages': False,
               'send_messages_in_threads': False, 'create_public_threads': False,
               'create_private_threads': False, 'add_reactions': False}
    if any(getattr(current, key) != value for key, value in desired.items()):
        for key, value in desired.items():
            setattr(current, key, value)
        await channel.set_permissions(everyone, overwrite=current,
                                      reason='Crônicas: consulta somente leitura')
    member = guild.me
    if member is not None:
        mine = channel.overwrites_for(member)
        bot_rights = {'view_channel': True, 'send_messages': True,
                      'embed_links': True, 'read_message_history': True,
                      'manage_messages': True}
        if any(getattr(mine, key) != value for key, value in bot_rights.items()):
            for key, value in bot_rights.items():
                setattr(mine, key, value)
            await channel.set_permissions(member, overwrite=mine,
                                          reason='Crônicas: publicação pelo bot')


def _stats_refresh():
    if SCUM_STATS_LOCAL_PATH:
        return _stats_import_rows(_stats_validated_rows(SCUM_STATS_LOCAL_PATH))
    if SCUM_STATS_FTP_ENABLED:
        rows = _stats_read_ftp()
        return _stats_import_rows(rows) if rows is not None else 0
    return 0


def _stats_ranks(now):
    week = (now.astimezone(CHRONICLES_TZ) - timedelta(days=now.astimezone(CHRONICLES_TZ).weekday())).strftime('%Y-%m-%d')
    results = {}
    with _stats_db() as db:
        for metric in SCUM_STATS_FIELDS:
            general = db.execute("""SELECT name,raw+offset FROM scum_stat_samples
                WHERE metric=? AND raw+offset>0 ORDER BY raw+offset DESC LIMIT 3""",(metric,)).fetchall()
            weekly = db.execute("""SELECT s.name,d.amount FROM scum_stat_deltas d
                JOIN scum_stat_samples s ON s.steam=d.steam AND s.metric=d.metric
                WHERE d.metric=? AND d.week=? AND d.amount>0 ORDER BY d.amount DESC LIMIT 3""",
                (metric,week)).fetchall()
            results[metric] = (general,weekly)
        last = db.execute('SELECT MAX(updated_at) FROM scum_stat_samples').fetchone()[0]
    return results,last


# Formatação exclusiva dos painéis; não modifica contadores nem coleta.
_STATS_DECIMAL_METRICS = {
    'total_calories_intake', 'liquid_drank',
    'distance_travelled_by_foot', 'distance_travelled_in_vehicle',
    'distance_travelled_swimming',
}
_STATS_HUNTING_METRICS = (
    'puppets_killed', 'animals_killed', 'boars_killed', 'bears_killed', 'wolves_killed',
)

def _stats_ptbr(value, decimals=0):
    result = f'{float(value):,.{decimals}f}'
    return result.replace(',', '@').replace('.', ',').replace('@', '.')

def _stats_format_value(metric, value):
    return _stats_ptbr(value, 2 if metric in _STATS_DECIMAL_METRICS else 0)

def _stats_rank_text(metric, rows, unit, empty='Sem registros confirmados.'):
    safe = discord.utils.escape_markdown
    return '\n'.join(
        f'{i}. **{safe(name)}** — {_stats_format_value(metric, value)} {unit}'
        for i, (name, value) in enumerate(rows, 1)
    ) or empty

def _stats_add_fields(embed, ranks, metrics):
    for metric in metrics:
        title, unit = SCUM_STATS_FIELDS[metric]
        if metric == 'total_calories_intake':
            unit = 'calorias registradas'
        elif metric == 'liquid_drank':
            unit = 'consumo registrado (unidade do SCUM)'
        elif metric.startswith('distance_travelled_'):
            unit = 'unidades de distância do SCUM'
        general, weekly = ranks[metric]
        embed.add_field(
            name=title,
            value='**Geral:**\n' + _stats_rank_text(metric, general, unit)
                  + '\n**Semana (diferença observada):**\n'
                  + _stats_rank_text(metric, weekly, unit),
            inline=False,
        )

def _stats_display_timestamp(raw):
    if not raw:
        return 'aguardando importação'
    try:
        dt = datetime.fromisoformat(str(raw).replace('Z', '+00:00'))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(CHRONICLES_TZ).strftime('%d/%m/%Y às %H:%M (Brasília)')
    except (TypeError, ValueError, OverflowError):
        return str(raw)


def _stats_embed():
    ranks, last = _stats_ranks(datetime.now(timezone.utc))
    e = discord.Embed(
        title='🧬 CRÔNICAS — ESTATÍSTICAS REAIS DO SCUM',
        description='Contadores do salvamento • histórico e variação semanal • sem dados inventados',
        colour=discord.Colour.green(), timestamp=datetime.now(timezone.utc),
    )
    _stats_add_fields(e, ranks, list(SCUM_STATS_FIELDS)[:7])
    e.set_footer(text='Última amostra: ' + _stats_display_timestamp(last)
                 + ' • Fome: ocorrências, não tempo/percentual • A pé não distingue corrida')
    return e

def _stats_embed_extra():
    ranks, last = _stats_ranks(datetime.now(timezone.utc))
    e = discord.Embed(title='🧬 CRÔNICAS — MAIS ESTATÍSTICAS',
                      colour=discord.Colour.green())
    # Os cinco rankings de caça aparecem exclusivamente no painel específico.
    metrics = [m for m in list(SCUM_STATS_FIELDS)[7:] if m not in _STATS_HUNTING_METRICS]
    _stats_add_fields(e, ranks, metrics)
    e.add_field(
        name='😵 Rei do Apagão',
        value='Aguardando contador confiável de desmaios. `players_knocked_out` mede adversários derrubados, não desmaios sofridos.',
        inline=False,
    )
    return e

def _stats_embed_hunting():
    ranks, last = _stats_ranks(datetime.now(timezone.utc))
    e = discord.Embed(
        title='🧟 CRÔNICAS — EXTERMINADORES E CAÇADORES',
        description='Ranking geral e semanal por contador individual validado do SCUM.',
        colour=discord.Colour.green(),
    )
    _stats_add_fields(e, ranks, _STATS_HUNTING_METRICS)
    e.add_field(
        name='🎯 Caçador de NPCs',
        value='Aguardando contador específico e validado de NPCs armados eliminados. O campo genérico `kills` não será utilizado como substituto.',
        inline=False,
    )
    e.set_footer(text='Última amostra: ' + _stats_display_timestamp(last))
    return e


async def _stats_guild(guild):
    channel = find_text_channel_anywhere(guild, CHRONICLES_CHANNEL)
    if channel is None: return
    await _chronicles_read_only(guild, channel)
    title = '🧬 CRÔNICAS — ESTATÍSTICAS REAIS DO SCUM'
    panel = None
    async for msg in channel.history(limit=35):
        if msg.author == bot.user and msg.embeds and msg.embeds[0].title == title:
            panel = msg; break
    embed = await asyncio.to_thread(_stats_embed)
    extra = await asyncio.to_thread(_stats_embed_extra)
    hunting = await asyncio.to_thread(_stats_embed_hunting)
    if panel: await panel.edit(embeds=[embed,extra,hunting])
    else: await channel.send(embeds=[embed,extra,hunting])

CHRONICLES_CHANNEL = "🏝️・hall-da-fama-e-vergonha"
CHRONICLES_TITLE = "🏝️ CRÔNICAS DA ILHA — HALL DA FAMA E DA VERGONHA"
CHRONICLES_TZ = ZoneInfo("America/Sao_Paulo")
CHRONICLES_PENDING = (
    ("🍖 Bucho de Aço", "alimentação individual"),
    ("💩 Rei do Trono", "evacuações individuais"),
    ("🥴 Fome de Leão", "tempo individual em estado de fome"),
    ("🚗 Braço de Ferro", "distância real dirigindo"),
    ("😴 Turista da Ilha", "atividade contínua verificável"),
)


def _chronicles_snapshot(guild_id, now):
    # Tabelas já existentes: não introduz consulta FTP nem altera módulos estáveis.
    local = now.astimezone(CHRONICLES_TZ)
    week_start = (local - timedelta(days=local.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    week_utc = week_start.astimezone(timezone.utc).isoformat()
    with _island_db_connect() as db:
        # A consolidação diária mantém o histórico após a limpeza de eventos antigos.
        deaths = db.execute("""SELECT player, SUM(total) AS n FROM (
            SELECT victim AS player, COUNT(*) AS total FROM island_events
              WHERE guild_id=? AND kind!='drop' AND victim IS NOT NULL GROUP BY victim
            UNION ALL
            SELECT player, SUM(total) FROM island_daily_players
              WHERE guild_id=? AND role='death' GROUP BY player
            ) WHERE player IS NOT NULL GROUP BY player ORDER BY n DESC, player LIMIT 5""",
            (guild_id, guild_id)).fetchall()
        weekly_deaths = db.execute("""SELECT victim, COUNT(*) FROM island_events
            WHERE guild_id=? AND occurred_at>=? AND kind!='drop' AND victim IS NOT NULL
            GROUP BY victim ORDER BY COUNT(*) DESC, victim LIMIT 5""", (guild_id, week_utc)).fetchall()
        drops = db.execute("""SELECT COALESCE((SELECT COUNT(*) FROM island_events WHERE guild_id=? AND kind='drop'),0)
            + COALESCE((SELECT SUM(total) FROM island_daily_totals WHERE guild_id=? AND kind='drop'),0)""",
            (guild_id, guild_id)).fetchone()[0] or 0
    with _lockpick_db() as db:
        locks = db.execute("""SELECT steam, MAX(player), COUNT(*), SUM(success),
            SUM(CASE WHEN success=0 THEN 1 ELSE 0 END),
            SUM(CASE WHEN success=1 AND target LIKE '%CargoDrop%' THEN 1 ELSE 0 END)
            FROM lockpick_events GROUP BY steam ORDER BY SUM(success) DESC, COUNT(*) DESC LIMIT 5""").fetchall()
        cargo = db.execute("""SELECT steam, MAX(player), COUNT(*) FROM lockpick_events
            WHERE success=1 AND target LIKE '%CargoDrop%' GROUP BY steam
            ORDER BY COUNT(*) DESC, player LIMIT 5""").fetchall()
        weekly_locks = db.execute("""SELECT steam, MAX(player), SUM(success), COUNT(*) FROM lockpick_events
            WHERE stamp>=? GROUP BY steam ORDER BY SUM(success) DESC, COUNT(*) DESC LIMIT 5""",
            (week_start.strftime('%Y.%m.%d-%H.%M.%S'),)).fetchall()
        milestones = db.execute("""SELECT steam, MAX(player), SUM(success),
            SUM(CASE WHEN success=0 THEN 1 ELSE 0 END) FROM lockpick_events
            GROUP BY steam ORDER BY SUM(success) DESC""").fetchall()
    walk_general, walk_weekly = _walk_ranks(now)
    return local, locks, cargo, deaths, weekly_locks, weekly_deaths, drops, milestones, walk_general, walk_weekly


def _chronicles_lines(rows, formatter, empty):
    return '\n'.join(formatter(i, r) for i, r in enumerate(rows, 1)) if rows else empty


def _chronicles_embed(data):
    local, locks, cargo, deaths, weekly_locks, weekly_deaths, drops, milestones, walk_general, walk_weekly = data
    e = discord.Embed(title=CHRONICLES_TITLE,
        description='Estatísticas verificadas • títulos humorísticos • histórico preservado',
        colour=discord.Colour.gold(), timestamp=datetime.now(timezone.utc))
    safe = discord.utils.escape_markdown
    e.add_field(name='🔓 Mãos de Cirurgião — geral', value=_chronicles_lines(
        locks, lambda i,r: f'**{i}. {safe(r[1])}** — {_stats_ptbr(r[3])} aberturas | {_stats_ptbr(r[4])} falhas | {_stats_ptbr(100*r[3]/r[2]) if r[2] else "0"}%',
        'Aguardando registros reais.'), inline=False)
    e.add_field(name='📦 Urubu de Cargo Drop — caixas abertas', value=_chronicles_lines(
        cargo, lambda i,r: f'**{i}. {safe(r[1])}** — {_stats_ptbr(r[2])} caixas',
        'Nenhuma caixa registrada.'), inline=False)
    e.add_field(name='💀 Cliente VIP da Morte — histórico', value=_chronicles_lines(
        deaths, lambda i,r: f'**{i}. {safe(r[0])}** — {_stats_ptbr(r[1])} mortes registradas',
        'Aguardando mortes identificadas.'), inline=False)
    e.add_field(name='📅 Semana atual — lockpick', value=_chronicles_lines(
        weekly_locks, lambda i,r: f'{i}. {safe(r[1])}: {_stats_ptbr(r[2])} sucessos / {_stats_ptbr(r[3])} eventos',
        'Sem eventos nesta semana.'), inline=False)
    e.add_field(name='📅 Semana atual — mortes', value=_chronicles_lines(
        weekly_deaths, lambda i,r: f'{i}. {safe(r[0])}: {_stats_ptbr(r[1])} mortes',
        'Sem mortes identificadas nesta semana.'), inline=False)
    achievements = []
    for _, name, successes, failures in milestones:
        titles = []
        if successes >= 1: titles.append('🔑 Primeira Fechadura')
        if successes >= 10: titles.append('🔓 Dez Aberturas')
        if successes >= 100: titles.append('🏅 Centenário das Fechaduras')
        if failures >= 10: titles.append('🪛 Teimosia de Aço')
        if titles: achievements.append(f'**{safe(name)}:** ' + ' • '.join(titles))
    e.add_field(name='🎖️ Conquistas comprovadas', value='\n'.join(achievements[:8])[:1024] or
                'Aguardando marcos verificáveis.', inline=False)
    # O painel principal reutiliza as amostras já coletadas pelo módulo de
    # estatísticas. Nenhuma consulta FTP adicional e nenhuma métrica presumida.
    linked = (
        ('🍖 Bucho de Aço', 'food_eaten', 'consumo registrado'),
        ('💩 Rei do Trono', 'total_defecations', 'vezes'),
        ('🥴 Fome de Leão', 'starvation', 'ocorrências (não tempo de fome)'),
        ('🚗 Braço de Ferro', 'distance_travelled_in_vehicle', 'distância em veículo (não somente dirigindo)'),
    )
    stat_lines = []
    try:
        ranks, last_sample = _stats_ranks(datetime.now(timezone.utc))
        for title, metric, unit in linked:
            general, weekly = ranks.get(metric, ([], []))
            if general and (metric != 'starvation' or general[0][1] > 0):
                name, value = general[0]
                stat_lines.append(f'{title} — **{safe(name)}**: {_stats_format_value(metric, value)} {unit}')
            elif metric == 'starvation' and general:
                stat_lines.append(f'{title} — nenhuma ocorrência de fome registrada no contador do SCUM')
            else:
                stat_lines.append(f'{title} — sem amostra individual validada')
        tourist = _tourist_best()
        if tourist:
            duration = int(tourist[1])
            stat_lines.append(f'😴 Turista da Ilha — **{safe(tourist[0])}**: {duration//3600}h {(duration%3600)//60:02d}min na maior sessão concluída ({tourist[2]} sessões registradas)')
        else:
            stat_lines.append('😴 Turista da Ilha — aguardando entrada e saída completas no login.log')
        stat_lines.append('📊 Última amostra SCUM: ' + _stats_display_timestamp(last_sample))
    except (sqlite3.Error, ValueError) as error:
        print(f'CRÔNICAS: métricas individuais indisponíveis | {type(error).__name__}: {error}')
        stat_lines = [f'{title} — aguardando amostra validada' for title, _ in CHRONICLES_PENDING]
    e.add_field(name='🧬 Estatísticas individuais verificadas',
                value='\n'.join(stat_lines)[:1024], inline=False)
    e.set_footer(text=f'Cargo Drops registrados: {_stats_ptbr(drops)} (sem atribuir dono) • {local:%d/%m/%Y %H:%M} BRT • Treino de lockpick excluído • Distância a pé: painel de estatísticas do SCUM')
    return e


async def _chronicles_guild(guild):
    category = discord.utils.get(guild.categories, name='🏝️ INÍCIO')
    if category is None:
        category = await get_or_create_category(guild, '🏝️ INÍCIO')
    channel = find_text_channel_anywhere(guild, CHRONICLES_CHANNEL)
    if channel is None:
        channel = await get_or_create_text(guild, category, CHRONICLES_CHANNEL,
            topic='Rankings e conquistas baseados em eventos reais; categorias sem log aguardam validação.')
    await _chronicles_read_only(guild, channel)
    data = await asyncio.to_thread(_chronicles_snapshot, guild.id, datetime.now(timezone.utc))
    embed = _chronicles_embed(data)
    panel = None
    async for message in channel.history(limit=30):
        if message.author == bot.user and message.embeds and message.embeds[0].title == CHRONICLES_TITLE:
            panel = message
            break
    if panel:
        await panel.edit(embed=embed)
    else:
        await channel.send(embed=embed)


async def scum_chronicles_loop():
    await bot.wait_until_ready()
    completed_slot = None
    while not bot.is_closed():
        try:
            snapshot = await asyncio.to_thread(_walk_read_sync)
            count = await asyncio.to_thread(_walk_import, snapshot)
            if snapshot: print(f'MARATONISTAS: {snapshot[0]} | {count} registros analisados')
        except Exception as error:
            print(f'MARATONISTAS: {type(error).__name__}: {error}')
        # Uma coleta por janela de reinício; falha não contamina o histórico.
        slot = _chronicles_collection_slot(datetime.now(timezone.utc))
        if slot is not None and slot != completed_slot:
            completed_slot = slot
            try:
                changed = await asyncio.wait_for(asyncio.to_thread(_stats_refresh), timeout=240)
                print(f'CRÔNICAS DB: coleta validada | métricas atualizadas={changed}')
            except Exception as error:
                print(f'CRÔNICAS DB: coleta descartada | {type(error).__name__}: {error}')
            for stats_guild in bot.guilds:
                try:
                    await _stats_guild(stats_guild)
                except Exception as error:
                    print(f'CRÔNICAS PAINEL: {stats_guild.name}: {type(error).__name__}: {error}')
        # Publicação independente da coleta: categorias visíveis mesmo sem snapshot.
        for stats_guild in bot.guilds:
            try:
                await _stats_guild(stats_guild)
            except Exception as error:
                print(f'CRÔNICAS PAINEL: {stats_guild.name}: {type(error).__name__}: {error}')
        for guild in bot.guilds:
            try:
                await _chronicles_guild(guild)
            except Exception as error:
                print(f'CRÔNICAS: {guild.name}: {type(error).__name__}: {error}')
        await asyncio.sleep(600)



# ============================================================
# REGISTRO PRIVADO DE ACESSOS — eventos do login.log já lido pelo Status.
# ============================================================
ACCESS_CHANNEL_NAME = "📋・registro-de-acessos"
ACCESS_TZ = ZoneInfo("America/Sao_Paulo")
ACCESS_CHANNEL_NAME = "📋・registro-de-acessos"
ACCESS_TZ = ZoneInfo("America/Sao_Paulo")
# O timestamp bruto do login.log ja e interpretado como UTC na ingestao.
# Converter para America/Sao_Paulo uma unica vez, sem subtracao adicional.
# Preservar eventos brutos e chaves de deduplicacao no SQLite.
ACCESS_LOG_CLOCK_CORRECTION = timedelta(0)

def _access_display_time(stamp):
    raw = datetime.fromisoformat(stamp)
    if raw.tzinfo is None:
        raw = raw.replace(tzinfo=timezone.utc)
    return (raw + ACCESS_LOG_CLOCK_CORRECTION).astimezone(ACCESS_TZ)

def _access_ingest(events):
    with _island_db_connect() as db:
        db.execute("""CREATE TABLE IF NOT EXISTS access_events (
            event_key TEXT PRIMARY KEY, steam TEXT NOT NULL, name TEXT NOT NULL,
            action TEXT NOT NULL, occurred_at TEXT NOT NULL)""")
        db.execute("CREATE INDEX IF NOT EXISTS access_events_day ON access_events(occurred_at,steam)")
        for stamp, steam, name, action in events:
            if action not in ('in', 'out'): continue
            key = hashlib.sha256(f'{stamp}|{steam}|{action}'.encode()).hexdigest()
            db.execute('INSERT OR IGNORE INTO access_events VALUES (?,?,?,?,?)',
                       (key,steam,name,action,stamp))

def _access_reconcile_status():
    """Fecha lacunas no histórico sem modificar eventos reais do SCUM.

    Logout ausente: usa o reset confirmado, a primeira leitura válida de
    ausência, ou (para lacunas antigas) a próxima entrada como limite máximo.
    A origem do horário fica persistida separadamente no SQLite.
    """
    checked = LIVE_ONLINE_CHECKED_AT
    fresh = (checked is not None and LAST_SCUM_STATUS is not None
             and LAST_SCUM_STATUS.get('online') is True
             and not LAST_SCUM_STATUS.get('stale')
             and 0 <= (datetime.now(timezone.utc)-checked).total_seconds() <= 300)
    online_ids = set(LIVE_ONLINE_STEAM_IDS) if fresh else set()
    with _island_db_connect() as db:
        db.execute("""CREATE TABLE IF NOT EXISTS access_events (
            event_key TEXT PRIMARY KEY, steam TEXT NOT NULL, name TEXT NOT NULL,
            action TEXT NOT NULL, occurred_at TEXT NOT NULL)""")
        db.execute("""CREATE TABLE IF NOT EXISTS access_inferred_exits (
            event_key TEXT PRIMARY KEY, source TEXT NOT NULL)""")
        rows = db.execute("""SELECT event_key,steam,name,action,occurred_at FROM access_events
            ORDER BY occurred_at, CASE action WHEN 'out' THEN 0 ELSE 1 END,event_key""").fetchall()
        # Se o logout real chegou depois de uma inferência, ele prevalece.
        inferred = {r[0] for r in db.execute('SELECT event_key FROM access_inferred_exits')}
        real = [r for r in rows if r[0] not in inferred]
        by_steam = {}
        for row in real:
            by_steam.setdefault(row[1], []).append(row)
        additions = []
        for steam, events in by_steam.items():
            pending = None
            for key, _, name, action, stamp in events:
                when = datetime.fromisoformat(stamp)
                if when.tzinfo is None: when = when.replace(tzinfo=timezone.utc)
                if action == 'out':
                    pending = None
                elif pending is not None:
                    old_name, start = pending
                    boundary = _access_reset_boundary(start.astimezone(ACCESS_TZ), LIVE_LOGIN_LOG_STARTED_AT)
                    if boundary is not None and boundary.astimezone(timezone.utc) <= when:
                        end, source = boundary.astimezone(timezone.utc), 'reset'
                    else:
                        end, source = when, 'next_login'
                    if end > start:
                        additions.append((steam,old_name,start,end,source))
                    pending = (name,when)
                else:
                    pending = (name,when)
            if pending is not None and fresh and steam not in online_ids:
                name,start = pending
                if checked > start:
                    boundary = _access_reset_boundary(start.astimezone(ACCESS_TZ), LIVE_LOGIN_LOG_STARTED_AT)
                    end = boundary.astimezone(timezone.utc) if boundary else checked
                    if end > start:
                        additions.append((steam,name,start,end,'reset' if boundary else 'status'))
        # Reconstrói apenas inferências, preservando integralmente eventos reais.
        db.execute('DELETE FROM access_events WHERE event_key IN (SELECT event_key FROM access_inferred_exits)')
        db.execute('DELETE FROM access_inferred_exits')
        for steam,name,start,end,source in additions:
            stamp = end.isoformat()
            key = hashlib.sha256(f'access-inferred|{steam}|{start.isoformat()}|{stamp}|{source}'.encode()).hexdigest()
            db.execute('INSERT OR IGNORE INTO access_events VALUES (?,?,?,?,?)',(key,steam,name,'out',stamp))
            db.execute('INSERT OR IGNORE INTO access_inferred_exits VALUES (?,?)',(key,source))
        return len(additions)


def _access_snapshot():
    today = datetime.now(ACCESS_TZ).date()
    start = (datetime.combine(today, datetime.min.time(), ACCESS_TZ).astimezone(timezone.utc) - ACCESS_LOG_CLOCK_CORRECTION).isoformat()
    end = (datetime.combine(today + timedelta(days=1), datetime.min.time(), ACCESS_TZ).astimezone(timezone.utc) - ACCESS_LOG_CLOCK_CORRECTION).isoformat()
    with _island_db_connect() as db:
        db.execute("""CREATE TABLE IF NOT EXISTS access_events (
            event_key TEXT PRIMARY KEY, steam TEXT NOT NULL, name TEXT NOT NULL,
            action TEXT NOT NULL, occurred_at TEXT NOT NULL)""")
        rows = db.execute('SELECT steam,name,action,occurred_at FROM access_events WHERE occurred_at>=? AND occurred_at<? ORDER BY occurred_at,steam', (start,end)).fetchall()
    people = {}
    for steam,name,action,stamp in rows:
        dt = _access_display_time(stamp)
        person = people.setdefault(steam, {'name':name,'entries':[],'exits':[],'events':[]})
        person['name'] = name
        person['events'].append((dt,action))
        person['entries' if action=='in' else 'exits'].append(dt)
    return today, people

def _access_reset_boundary(started, log_started):
    """Ultimo reset programado entre a entrada e o novo login.log confirmado.

    Retorna horario LOCAL programado, nao um horario real de logout.
    """
    if not log_started:
        return None
    log_local = log_started.astimezone(ACCESS_TZ)
    for day_offset in (0, -1):
        day = log_local.date() + timedelta(days=day_offset)
        for hour in (22, 14, 6):
            boundary = datetime.combine(day, datetime.min.time(), ACCESS_TZ).replace(hour=hour)
            # O log novo pode iniciar segundos/minutos depois do reset.
            if started < boundary <= log_local and (log_local-boundary).total_seconds() <= 3600:
                return boundary
    return None


def _access_embeds():
    try:
        _access_reconcile_status()
    except (sqlite3.Error, OSError, ValueError) as error:
        print(f'ACESSOS: conciliacao indisponivel | {type(error).__name__}: {error}')
    today, people = _access_snapshot()
    records = []
    for steam, person in sorted(people.items(), key=lambda pair: (
            pair[1]['entries'][0] if pair[1]['entries'] else datetime.max.replace(tzinfo=ACCESS_TZ),pair[0])):
        if not person['entries']: continue
        events = sorted(person['events'],key=lambda item:(item[0],0 if item[1]=='out' else 1))
        lines=[]; started=None
        for dt,action in events:
            if action == 'in':
                started=dt
                lines.append('🟢 '+dt.strftime('%H:%M:%S')+' entrada')
            else:
                duration=''
                if started is not None and dt >= started:
                    seconds=int((dt-started).total_seconds())
                    duration=f' · {seconds//3600}h {(seconds%3600)//60:02d}min'
                lines.append('🔴 '+dt.strftime('%H:%M:%S')+' saída'+duration)
                started=None
        name=discord.utils.escape_markdown(person['name'])[:75]
        records.append(f'**{name}** · `{steam}`\n'+'\n'.join(lines))
    chunks=[]; current=''
    for record in records:
        for i in range(0,len(record),2900):
            part=record[i:i+2900]
            if len(current)+len(part)+2>3500:
                chunks.append(current);current=''
            current+=('\n\n' if current else '')+part
    if current:chunks.append(current)
    if not chunks:chunks=['Nenhuma entrada identificada no login.log para hoje.']
    embeds=[]
    for i,chunk in enumerate(chunks):
        e=discord.Embed(title=f'📋 REGISTRO DE ACESSOS — {today.strftime("%d/%m/%Y")} · {i+1}/{len(chunks)}',
                        description=chunk,colour=discord.Colour.gold())
        e.set_footer(text=f'{len(records)} jogadores únicos com entrada registrada • Brasília (UTC−3) • Saídas sem logout usam detecção/reset/próxima entrada • Atualizado {datetime.now(ACCESS_TZ).strftime("%H:%M:%S")}')
        embeds.append(e)
    return embeds

async def _access_guild(guild):
    owner=discord.utils.get(guild.roles,name='👑 DONO')
    admin=discord.utils.get(guild.roles,name='🛡️ ADMINISTRADOR')
    category=discord.utils.get(guild.categories,name='🔐 STAFF')
    if category is None:
        category=await get_or_create_category(guild,'🔐 STAFF')
    overwrites={guild.default_role:discord.PermissionOverwrite(view_channel=False),
                guild.me:discord.PermissionOverwrite(view_channel=True,read_message_history=True,send_messages=True,embed_links=True)}
    for role in (owner,admin):
        if role: overwrites[role]=discord.PermissionOverwrite(view_channel=True,read_message_history=True)
    channel=find_text_channel_anywhere(guild,ACCESS_CHANNEL_NAME)
    if channel is None:
        channel=await get_or_create_text(guild,category,ACCESS_CHANNEL_NAME,
                                         topic='Registro diário privado de entradas e saídas do SCUM',overwrites=overwrites)
    else:
        await channel.edit(category=category,overwrites=overwrites,reason='Acesso exclusivo DONO e ADMINISTRADOR')
    embeds=await asyncio.to_thread(_access_embeds)
    old=[]
    async for msg in channel.history(limit=100):
        if msg.author==bot.user and msg.embeds and msg.embeds[0].title.startswith('📋 REGISTRO DE ACESSOS —'):
            old.append(msg)
    old.sort(key=lambda m:m.id)
    for i,embed in enumerate(embeds):
        if i<len(old): await old[i].edit(embed=embed)
        else: await channel.send(embed=embed)
    for msg in old[len(embeds):]: await msg.delete()

async def scum_access_loop():
    await bot.wait_until_ready()
    while not bot.is_closed():
        for guild in bot.guilds:
            try: await _access_guild(guild)
            except Exception as error: print(f'ACESSOS: {guild.name}: {type(error).__name__}: {error}')
        await asyncio.sleep(120)


