# SEGUROS — confirmação humana e persistência no SQLite existente
# ============================================================
INSURANCE_PUBLIC_CHANNEL = '🚗・seguro-veicular'
INSURANCE_STAFF_CHANNEL = '🛡️・controle-de-seguros'
FINANCE_CHANNEL = '💰・financeiro-primeiro-mundo'
INSURANCE_PLANS = {'Seguro de veículo': 10, 'Ranger + Seguro': 20, 'Ranger Full blindada': 30}
# As fotos sao anexadas ao proprio cartao administrativo do Discord.
# Nao dependem de URL externa nem geram mensagens adicionais.
INSURANCE_VEHICLE_FILES = {'Laika':'seguro_laika.png','Ranger':'seguro_ranger.png','WolfsWagen (WW)':'seguro_ww.png'}

def _insurance_vehicle_filename(vehicle):
    name=str(vehicle or '').casefold()
    if 'ranger' in name: return INSURANCE_VEHICLE_FILES['Ranger']
    if 'laika' in name: return INSURANCE_VEHICLE_FILES['Laika']
    if any(v in name for v in ('wolfswagen','volkswagen','wolfwagen')) or name.strip()=='ww' or name.startswith('ww '):
        return INSURANCE_VEHICLE_FILES['WolfsWagen (WW)']
    return None

# PNGs incorporados: funcionam mesmo quando Docker/Railway nao copia imagens/.
# Somente os tres arquivos do seguro; nao altera os demais modulos.
INSURANCE_EMBEDDED_IMAGES = {
    'seguro_laika.png': '',
    'seguro_ranger.png': '',
    'seguro_ww.png': '',
}

def _insurance_vehicle_path(filename):
    if not filename: return None
    base=os.path.dirname(os.path.abspath(__file__))
    for candidate in (os.path.join(base,'imagens',filename),os.path.join(base,filename)):
        if os.path.isfile(candidate): return candidate
    # Railway pode copiar somente bot.py para a imagem Docker.
    # Recupera a foto do proprio codigo em /tmp, sem tocar no volume /data.
    payload=INSURANCE_EMBEDDED_IMAGES.get(filename)
    if not payload: return None
    try:
        import tempfile
        target=os.path.join(tempfile.gettempdir(),'primeiro_mundo_insurance_assets',filename)
        os.makedirs(os.path.dirname(target),exist_ok=True)
        import base64,zlib,hashlib
        content=zlib.decompress(base64.b64decode(payload))
        if not os.path.isfile(target) or hashlib.sha256(open(target,'rb').read()).digest()!=hashlib.sha256(content).digest():
            with open(target,'wb') as handle:
                handle.write(content)
        return target
    except Exception as exc:
        print(f'SEGUROS: falha ao recuperar imagem {filename}: {exc}')
        return None

async def _insurance_send_card(channel,row,view):
    filename=_insurance_vehicle_filename(row['vehicle'])
    path=_insurance_vehicle_path(filename)
    kwargs={'embed':_insurance_embed(row),'view':view}
    if path: kwargs['file']=discord.File(path,filename=filename)
    elif filename: print(f'SEGUROS: imagem ausente: {filename}')
    return await channel.send(**kwargs)

async def _insurance_edit_card(message,row,view):
    filename=_insurance_vehicle_filename(row['vehicle'])
    path=_insurance_vehicle_path(filename)
    attachments=list(message.attachments)
    kwargs={'embed':_insurance_embed(row),'view':view}
    if filename and path:
        # Substitui a foto anterior, mesmo que o nome seja igual.
        kwargs['attachments']=[*[a for a in attachments if a.filename not in INSURANCE_VEHICLE_FILES.values()],discord.File(path,filename=filename)]
    await message.edit(**kwargs)

INSURANCE_DB_LOCK = threading.RLock()

def _insurance_db():
    os.makedirs(os.path.dirname(ISLAND_DB_PATH) or '.', exist_ok=True)
    db = sqlite3.connect(ISLAND_DB_PATH, timeout=20)
    db.row_factory = sqlite3.Row
    db.execute('PRAGMA busy_timeout=20000')
    db.execute('''CREATE TABLE IF NOT EXISTS insurance_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER NOT NULL,
        discord_id INTEGER NOT NULL, discord_name TEXT NOT NULL,
        player_name TEXT NOT NULL, vehicle TEXT NOT NULL, plan TEXT NOT NULL,
        amount INTEGER NOT NULL, requested_at TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending', reviewed_at TEXT,
        reviewed_by INTEGER, starts_at TEXT, expires_at TEXT,
        staff_message_id INTEGER, reminder_stage INTEGER NOT NULL DEFAULT 0)''')
    db.execute('''CREATE TABLE IF NOT EXISTS insurance_date_audit (
        id INTEGER PRIMARY KEY AUTOINCREMENT, request_id INTEGER NOT NULL,
        guild_id INTEGER NOT NULL, admin_id INTEGER NOT NULL,
        old_payment_at TEXT, new_payment_at TEXT NOT NULL,
        old_expires_at TEXT, new_expires_at TEXT NOT NULL,
        changed_at TEXT NOT NULL, reason TEXT NOT NULL DEFAULT 'Correção administrativa')''')
    db.execute('''CREATE TABLE IF NOT EXISTS finance_entries (
        id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER NOT NULL,
        kind TEXT NOT NULL CHECK(kind IN ('income','expense')),
        amount_cents INTEGER NOT NULL CHECK(amount_cents>0), description TEXT NOT NULL,
        occurred_at TEXT NOT NULL, created_at TEXT NOT NULL, created_by INTEGER NOT NULL,
        insurance_id INTEGER UNIQUE, deleted_at TEXT, deleted_by INTEGER, delete_reason TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS insurance_cancel_audit (
        id INTEGER PRIMARY KEY AUTOINCREMENT, request_id INTEGER NOT NULL,
        guild_id INTEGER NOT NULL, admin_id INTEGER NOT NULL,
        cancelled_at TEXT NOT NULL, reason TEXT NOT NULL, reversed_entry_id INTEGER)''')
    db.execute('CREATE INDEX IF NOT EXISTS idx_finance_period ON finance_entries(guild_id,occurred_at,deleted_at)')
    db.execute('CREATE INDEX IF NOT EXISTS idx_insurance_guild_status ON insurance_requests(guild_id,status)')
    db.commit()
    return db

def _insurance_staff(member):
    return member.guild_permissions.administrator or any(r.name in ('👑 DONO','🛡️ ADMINISTRADOR') for r in member.roles)

def _insurance_fmt(value):
    return datetime.fromisoformat(value).astimezone(BRASILIA_TZ).strftime('%d/%m/%Y às %H:%M') if value else '—'

def _insurance_embed(row):
    status = row['status']
    title = {'pending':'🟡 PAGAMENTO A CONFERIR','active':'🟢 SEGURO ATIVO','rejected':'🔴 SOLICITAÇÃO RECUSADA','cancelled':'⚫ SEGURO CANCELADO'}.get(status,'🔴 SEGURO VENCIDO')
    e = discord.Embed(title=f'{title} · #{row["id"]}',colour=discord.Colour.gold() if status=='pending' else discord.Colour.green() if status=='active' else discord.Colour.red())
    e.description = (f'**Jogador:** {discord.utils.escape_markdown(row["player_name"])}\n'
                     f'**Discord:** <@{row["discord_id"]}>\n**Veículo:** {discord.utils.escape_markdown(row["vehicle"])}\n'
                     f'**Plano:** {row["plan"]} · R$ {row["amount"]},00\n'
                     f'**Solicitado:** {_insurance_fmt(row["requested_at"])}\n'
                     f'**Pagamento:** {_insurance_fmt(row["starts_at"])}\n'
                     f'**Conferência ADM:** {_insurance_fmt(row["reviewed_at"])}\n'
                     f'**Vencimento:** {_insurance_fmt(row["expires_at"])}')
    vehicle_filename = _insurance_vehicle_filename(row['vehicle'])
    if vehicle_filename and _insurance_vehicle_path(vehicle_filename): e.set_thumbnail(url='attachment://'+vehicle_filename)
    e.set_footer(text='A solicitação do jogador NÃO confirma pagamento. Apenas a Administração aprova.')
    return e

class InsuranceNameModal(discord.ui.Modal, title='Confirmar seguro — PRIMEIRO MUNDO'):
    player_name = discord.ui.TextInput(label='Nome do jogador no SCUM',max_length=70,required=True)
    def __init__(self, vehicle, plan_key):
        super().__init__(); self.vehicle=vehicle; self.plan_key=plan_key
    async def on_submit(self, interaction):
        choices={'10':'Seguro de veículo','20':'Ranger + Seguro','30':'Ranger Full blindada'}
        vehicle='Ranger' if self.plan_key in ('20','30') else self.vehicle
        guild=interaction.guild
        if not guild: return await interaction.response.send_message('Use este botão dentro do servidor.',ephemeral=True)
        staff=find_text_channel_anywhere(guild,INSURANCE_STAFF_CHANNEL)
        if staff is None: return await interaction.response.send_message('Canal administrativo indisponível. Avise a Administração.',ephemeral=True)
        await interaction.response.defer(ephemeral=True)
        with INSURANCE_DB_LOCK:
            db=_insurance_db()
            try:
                pending=db.execute("SELECT id FROM insurance_requests WHERE guild_id=? AND discord_id=? AND vehicle=? AND status='pending'",(guild.id,interaction.user.id,vehicle)).fetchone()
                if pending:
                    pending_row=db.execute('SELECT * FROM insurance_requests WHERE id=?',(pending['id'],)).fetchone()
                    # A solicitação pode ter sido gravada antes de falhar o envio ao canal ADM.
                    # Nunca tratar um registro órfão como pedido efetivamente encaminhado.
                    pending_id=pending_row['id']
                else:
                    pending_row=None
                if pending_row is None:
                    cur=db.execute('INSERT INTO insurance_requests(guild_id,discord_id,discord_name,player_name,vehicle,plan,amount,requested_at) VALUES(?,?,?,?,?,?,?,?)',
                        (guild.id,interaction.user.id,str(interaction.user),str(self.player_name.value).strip(),vehicle,choices[self.plan_key],int(self.plan_key),datetime.now(timezone.utc).isoformat()))
                    request_id=cur.lastrowid;db.commit()
                    row=db.execute('SELECT * FROM insurance_requests WHERE id=?',(request_id,)).fetchone()
                else:
                    request_id=pending_id
                    row=pending_row
            finally: db.close()
        # Confere o cartão no Discord antes de criar outro: evita duplicidade.
        msg=None
        if row['staff_message_id']:
            try:
                msg=await staff.fetch_message(row['staff_message_id'])
                await _insurance_edit_card(msg,row,InsuranceReviewView(request_id))
            except discord.NotFound:
                msg=None
            except Exception as error:
                print(f'SEGUROS: falha ao verificar painel #{request_id}: {type(error).__name__}: {error}')
                return await interaction.followup.send('⚠️ Não foi possível verificar o pedido administrativo. Tente novamente ou avise a Administração.',ephemeral=True)
        if msg is None:
            try:
                msg=await _insurance_send_card(staff,row,InsuranceReviewView(request_id))
            except Exception as error:
                print(f'SEGUROS: FALHA PUBLICAÇÃO ADM #{request_id} canal={staff.id}: {type(error).__name__}: {error}')
                return await interaction.followup.send(f'⚠️ Solicitação #{request_id} registrada, mas NÃO encaminhada ao canal administrativo. Tente novamente.',ephemeral=True)
        with INSURANCE_DB_LOCK:
            db=_insurance_db()
            try: db.execute('UPDATE insurance_requests SET staff_message_id=? WHERE id=?',(msg.id,request_id));db.commit()
            finally:db.close()
        # O formulário foi criado como resposta efêmera à interação do botão público.
        # Após o envio confirmado ao canal ADM, apagar ESSA mensagem (não publicar
        # comprovante no lugar). A interação do modal tem token próprio, por isso
        # usamos o ID da mensagem de origem e o webhook da interação.
        if interaction.message:
            try:
                await interaction.followup.delete_message(interaction.message.id)
            except discord.NotFound:
                pass  # Já removido.
            except Exception as error:
                print(f'SEGUROS: falha ao fechar formulário #{request_id}: {type(error).__name__}: {error}')
                # Plano B: impedir novos cliques caso o Discord recuse a exclusão.
                try:
                    await interaction.message.edit(content='✅ Solicitação enviada à Administração.',embed=None,view=None,attachments=[])
                except Exception as edit_error:
                    print(f'SEGUROS: falha ao desativar formulário #{request_id}: {type(edit_error).__name__}: {edit_error}')
        else:
            # Modal sem mensagem de origem: não criar nova tela efêmera.
            print(f'SEGUROS: solicitação #{request_id} enviada; modal sem mensagem de origem para fechar.')

class InsuranceSelectionView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=300)
        self.vehicle='Ranger';self.plan_key='10';self.owner_id=None
        vehicle_select=discord.ui.Select(placeholder='Selecione o veículo',min_values=1,max_values=1,options=[
            discord.SelectOption(label='Laika',value='Laika',emoji='🚙'),
            discord.SelectOption(label='Ranger',value='Ranger',emoji='🛻'),
            discord.SelectOption(label='WolfsWagen (WW)',value='WolfsWagen (WW)',emoji='🚗')],row=0)
        vehicle_select.callback=self.select_vehicle;self.vehicle_select=vehicle_select;self.add_item(vehicle_select)
        plan_select=discord.ui.Select(placeholder='Selecione o plano',min_values=1,max_values=1,options=[
            discord.SelectOption(label='R$ 10 — Seguro de veículo (30 dias)',value='10'),
            discord.SelectOption(label='R$ 20 — Ranger + seguro (30 dias)',value='20'),
            discord.SelectOption(label='R$ 30 — Ranger Full blindada + seguro (30 dias)',value='30')],row=1)
        plan_select.callback=self.select_plan;self.add_item(plan_select)
    async def interaction_check(self,interaction):
        if self.owner_id is None: self.owner_id=interaction.user.id
        if interaction.user.id!=self.owner_id:
            await interaction.response.send_message('Esta seleção pertence a outro jogador.',ephemeral=True);return False
        return True
    def _embed(self):
        vehicle='Ranger' if self.plan_key in ('20','30') else self.vehicle
        e=discord.Embed(title='🚗 Solicitar seguro — PRIMEIRO MUNDO',description=f'**Veículo:** {vehicle}\n**Plano:** R$ {self.plan_key},00\n\nConfira a foto e clique em **Continuar**.',colour=discord.Colour.blue())
        filename=_insurance_vehicle_filename(vehicle)
        if filename and _insurance_vehicle_path(filename):e.set_image(url='attachment://'+filename)
        return e
    async def _refresh(self,interaction):
        await interaction.response.defer()
        vehicle='Ranger' if self.plan_key in ('20','30') else self.vehicle
        filename=_insurance_vehicle_filename(vehicle);path=_insurance_vehicle_path(filename)
        kwargs={'embed':self._embed(),'view':self,'attachments':[]}
        if path: kwargs['attachments']=[discord.File(path,filename=filename)]
        else: kwargs['embed'].description += '\n\n⚠️ Imagem não encontrada no repositório.'
        await interaction.edit_original_response(**kwargs)
    async def select_vehicle(self,interaction):
        self.vehicle=self.vehicle_select.values[0]
        if self.plan_key in ('20','30') and self.vehicle!='Ranger':self.plan_key='10'
        await self._refresh(interaction)
    async def select_plan(self,interaction):
        self.plan_key=interaction.data['values'][0]
        if self.plan_key in ('20','30'):self.vehicle='Ranger'
        await self._refresh(interaction)
    @discord.ui.button(label='Continuar',emoji='✅',style=discord.ButtonStyle.success,row=2)
    async def continue_request(self,interaction,button):
        await interaction.response.send_modal(InsuranceNameModal(self.vehicle,self.plan_key))
    @discord.ui.button(label='Cancelar',style=discord.ButtonStyle.secondary,row=2)
    async def cancel(self,interaction,button):
        await interaction.response.edit_message(content='Solicitação cancelada.',embed=None,view=None,attachments=[])

class InsurancePublicView(discord.ui.View):
    def __init__(self): super().__init__(timeout=None)
