class InsuranceReviewView(discord.ui.View):
    def __init__(self,request_id):
        super().__init__(timeout=None)
        self.request_id=request_id
        approve=discord.ui.Button(label='Confirmar pagamento',emoji='✅',style=discord.ButtonStyle.success,custom_id=f'pm:ins:approve:{request_id}')
        reject=discord.ui.Button(label='Recusar',emoji='❌',style=discord.ButtonStyle.danger,custom_id=f'pm:ins:reject:{request_id}')
        approve.callback=self.approve;reject.callback=self.reject
        self.add_item(approve);self.add_item(reject)
    async def _review(self,interaction,approve):
        if not _insurance_staff(interaction.user):
            return await interaction.response.send_message('❌ Apenas DONO ou ADMINISTRADOR podem confirmar pagamentos.',ephemeral=True)
        await interaction.response.defer(ephemeral=True)
        with INSURANCE_DB_LOCK:
            db=_insurance_db()
            try:
                now=datetime.now(timezone.utc)
                expires=now+timedelta(days=30)
                cur=db.execute("UPDATE insurance_requests SET status=?,reviewed_at=?,reviewed_by=?,starts_at=?,expires_at=? WHERE id=? AND guild_id=? AND status='pending'",
                    ('active' if approve else 'rejected',now.isoformat(),interaction.user.id,now.isoformat() if approve else None,expires.isoformat() if approve else None,self.request_id,interaction.guild.id))
                if approve and cur.rowcount:
                    db.execute('''INSERT OR IGNORE INTO finance_entries
                        (guild_id,kind,amount_cents,description,occurred_at,created_at,created_by,insurance_id)
                        VALUES(?,?,?,?,?,?,?,?)''',
                        (interaction.guild.id,'income',int(db.execute('SELECT amount FROM insurance_requests WHERE id=?',(self.request_id,)).fetchone()['amount'])*100,
                         f'Seguro #{self.request_id}',now.isoformat(),now.isoformat(),interaction.user.id,self.request_id))
                db.commit()
                row=db.execute('SELECT * FROM insurance_requests WHERE id=? AND guild_id=?',(self.request_id,interaction.guild.id)).fetchone()
                changed=cur.rowcount
            finally:db.close()
        if not changed:
            return await interaction.followup.send('Esta solicitação já foi analisada. Nenhuma alteração realizada.',ephemeral=True)
        await _insurance_edit_card(interaction.message,row,InsuranceActiveView(self.request_id) if approve else None)
        if approve:
            await _finance_refresh(find_text_channel_anywhere(interaction.guild,FINANCE_CHANNEL))
        try:
            member=interaction.guild.get_member(row['discord_id']) or await interaction.guild.fetch_member(row['discord_id'])
            await member.send(f'🛡️ PRIMEIRO MUNDO — Seu seguro #{row["id"]} foi '+(f'confirmado! Vence em {_insurance_fmt(row["expires_at"])}.' if approve else 'recusado pela Administração.'))
        except (discord.Forbidden,discord.NotFound): pass
    async def approve(self,interaction): await self._review(interaction,True)
    async def reject(self,interaction): await self._review(interaction,False)

class InsurancePaymentDateModal(discord.ui.Modal, title='Corrigir data do pagamento'):
    payment_date = discord.ui.TextInput(label='Data real do pagamento (DD/MM/AAAA)', placeholder='Ex.: 25/09/2026', min_length=10, max_length=10, required=True)
    reason = discord.ui.TextInput(label='Motivo / referência (opcional)', placeholder='Pagamento identificado no PIX', required=False, max_length=180)
    def __init__(self, request_id):
        super().__init__()
        self.request_id=request_id
    async def on_submit(self, interaction):
        if not interaction.guild or not _insurance_staff(interaction.user):
            return await interaction.response.send_message('❌ Acesso exclusivo de DONO/ADMINISTRADOR.', ephemeral=True)
        try:
            paid_date=datetime.strptime(str(self.payment_date.value).strip(), '%d/%m/%Y').date()
        except ValueError:
            return await interaction.response.send_message('❌ Data inválida. Use DD/MM/AAAA.', ephemeral=True)
        today=datetime.now(BRASILIA_TZ).date()
        if paid_date>today:
            return await interaction.response.send_message('❌ A data do pagamento não pode estar no futuro.', ephemeral=True)
        # Data civil brasileira: mantém o horário de pagamento/ativação original quando
        # conhecido; para uma correção retrospectiva, 00h BRT é a referência explícita.
        with INSURANCE_DB_LOCK:
            db=_insurance_db()
            try:
                db.execute('BEGIN IMMEDIATE')
                row=db.execute('SELECT * FROM insurance_requests WHERE id=? AND guild_id=?', (self.request_id,interaction.guild.id)).fetchone()
                if row is None or row['status'] not in ('active','expired'):
                    db.rollback()
                    return await interaction.response.send_message('❌ Seguro não encontrado ou ainda não aprovado.', ephemeral=True)
                old_start=datetime.fromisoformat(row['starts_at']).astimezone(BRASILIA_TZ) if row['starts_at'] else None
                paid_local=datetime.combine(paid_date, old_start.timetz().replace(tzinfo=None) if old_start and old_start.date()==paid_date else datetime.min.time(), tzinfo=BRASILIA_TZ)
                paid_utc=paid_local.astimezone(timezone.utc)
                expires_utc=(paid_local+timedelta(days=30)).astimezone(timezone.utc)
                now=datetime.now(timezone.utc)
                status='expired' if expires_utc<=now else 'active'
                remaining=(expires_utc-now).total_seconds()
                # Reminders already passed must not be replayed after a date correction.
                stage=4 if remaining<=0 else 3 if remaining<=86400 else 2 if remaining<=3*86400 else 1 if remaining<=5*86400 else 0
                db.execute('UPDATE finance_entries SET occurred_at=? WHERE guild_id=? AND insurance_id=? AND deleted_at IS NULL',
                           (paid_utc.isoformat(),interaction.guild.id,self.request_id))
                db.execute('UPDATE insurance_requests SET starts_at=?, expires_at=?, status=?, reminder_stage=? WHERE id=? AND guild_id=?',
                           (paid_utc.isoformat(),expires_utc.isoformat(),status,stage,self.request_id,interaction.guild.id))
                db.execute('INSERT INTO insurance_date_audit(request_id,guild_id,admin_id,old_payment_at,new_payment_at,old_expires_at,new_expires_at,changed_at,reason) VALUES(?,?,?,?,?,?,?,?,?)',
                           (self.request_id,interaction.guild.id,interaction.user.id,row['starts_at'],paid_utc.isoformat(),row['expires_at'],expires_utc.isoformat(),now.isoformat(),str(self.reason.value).strip() or 'Correção administrativa'))
                db.commit()
                updated=db.execute('SELECT * FROM insurance_requests WHERE id=?',(self.request_id,)).fetchone()
            except Exception:
                db.rollback()
                raise
            finally: db.close()
        await interaction.response.send_message(f'✅ Pagamento corrigido para **{paid_date:%d/%m/%Y}**. Vencimento: **{_insurance_fmt(updated["expires_at"])}**. Histórico preservado.',ephemeral=True)
        await _finance_refresh(find_text_channel_anywhere(interaction.guild,FINANCE_CHANNEL))
        staff=find_text_channel_anywhere(interaction.guild,INSURANCE_STAFF_CHANNEL)
        if staff and updated['staff_message_id']:
            try:
                message=await staff.fetch_message(updated['staff_message_id'])
                await _insurance_edit_card(message,updated,InsuranceActiveView(self.request_id))
            except (discord.NotFound,discord.Forbidden) as error:
                print(f'SEGUROS: painel #{self.request_id} não atualizado: {error}')
        if staff:
            await staff.send(f'📅 **Correção de pagamento #{self.request_id}** por <@{interaction.user.id}>: {_insurance_fmt(row["starts_at"])} → {_insurance_fmt(updated["starts_at"])}; vencimento {_insurance_fmt(row["expires_at"])} → {_insurance_fmt(updated["expires_at"])}. Motivo: {discord.utils.escape_markdown(str(self.reason.value).strip() or "Correção administrativa")}')

