class InsuranceCancelConfirmView(discord.ui.View):
    def __init__(self,request_id,owner_id):
        super().__init__(timeout=120)
        self.request_id=request_id;self.owner_id=owner_id;self.done=False

    @discord.ui.button(label='Confirmar exclusão',emoji='🗑️',style=discord.ButtonStyle.danger)
    async def confirm(self,interaction,button):
        if not interaction.guild or not _insurance_staff(interaction.user) or interaction.user.id!=self.owner_id:
            return await interaction.response.send_message('Acesso negado.',ephemeral=True)
        if self.done:
            return await interaction.response.defer(ephemeral=True)
        await interaction.response.defer(ephemeral=True)
        now=datetime.now(timezone.utc).isoformat()
        reason='Exclusão administrativa pelo controle de seguros'
        with INSURANCE_DB_LOCK:
            db=_insurance_db()
            try:
                db.execute('BEGIN IMMEDIATE')
                row=db.execute('SELECT * FROM insurance_requests WHERE id=? AND guild_id=?',(self.request_id,interaction.guild.id)).fetchone()
                if row is None or row['status'] not in ('active','expired'):
                    db.rollback();self.done=True
                    await interaction.message.edit(view=None)
                    return
                entry=db.execute('SELECT id FROM finance_entries WHERE insurance_id=? AND guild_id=? AND deleted_at IS NULL',(self.request_id,interaction.guild.id)).fetchone()
                if entry:
                    db.execute('UPDATE finance_entries SET deleted_at=?,deleted_by=?,delete_reason=? WHERE id=? AND deleted_at IS NULL',
                               (now,interaction.user.id,'Cancelamento do seguro: '+reason,entry['id']))
                db.execute("UPDATE insurance_requests SET status='cancelled' WHERE id=? AND guild_id=? AND status IN ('active','expired')",(self.request_id,interaction.guild.id))
                db.execute('INSERT INTO insurance_cancel_audit(request_id,guild_id,admin_id,cancelled_at,reason,reversed_entry_id) VALUES(?,?,?,?,?,?)',
                           (self.request_id,interaction.guild.id,interaction.user.id,now,reason,entry['id'] if entry else None))
                db.commit()
                updated=db.execute('SELECT * FROM insurance_requests WHERE id=?',(self.request_id,)).fetchone()
            except Exception:
                db.rollback();raise
            finally: db.close()
        self.done=True
        await interaction.message.edit(view=None)
        staff=find_text_channel_anywhere(interaction.guild,INSURANCE_STAFF_CHANNEL)
        if staff and updated['staff_message_id']:
            try:
                card=await staff.fetch_message(updated['staff_message_id'])
                await _insurance_edit_card(card,updated,None)
            except (discord.NotFound,discord.Forbidden) as error:
                print(f'SEGUROS: cartao #{self.request_id} nao atualizado: {error}')
        channel=find_text_channel_anywhere(interaction.guild,FINANCE_CHANNEL)
        if channel: await _finance_refresh(channel)

    @discord.ui.button(label='Voltar',style=discord.ButtonStyle.secondary)
    async def back(self,interaction,button):
        if interaction.user.id!=self.owner_id:
            return await interaction.response.send_message('Acesso negado.',ephemeral=True)
        self.done=True
        await interaction.response.edit_message(view=None)


def _finance_brl(cents):
    return 'R$ '+f'{cents/100:,.2f}'.replace(',','X').replace('.',',').replace('X','.')

def _finance_summary(guild_id):
    with INSURANCE_DB_LOCK:
        db=_insurance_db()
        try:
            rows=db.execute('SELECT * FROM finance_entries WHERE guild_id=? AND deleted_at IS NULL ORDER BY occurred_at DESC,id DESC',(guild_id,)).fetchall()
        finally: db.close()
    now=datetime.now(BRASILIA_TZ)
    monthly=[r for r in rows if datetime.fromisoformat(r['occurred_at']).astimezone(BRASILIA_TZ).strftime('%Y-%m')==now.strftime('%Y-%m')]
    def totals(items):
        income=sum(r['amount_cents'] for r in items if r['kind']=='income')
        expense=sum(r['amount_cents'] for r in items if r['kind']=='expense')
        return income,expense,income-expense
    return rows,totals(rows),totals(monthly),now

def _finance_embed(guild_id):
    rows,all_tot,month,now=_finance_summary(guild_id)
    e=discord.Embed(title='💰 CAIXA — PRIMEIRO MUNDO',colour=discord.Colour.green(),description='Somente pagamentos confirmados e lançamentos ativos. Exclusões permanecem no histórico, fora dos totais.')
    e.add_field(name=f'📅 {now:%m/%Y} · Entradas',value=_finance_brl(month[0]))
    e.add_field(name='Despesas',value=_finance_brl(month[1]))
    e.add_field(name='Resultado mensal',value=_finance_brl(month[2]),inline=False)
    e.add_field(name='Saldo acumulado registrado',value=_finance_brl(all_tot[2]),inline=False)
    lines=[]
    for r in rows[:12]:
        day=datetime.fromisoformat(r['occurred_at']).astimezone(BRASILIA_TZ).strftime('%d/%m')
        lines.append(f'`#{r["id"]}` {day} '+('🟢 +' if r['kind']=='income' else '🔴 −')+f'{_finance_brl(r["amount_cents"])} · {discord.utils.escape_markdown(r["description"][:65])}')
    e.add_field(name='Últimas movimentações',value='\n'.join(lines)[:1024] if lines else 'Nenhum lançamento.',inline=False)
    e.set_footer(text='Valores informados pela Administração; não substitui extrato bancário.')
    return e

class FinanceEntryModal(discord.ui.Modal):
    description=discord.ui.TextInput(label='Descrição',max_length=100,required=True)
    amount=discord.ui.TextInput(label='Valor em reais (ex.: 179,90)',max_length=20,required=True)
    date=discord.ui.TextInput(label='Data DD/MM/AAAA (opcional)',required=False,max_length=10)
    def __init__(self,kind):
        super().__init__(title='Registrar receita' if kind=='income' else 'Registrar despesa');self.kind=kind
    async def on_submit(self,interaction):
        if not interaction.guild or not _insurance_staff(interaction.user):
            return await interaction.response.send_message('Acesso negado.',ephemeral=True)
        from decimal import Decimal,InvalidOperation,ROUND_HALF_UP
        try:
            value=Decimal(str(self.amount.value).strip().replace('.','').replace(',','.'))
            cents=int((value*100).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
            if cents<=0 or cents>1000000000: raise ValueError()
            day=datetime.strptime(str(self.date.value).strip(),'%d/%m/%Y').date() if str(self.date.value).strip() else datetime.now(BRASILIA_TZ).date()
            if day>datetime.now(BRASILIA_TZ).date(): raise ValueError()
        except (ValueError,InvalidOperation):
            return await interaction.response.send_message('Valor ou data inválidos.',ephemeral=True)
        now=datetime.now(timezone.utc).isoformat()
        occurred=datetime.combine(day,datetime.min.time(),tzinfo=BRASILIA_TZ).astimezone(timezone.utc).isoformat()
        with INSURANCE_DB_LOCK:
            db=_insurance_db()
            try:
                cur=db.execute('INSERT INTO finance_entries(guild_id,kind,amount_cents,description,occurred_at,created_at,created_by) VALUES(?,?,?,?,?,?,?)',
                               (interaction.guild.id,self.kind,cents,str(self.description.value).strip(),occurred,now,interaction.user.id))
                db.commit();entry_id=cur.lastrowid
            finally:db.close()
        await interaction.response.send_message(f'✅ Lançamento #{entry_id} registrado: {_finance_brl(cents)}.',ephemeral=True)
        await _finance_refresh(interaction.channel)

class FinanceDeleteConfirmView(discord.ui.View):
    def __init__(self, entry_ids, owner_id):
        super().__init__(timeout=120)
        self.entry_ids=tuple(entry_ids);self.owner_id=owner_id;self.done=False

    @discord.ui.button(label='Confirmar exclusão',emoji='🗑️',style=discord.ButtonStyle.danger)
    async def confirm(self,interaction,button):
        if interaction.user.id!=self.owner_id or not interaction.guild or not _insurance_staff(interaction.user):
            return await interaction.response.send_message('Acesso negado.',ephemeral=True)
        if self.done:
            return await interaction.response.send_message('Operação já processada.',ephemeral=True)
        await interaction.response.defer(ephemeral=True)
        changed=[]; insurance_changed=[]; now=datetime.now(timezone.utc).isoformat()
        with INSURANCE_DB_LOCK:
            db=_insurance_db()
            try:
                db.execute('BEGIN IMMEDIATE')
                for entry_id in self.entry_ids:
                    row=db.execute('SELECT * FROM finance_entries WHERE id=? AND guild_id=? AND deleted_at IS NULL',(entry_id,interaction.guild.id)).fetchone()
                    if row is None:continue
                    if row['insurance_id'] is not None:
                        ins=db.execute('SELECT * FROM insurance_requests WHERE id=? AND guild_id=?',(row['insurance_id'],interaction.guild.id)).fetchone()
                        if ins and ins['status'] in ('active','expired'):
                            db.execute("UPDATE insurance_requests SET status='cancelled' WHERE id=? AND guild_id=? AND status IN ('active','expired')",(ins['id'],interaction.guild.id))
                            db.execute('INSERT INTO insurance_cancel_audit(request_id,guild_id,admin_id,cancelled_at,reason,reversed_entry_id) VALUES(?,?,?,?,?,?)',
                                       (ins['id'],interaction.guild.id,interaction.user.id,now,'Exclusão pelo caixa (seleção administrativa)',row['id']))
                            insurance_changed.append((ins['id'],ins['staff_message_id']))
                    db.execute('UPDATE finance_entries SET deleted_at=?,deleted_by=?,delete_reason=? WHERE id=? AND guild_id=? AND deleted_at IS NULL',
                               (now,interaction.user.id,'Exclusão pelo caixa (seleção administrativa)',row['id'],interaction.guild.id))
                    changed.append(row['id'])
                db.commit()
            except Exception:
                db.rollback();raise
            finally:db.close()
        self.done=True
        for item in self.children:item.disabled=True
        staff=find_text_channel_anywhere(interaction.guild,INSURANCE_STAFF_CHANNEL)
        if staff:
            for ins_id,msg_id in insurance_changed:
                if not msg_id:continue
                try:
                    msg=await staff.fetch_message(msg_id)
                    with INSURANCE_DB_LOCK:
                        db=_insurance_db()
                        try: ins=db.execute('SELECT * FROM insurance_requests WHERE id=?',(ins_id,)).fetchone()
                        finally:db.close()
                    if ins:await _insurance_edit_card(msg,ins,None)
                except discord.HTTPException:pass
        # Encerra a mensagem efêmera da seleção antes de atualizar o painel.
        # Não envia followup nem substitui o conteúdo por aviso de sucesso.
        try:
            await interaction.delete_original_response()
        except discord.NotFound:
            pass
        await _finance_refresh(find_text_channel_anywhere(interaction.guild,FINANCE_CHANNEL))

    @discord.ui.button(label='Voltar',style=discord.ButtonStyle.secondary)
    async def back(self,interaction,button):
        if interaction.user.id!=self.owner_id:return await interaction.response.send_message('Acesso negado.',ephemeral=True)
        self.done=True
        await interaction.response.edit_message(content='Operação cancelada.',view=None)

def _finance_display(row, insurance=None):
    """Human-readable labels; database IDs remain only in SelectOption.value."""
    if insurance is not None:
        player = str(insurance['player_name'] or 'Jogador não informado').strip()
        vehicle = str(insurance['vehicle'] or 'Veículo não informado').strip()
        title = f'{player} — {vehicle}'
    else:
        title = str(row['description'] or 'Lançamento manual').strip()
    try:
        day = datetime.fromisoformat(row['occurred_at']).astimezone(BRASILIA_TZ).strftime('%d/%m/%Y')
    except (TypeError, ValueError):
        day = 'Data não informada'
    amount = _finance_brl(row['amount_cents'])
    kind = 'Entrada' if row['kind'] == 'income' else 'Despesa'
    return title, f'{kind} · {day} · {amount}'


def _finance_insurance_lookup(db, rows, guild_id):
    ids = sorted({int(r['insurance_id']) for r in rows if r['insurance_id'] is not None})
    if not ids:
        return {}
    marks = ','.join('?' for _ in ids)
    matches = db.execute(f'SELECT id,player_name,vehicle FROM insurance_requests WHERE guild_id=? AND id IN ({marks})',
                         (guild_id, *ids)).fetchall()
    return {r['id']: r for r in matches}


class FinanceDeletePickView(discord.ui.View):
    """Native buttons avoid the Discord select popover obscuring the next screen."""
    def __init__(self, rows, owner_id, page=0, selected=None):
        super().__init__(timeout=180)
        self.rows=rows; self.owner_id=owner_id; self.page=page
        self.selected=set(selected or ())
        self._build()

    def _build(self):
        self.clear_items()
        start=self.page*4
        for row, ins in self.rows[start:start+4]:
            title, detail=_finance_display(row, ins)
            chosen=row['id'] in self.selected
            button=discord.ui.Button(label=('☑ ' if chosen else '☐ ')+title[:72],
                style=discord.ButtonStyle.success if chosen else discord.ButtonStyle.secondary,
                row=(row['id']-row['id'])+len(self.children))
            async def pick(interaction, entry_id=row['id']):
                if interaction.user.id!=self.owner_id or not _insurance_staff(interaction.user):
                    return await interaction.response.send_message('Acesso negado.',ephemeral=True)
                if entry_id in self.selected:self.selected.remove(entry_id)
                else:self.selected.add(entry_id)
                self._build()
                await interaction.response.edit_message(content=self._content(),view=self)
            button.callback=pick
            self.add_item(button)
        if self.page>0:
            prev=discord.ui.Button(label='◀ Anterior',style=discord.ButtonStyle.secondary,row=4)
            async def previous(interaction):
                if interaction.user.id!=self.owner_id:return await interaction.response.send_message('Acesso negado.',ephemeral=True)
                self.page-=1;self._build();await interaction.response.edit_message(content=self._content(),view=self)
            prev.callback=previous;self.add_item(prev)
        if (self.page+1)*4<len(self.rows):
            nxt=discord.ui.Button(label='Próxima ▶',style=discord.ButtonStyle.secondary,row=4)
            async def next_page(interaction):
                if interaction.user.id!=self.owner_id:return await interaction.response.send_message('Acesso negado.',ephemeral=True)
                self.page+=1;self._build();await interaction.response.edit_message(content=self._content(),view=self)
            nxt.callback=next_page;self.add_item(nxt)
        confirm=discord.ui.Button(label=f'Continuar ({len(self.selected)})',emoji='🗑️',
            style=discord.ButtonStyle.danger,disabled=not self.selected,row=4)
        async def proceed(interaction):
            if interaction.user.id!=self.owner_id or not interaction.guild or not _insurance_staff(interaction.user):
                return await interaction.response.send_message('Acesso negado.',ephemeral=True)
            with INSURANCE_DB_LOCK:
                db=_insurance_db()
                try:
                    ids=sorted(self.selected)
                    marks=','.join('?' for _ in ids)
                    rows=db.execute(f'SELECT * FROM finance_entries WHERE guild_id=? AND deleted_at IS NULL AND id IN ({marks})',(interaction.guild.id,*ids)).fetchall()
                    insurance=_finance_insurance_lookup(db,rows,interaction.guild.id)
                finally:db.close()
            if not rows:return await interaction.response.edit_message(content='Os lançamentos selecionados já foram excluídos.',view=None)
            lines=[]
            for r in rows:
                title,detail=_finance_display(r,insurance.get(r['insurance_id']))
                lines.append(f'• **{discord.utils.escape_markdown(title[:100])}** · {detail}'+(' · **CANCELA O SEGURO**' if r['insurance_id'] is not None else ''))
            await interaction.response.edit_message(content='**Confirma excluir estes lançamentos?**\n'+'\n'.join(lines)+'\n\nO histórico será preservado. Seguros vinculados perderão a cobertura.',view=FinanceDeleteConfirmView([r['id'] for r in rows],interaction.user.id))
        confirm.callback=proceed;self.add_item(confirm)

    def _content(self):
        lines=['**Marque os lançamentos para excluir:**',f'Página {self.page+1}/{(len(self.rows)+3)//4} · {len(self.selected)} selecionado(s)']
        for row,ins in self.rows[self.page*4:self.page*4+4]:
            title,detail=_finance_display(row,ins)
            lines.append(('☑ ' if row['id'] in self.selected else '☐ ')+discord.utils.escape_markdown(title[:80])+' · '+detail+(' · cancela cobertura' if ins is not None else ''))
        lines.append('Clique nos nomes para marcar; depois, **Continuar**. Sem menu suspenso.')
        return '\n'.join(lines)

class FinanceView(discord.ui.View):
    def __init__(self, has_entries=True):
        super().__init__(timeout=None)
        # Sem movimentações, o botão não abre uma resposta efêmera repetitiva.
        self.delete.disabled = not has_entries
    @discord.ui.button(label='Registrar entrada',emoji='➕',style=discord.ButtonStyle.success,custom_id='pm:finance:income')
    async def income(self,interaction,button):
        if not _insurance_staff(interaction.user):return await interaction.response.send_message('Acesso negado.',ephemeral=True)
        await interaction.response.send_modal(FinanceEntryModal('income'))
    @discord.ui.button(label='Registrar despesa',emoji='➖',style=discord.ButtonStyle.danger,custom_id='pm:finance:expense')
    async def expense(self,interaction,button):
        if not _insurance_staff(interaction.user):return await interaction.response.send_message('Acesso negado.',ephemeral=True)
        await interaction.response.send_modal(FinanceEntryModal('expense'))
    @discord.ui.button(label='Excluir lançamento',emoji='🗑️',style=discord.ButtonStyle.secondary,custom_id='pm:finance:delete')
    async def delete(self,interaction,button):
        if not _insurance_staff(interaction.user):return await interaction.response.send_message('Acesso negado.',ephemeral=True)
        with INSURANCE_DB_LOCK:
            db=_insurance_db()
            try:
                rows=db.execute('SELECT * FROM finance_entries WHERE guild_id=? AND deleted_at IS NULL ORDER BY id DESC LIMIT 25',(interaction.guild.id,)).fetchall()
                insurance=_finance_insurance_lookup(db,rows,interaction.guild.id)
            finally:db.close()
        if not rows:
            # Protege também contra clique em painel antigo, ainda não atualizado.
            await interaction.response.defer()
            await _finance_refresh(interaction.channel)
            return
        display_rows=[(r,insurance.get(r['insurance_id'])) for r in rows]
        pick_view=FinanceDeletePickView(display_rows,interaction.user.id)
        await interaction.response.send_message(pick_view._content(),view=pick_view,ephemeral=True)
    @discord.ui.button(label='Atualizar caixa',emoji='🔄',style=discord.ButtonStyle.secondary,custom_id='pm:finance:refresh')
    async def refresh(self,interaction,button):
        if not _insurance_staff(interaction.user):return await interaction.response.send_message('Acesso negado.',ephemeral=True)
        await interaction.response.defer(ephemeral=True)
        await _finance_refresh(interaction.channel)
        await interaction.followup.send('Caixa atualizado.',ephemeral=True)

async def _finance_refresh(channel):
    if not channel:return
    panel=None
    async for msg in channel.history(limit=50):
        if msg.author==bot.user and msg.embeds and msg.embeds[0].title=='💰 CAIXA — PRIMEIRO MUNDO':panel=msg;break
    entries, _, _, _ = _finance_summary(channel.guild.id)
    view = FinanceView(has_entries=bool(entries))
    if panel:await panel.edit(embed=_finance_embed(channel.guild.id),view=view)
    else:await channel.send(embed=_finance_embed(channel.guild.id),view=view)

async def _finance_setup(guild):
    category=discord.utils.get(guild.categories,name=STAFF_CATEGORY_NAME)
    if not category:return
    owner=discord.utils.get(guild.roles,name='👑 DONO');admin=discord.utils.get(guild.roles,name='🛡️ ADMINISTRADOR')
    overwrites={guild.default_role:discord.PermissionOverwrite(view_channel=False),guild.me:discord.PermissionOverwrite(view_channel=True,send_messages=True,read_message_history=True,embed_links=True)}
    for role in (owner,admin):
        if role:overwrites[role]=discord.PermissionOverwrite(view_channel=True,read_message_history=True)
    channel=find_text_channel_anywhere(guild,FINANCE_CHANNEL)
    if channel is None:channel=await get_or_create_text(guild,category,FINANCE_CHANNEL,overwrites=overwrites)
    else:await channel.edit(category=category,overwrites=overwrites)
    with INSURANCE_DB_LOCK:
        db=_insurance_db()
        try:
            # Reconciliação: registros de seguros não vigentes jamais integram o caixa.
            db.execute("""UPDATE finance_entries SET deleted_at=COALESCE(deleted_at,?),
                deleted_by=COALESCE(deleted_by,0),delete_reason=COALESCE(delete_reason,'Reconciliação: seguro não vigente')
                WHERE guild_id=? AND insurance_id IS NOT NULL AND deleted_at IS NULL
                AND NOT EXISTS (SELECT 1 FROM insurance_requests i WHERE i.id=finance_entries.insurance_id
                    AND i.guild_id=finance_entries.guild_id AND i.status IN ('active','expired'))""",
                (datetime.now(timezone.utc).isoformat(),guild.id))
            # Importação idempotente de seguros aprovados antes da instalação do caixa.
            db.execute('''INSERT OR IGNORE INTO finance_entries(guild_id,kind,amount_cents,description,occurred_at,created_at,created_by,insurance_id)
                SELECT guild_id,'income',amount*100,'Seguro #'||id,COALESCE(starts_at,reviewed_at),COALESCE(reviewed_at,requested_at),COALESCE(reviewed_by,0),id
                FROM insurance_requests WHERE guild_id=? AND status IN ('active','expired') AND starts_at IS NOT NULL''',(guild.id,))
            db.commit()
        finally:db.close()
    await _finance_refresh(channel)

async def _insurance_setup(guild):
    public=find_text_channel_anywhere(guild,INSURANCE_PUBLIC_CHANNEL)
    if public is None:
        category=discord.utils.get(guild.categories,name=SUPPORT_CATEGORY_NAME)
        if category is None: category=await get_or_create_category(guild,SUPPORT_CATEGORY_NAME)
        public=await get_or_create_text(guild,category,INSURANCE_PUBLIC_CHANNEL)
    category=discord.utils.get(guild.categories,name=STAFF_CATEGORY_NAME)
    if category is None: category=await get_or_create_category(guild,STAFF_CATEGORY_NAME)
    owner=discord.utils.get(guild.roles,name='👑 DONO');admin=discord.utils.get(guild.roles,name='🛡️ ADMINISTRADOR')
    overwrites={guild.default_role:discord.PermissionOverwrite(view_channel=False),guild.me:discord.PermissionOverwrite(view_channel=True,send_messages=True,read_message_history=True,embed_links=True)}
    for role in (owner,admin):
        if role: overwrites[role]=discord.PermissionOverwrite(view_channel=True,read_message_history=True)
    staff=find_text_channel_anywhere(guild,INSURANCE_STAFF_CHANNEL)
    if staff is None: staff=await get_or_create_text(guild,category,INSURANCE_STAFF_CHANNEL,overwrites=overwrites)
    else: await staff.edit(category=category,overwrites=overwrites)
    # Só remove painéis anteriores do próprio bot; preserva mensagens de jogadores.
    existing=None
    async for msg in public.history(limit=100):
        if msg.author==bot.user and msg.embeds and msg.embeds[0].title=='🛡️ SEGURO DE VEÍCULOS — PRIMEIRO MUNDO': existing=msg;break
    # O painel de contratação inclui pagamento e solicitação na MESMA mensagem.
    # Reutiliza os dados PIX originais do PRIMEIRO MUNDO; não gera nova cobrança.
    embed=discord.Embed(
        title='🛡️ SEGURO DE VEÍCULOS — PRIMEIRO MUNDO',
        description=(
            '**Escolha seu plano (validade de 30 dias):**\n'
            '🛡️ **R$ 10** — Seguro de 1 veículo\n'
            '🚙 **R$ 20** — 1 Ranger + Seguro\n'
            '🚙 **R$ 30** — 1 Ranger Full blindada + Seguro\n\n'
            '**💳 PAGAMENTO VIA PIX**\n'
            f'📱 Chave PIX (celular): `{PIX_PHONE_KEY}`\n'
            f'📋 PIX Copia e Cola:\n```text\n{PIX_COPY_PASTE}\n```\n'
            '📸 Escaneie o QR Code abaixo ou copie os dados acima.\n\n'
            '**Após pagar**, clique em **💳 Eu paguei o seguro** e informe seu nome no SCUM, '
            'veículo e plano. A declaração **não ativa** o seguro: somente a Administração '
            'confirma o recebimento. O prazo de 30 dias é contado da data real do pagamento, que a Administração pode corrigir.\n\n'
            '⚠️ O seguro fica vinculado ao veículo cadastrado e não é automaticamente transferível.'
        ),colour=discord.Colour.blue())
    if os.path.isfile(PIX_QR_IMAGE_PATH):
        embed.set_image(url='attachment://pix_doacao_qr.png')
        qr_file=discord.File(PIX_QR_IMAGE_PATH,filename='pix_doacao_qr.png')
        if existing:
            await existing.edit(embed=embed,view=InsurancePublicView(),attachments=[qr_file])
        else:
            await public.send(embed=embed,view=InsurancePublicView(),file=qr_file)
    else:
        print('SEGUROS: QR Code não encontrado; exibindo chave PIX e Copia e Cola.')
        if existing: await existing.edit(embed=embed,view=InsurancePublicView(),attachments=[])
        else: await public.send(embed=embed,view=InsurancePublicView())
    with INSURANCE_DB_LOCK:
        db=_insurance_db()
        try: pending=db.execute("SELECT * FROM insurance_requests WHERE guild_id=? AND status='pending' ORDER BY id",(guild.id,)).fetchall()
        finally:db.close()
    with INSURANCE_DB_LOCK:
        db=_insurance_db()
        try: approved=db.execute("SELECT * FROM insurance_requests WHERE guild_id=? AND status IN ('active','expired') ORDER BY id",(guild.id,)).fetchall()
        finally:db.close()
    for row in approved:
        if not row['staff_message_id']: continue
        try:
            msg=await staff.fetch_message(row['staff_message_id'])
            await _insurance_edit_card(msg,row,InsuranceActiveView(row['id']))
        except (discord.NotFound,discord.Forbidden) as error:
            print(f'SEGUROS: painel ativo #{row["id"]} indisponível: {error}')
    for row in pending:
        if row['staff_message_id']:
            try:
                msg=await staff.fetch_message(row['staff_message_id'])
                await _insurance_edit_card(msg,row,InsuranceReviewView(row['id']))
                continue
            except (discord.NotFound,discord.Forbidden): pass
        msg=await _insurance_send_card(staff,row,InsuranceReviewView(row['id']))
        with INSURANCE_DB_LOCK:
            db=_insurance_db()
            try: db.execute('UPDATE insurance_requests SET staff_message_id=? WHERE id=?',(msg.id,row['id']));db.commit()
            finally:db.close()

async def _insurance_setup_safe(guild):
    try:
        await _insurance_setup(guild)
    except Exception as error:
        print(f'SEGUROS SETUP: {guild.name}: {type(error).__name__}: {error}')

async def _insurance_loop():
    await bot.wait_until_ready()
    while not bot.is_closed():
        for guild in bot.guilds:
            try:
                staff=find_text_channel_anywhere(guild,INSURANCE_STAFF_CHANNEL)
                if staff is None: continue
                # Repara pedidos pendentes que ficaram sem cartão após falha de rede/deploy.
                with INSURANCE_DB_LOCK:
                    db=_insurance_db()
                    try: orphan_rows=db.execute("SELECT * FROM insurance_requests WHERE guild_id=? AND status='pending' AND staff_message_id IS NULL ORDER BY id",(guild.id,)).fetchall()
                    finally: db.close()
                for orphan in orphan_rows:
                    try:
                        card=await _insurance_send_card(staff,orphan,InsuranceReviewView(orphan['id']))
                        with INSURANCE_DB_LOCK:
                            db=_insurance_db()
                            try:
                                db.execute('UPDATE insurance_requests SET staff_message_id=? WHERE id=? AND staff_message_id IS NULL',(card.id,orphan['id']))
                                db.commit()
                            finally: db.close()
                        print(f'SEGUROS: solicitação órfã #{orphan["id"]} recuperada no canal ADM.')
                    except Exception as error:
                        print(f'SEGUROS: falha ao recuperar #{orphan["id"]}: {type(error).__name__}: {error}')
                with INSURANCE_DB_LOCK:
                    db=_insurance_db()
                    try: rows=db.execute("SELECT * FROM insurance_requests WHERE guild_id=? AND status='active'",(guild.id,)).fetchall()
                    finally:db.close()
                for row in rows:
                    remaining=(datetime.fromisoformat(row['expires_at'])-datetime.now(timezone.utc)).total_seconds()
                    stage=4 if remaining<=0 else 3 if remaining<=86400 else 2 if remaining<=3*86400 else 1 if remaining<=5*86400 else 0
                    if stage<=row['reminder_stage']: continue
                    with INSURANCE_DB_LOCK:
                        db=_insurance_db()
                        try:
                            cur=db.execute('UPDATE insurance_requests SET reminder_stage=?,status=? WHERE id=? AND reminder_stage<? AND status=?',(stage,'expired' if stage==4 else 'active',row['id'],stage,'active'))
                            db.commit()
                        finally:db.close()
                    if cur.rowcount:
                        await staff.send(f'🛡️ **Seguro #{row["id"]}** — {discord.utils.escape_markdown(row["player_name"])} · {discord.utils.escape_markdown(row["vehicle"])}: '+('**VENCIDO**' if stage==4 else f'faltam aproximadamente {max(0,int(remaining//86400)+1)} dias')+f'. Vencimento: {_insurance_fmt(row["expires_at"])}.')
            except Exception as error: print(f'SEGUROS: {guild.name}: {type(error).__name__}: {error}')
        await asyncio.sleep(3600)



