# CRIADORES — ANÚNCIO AUTOMÁTICO DE LIVES VERIFICADAS
# ============================================================
# Configure no Railway: YOUTUBE_API_KEY e/ou TWITCH_CLIENT_ID + TWITCH_CLIENT_SECRET.
# Cadastro exclusivamente pela administração: !liveadd youtube CHANNEL_ID STEAMID @membro
# ou !liveadd twitch login STEAMID @membro. !livedel plataforma identificador
LIVE_YOUTUBE_KEY = os.getenv("YOUTUBE_API_KEY", "").strip()
LIVE_TWITCH_ID = os.getenv("TWITCH_CLIENT_ID", "").strip()
LIVE_TWITCH_SECRET = os.getenv("TWITCH_CLIENT_SECRET", "").strip()
LIVE_POLL_SECONDS = 180


def _live_db():
    db = sqlite3.connect(ISLAND_DB_PATH, timeout=15)
    db.execute("PRAGMA busy_timeout=15000")
    db.execute("""CREATE TABLE IF NOT EXISTS live_creators (
        guild_id INTEGER NOT NULL, platform TEXT NOT NULL, channel_key TEXT NOT NULL,
        steam_id TEXT NOT NULL, member_id INTEGER NOT NULL,
        PRIMARY KEY(guild_id,platform,channel_key))""")
    db.execute("""CREATE TABLE IF NOT EXISTS live_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER NOT NULL,
        member_id INTEGER NOT NULL, platform TEXT NOT NULL, channel_key TEXT NOT NULL,
        steam_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',
        staff_message_id INTEGER, created_at TEXT NOT NULL,
        reviewed_by INTEGER, reviewed_at TEXT)""")
    db.execute("""CREATE TABLE IF NOT EXISTS live_announcements (
        guild_id INTEGER NOT NULL, platform TEXT NOT NULL, stream_id TEXT NOT NULL,
        announced_at TEXT NOT NULL, PRIMARY KEY(guild_id,platform,stream_id))""")
    return db


def _live_existing(db, guild_id, member_id, platform, key, steam):
    """A channel, SteamID or Discord member may own only one active creator registration."""
    return db.execute("""SELECT platform,channel_key,steam_id,member_id FROM live_creators
        WHERE guild_id=? AND (member_id=? OR steam_id=? OR (platform=? AND channel_key=?)) LIMIT 1""",
        (guild_id,member_id,steam,platform,key)).fetchone()


def _live_pending(db, guild_id, member_id, platform, key, steam, exclude_id=None):
    return db.execute("""SELECT id FROM live_requests WHERE guild_id=? AND status='pending'
        AND (member_id=? OR steam_id=? OR (platform=? AND channel_key=?)) AND id != ? LIMIT 1""",
        (guild_id,member_id,steam,platform,key,exclude_id or -1)).fetchone()


def _live_deduplicate(db, guild_id):
    """Preserve the earliest existing registration for each member, SteamID and channel."""
    rows = db.execute("""SELECT rowid,platform,channel_key,steam_id,member_id
        FROM live_creators WHERE guild_id=? ORDER BY rowid""", (guild_id,)).fetchall()
    members, steams, channels = set(), set(), set()
    for rid, platform, key, steam, member in rows:
        channel = (platform,key)
        if member in members or steam in steams or channel in channels:
            db.execute("DELETE FROM live_creators WHERE rowid=?", (rid,))
        else:
            members.add(member); steams.add(steam); channels.add(channel)


def _live_validate(platform, key, steam):
    platform = platform.strip().lower()
    key = key.strip().strip("<>")
    steam = steam.strip()
    if platform not in ("youtube", "twitch") or not re.fullmatch(r"\d{17}", steam):
        raise ValueError("Escolha YouTube ou Twitch e informe um SteamID64 de 17 dígitos.")
    if not key or len(key) > 200:
        raise ValueError("Informe o link, @usuário ou identificador do canal.")
    return platform, key, steam


def _live_resolve_youtube(raw):
    from urllib.parse import urlparse, unquote
    value = raw.strip().strip("<>")
    if not LIVE_YOUTUBE_KEY:
        raise ValueError("API do YouTube não configurada. Avise a administração.")
    if re.fullmatch(r"UC[\w-]{22}", value):
        channel_id = value
        lookup = {"id": channel_id}
    else:
        url = urlparse(value if "://" in value else "https://" + value)
        host = (url.hostname or "").lower()
        if host in ("youtube.com", "www.youtube.com", "m.youtube.com"):
            parts = [unquote(p) for p in url.path.split("/") if p]
            if not parts:
                raise ValueError("Informe um link de canal, não a página inicial do YouTube.")
            if parts[0] == "channel" and len(parts) > 1 and re.fullmatch(r"UC[\w-]{22}", parts[1]):
                lookup = {"id": parts[1]}
            elif parts[0].startswith("@"):
                lookup = {"forHandle": parts[0][1:]}
            elif parts[0] in ("user", "c") and len(parts) > 1:
                lookup = {"forUsername": parts[1]} if parts[0] == "user" else None
            else:
                lookup = None
        elif value.startswith("@"):
            lookup = {"forHandle": value[1:]}
        else:
            lookup = {"forHandle": value} if re.fullmatch(r"[\w.-]{3,100}", value) else None
        if lookup is None:
            raise ValueError("Use o link youtube.com/@canal, @canal ou ID UC...; links /c/ antigos podem não identificar o canal.")
    try:
        response = requests.get("https://www.googleapis.com/youtube/v3/channels", params={"part":"snippet", "key":LIVE_YOUTUBE_KEY, **lookup}, timeout=15)
        response.raise_for_status()
        items = response.json().get("items", [])
    except requests.RequestException as exc:
        raise ValueError("Não foi possível consultar o YouTube agora. Tente novamente.") from exc
    if not items:
        raise ValueError("Canal não encontrado. Informe o link youtube.com/@canal ou o ID iniciado por UC.")
    item = items[0]
    return item["id"], item.get("snippet", {}).get("title", "Canal YouTube")


def _live_resolve_twitch(raw):
    from urllib.parse import urlparse
    value = raw.strip().strip("<>")
    if value.startswith("@"):
        value = value[1:]
    if "://" in value or value.lower().startswith(("twitch.tv/", "www.twitch.tv/")):
        url = urlparse(value if "://" in value else "https://" + value)
        if (url.hostname or "").lower() not in ("twitch.tv", "www.twitch.tv", "m.twitch.tv"):
            raise ValueError("Informe um link válido da Twitch.")
        value = url.path.strip("/").split("/")[0]
    if not re.fullmatch(r"[a-zA-Z0-9_]{4,25}", value):
        raise ValueError("Informe o @usuário, login ou link twitch.tv/usuario.")
    login = value.lower()
    if not LIVE_TWITCH_ID or not LIVE_TWITCH_SECRET:
        raise ValueError("API da Twitch não configurada. Avise a administração.")
    try:
        token = _live_twitch_token()
        response = requests.get("https://api.twitch.tv/helix/users", params={"login": login}, headers={"Client-ID": LIVE_TWITCH_ID, "Authorization": f"Bearer {token}"}, timeout=15)
        response.raise_for_status()
        users = response.json().get("data", [])
    except requests.RequestException as exc:
        raise ValueError("Não foi possível consultar a Twitch agora. Tente novamente.") from exc
    if not users:
        raise ValueError("Canal da Twitch não encontrado. Confira o login informado.")
    return users[0]["login"].lower(), users[0].get("display_name", login)


def _live_resolve_channel(platform, raw):
    return _live_resolve_youtube(raw) if platform == "youtube" else _live_resolve_twitch(raw)


async def _live_clear_ephemeral(interaction: discord.Interaction, message_id: int, delay: float = 0):
    """Remove a private registration step, never the public panel or staff request."""
    if delay:
        await asyncio.sleep(delay)
    try:
        await interaction.followup.delete_message(message_id)
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        pass


async def _live_private_result(interaction: discord.Interaction, content: str, delay: float = 15):
    """Replace the deferred private progress message, then remove it."""
    await interaction.edit_original_response(content=content, view=None)
    async def _remove():
        await asyncio.sleep(delay)
        try:
            await interaction.delete_original_response()
        except (discord.NotFound, discord.Forbidden, discord.HTTPException):
            pass
    asyncio.create_task(_remove())


class LiveRegistrationModal(discord.ui.Modal, title="Cadastro de criador — PRIMEIRO MUNDO"):
    def __init__(self, platform):
        super().__init__()
        self.selected_platform = platform
    channel = discord.ui.TextInput(label="Link, @usuário ou ID do canal", max_length=200, required=True)
    steam = discord.ui.TextInput(label="Seu SteamID64 (17 dígitos)", min_length=17, max_length=17, required=True)

    async def on_submit(self, interaction: discord.Interaction):
        try:
            platform, key, steam = _live_validate(self.selected_platform, str(self.channel), str(self.steam))
        except ValueError as exc:
            await interaction.response.send_message(f"❌ {exc}", ephemeral=True)
            return
        guild = interaction.guild
        if guild is None:
            await interaction.response.send_message("Use o cadastro dentro do servidor PRIMEIRO MUNDO.", ephemeral=True)
            return
        staff = discord.utils.get(guild.text_channels, name="🛡️・aprovar-criadores")
        if staff is None:
            await interaction.response.send_message("Canal de aprovação indisponível. Avise a administração.", ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True, thinking=True)
        # The modal originates from the private platform selector. Close it
        # after submission; keep the permanent public registration panel.
        if interaction.message is not None:
            asyncio.create_task(_live_clear_ephemeral(interaction, interaction.message.id))
        try:
            key, channel_title = await asyncio.to_thread(_live_resolve_channel, platform, key)
        except ValueError as exc:
            await _live_private_result(interaction, f"❌ {exc}")
            return
        with _live_db() as db:
            _live_deduplicate(db, guild.id)
            existing = _live_existing(db, guild.id, interaction.user.id, platform, key, steam)
            pending = _live_pending(db, guild.id, interaction.user.id, platform, key, steam)
            if existing:
                result = "✅ Este criador, SteamID ou canal já possui cadastro aprovado. Não foi criada outra solicitação."
            elif pending:
                result = "⏳ Este criador, SteamID ou canal já possui uma solicitação aguardando análise."
            else:
                cur = db.execute("INSERT INTO live_requests (guild_id,member_id,platform,channel_key,steam_id,status,created_at) VALUES (?,?,?,?,?,'pending',?)",
                                 (guild.id,interaction.user.id,platform,key,steam,datetime.now(timezone.utc).isoformat()))
                request_id = cur.lastrowid
                result = None
        if result:
            await _live_private_result(interaction, result)
            return
        await _live_private_result(interaction, f"✅ Canal identificado: **{discord.utils.escape_markdown(channel_title)}** (`{key}`). Solicitação enviada para aprovação!")
        try:
            msg = await staff.send(
                f"🎥 **CADASTRO DE CRIADOR #{request_id}**\n"
                f"👤 Solicitante: <@{interaction.user.id}>\n"
                f"📺 Plataforma: **{platform}**\n"
                f"🔗 Canal: **{discord.utils.escape_markdown(channel_title)}** (`{key}`)\n"
                f"🎮 SteamID64 informado: `{steam}`\n"
                "⚠️ Confirme a titularidade do canal e do SteamID antes de aprovar.",
                view=LiveReviewView(request_id),
                allowed_mentions=discord.AllowedMentions.none())
            with _live_db() as db:
                db.execute("UPDATE live_requests SET staff_message_id=? WHERE id=?", (msg.id,request_id))
        except (discord.Forbidden, discord.HTTPException) as exc:
            print(f"LIVES: falha ao encaminhar cadastro #{request_id}: {exc}")


class LivePlatformSelect(discord.ui.Select):
    def __init__(self):
        super().__init__(
            placeholder="Escolha sua plataforma",
            min_values=1, max_values=1,
            options=[
                discord.SelectOption(label="YouTube", value="youtube", emoji="▶️"),
                discord.SelectOption(label="Twitch", value="twitch", emoji="🟣"),
            ],
        )

    async def callback(self, interaction: discord.Interaction):
        await interaction.response.send_modal(LiveRegistrationModal(self.values[0]))


class LivePlatformView(discord.ui.View):
    def __init__(self, member_id):
        super().__init__(timeout=180)
        self.member_id = member_id
        self.add_item(LivePlatformSelect())

    async def interaction_check(self, interaction: discord.Interaction):
        if interaction.user.id != self.member_id:
            await interaction.response.send_message("Este cadastro pertence a outro jogador.", ephemeral=True)
            return False
        return True


class LiveRegistrationView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="Cadastrar meu canal", emoji="🎥", style=discord.ButtonStyle.primary, custom_id="pm_live_registration")
    async def register(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_message(
            "🎥 **Selecione a plataforma para continuar o cadastro:**",
            view=LivePlatformView(interaction.user.id), ephemeral=True,
        )


class LiveReviewView(discord.ui.View):
    def __init__(self, request_id):
        super().__init__(timeout=None)
        self.request_id = request_id
        for item in self.children:
            item.custom_id = f"pm_live_review_{item.label.lower()}_{request_id}"

    async def _decide(self, interaction, approve):
        if not isinstance(interaction.user, discord.Member) or not is_staff(interaction.user):
            await interaction.response.send_message("❌ Somente a administração pode analisar solicitações.", ephemeral=True)
            return
        with _live_db() as db:
            row = db.execute("SELECT guild_id,member_id,platform,channel_key,steam_id,status FROM live_requests WHERE id=?", (self.request_id,)).fetchone()
            if not row or row[5] != 'pending':
                await interaction.response.send_message("Esta solicitação já foi analisada.", ephemeral=True)
                return
            if row[0] != interaction.guild_id:
                await interaction.response.send_message("Solicitação de outro servidor.", ephemeral=True)
                return
            _live_deduplicate(db, row[0])
            if approve and _live_existing(db, row[0], row[1], row[2], row[3], row[4]):
                db.execute("UPDATE live_requests SET status='duplicate',reviewed_by=?,reviewed_at=? WHERE id=? AND status='pending'",
                    (interaction.user.id,datetime.now(timezone.utc).isoformat(),self.request_id))
                await interaction.response.send_message("⚠️ Cadastro já aprovado para este membro, SteamID ou canal. Solicitação duplicada encerrada sem nova aprovação.", ephemeral=True)
                for item in self.children: item.disabled = True
                await interaction.message.edit(content=interaction.message.content + "\n\n⚠️ DUPLICADO — cadastro existente preservado.", view=self)
                return
            status = 'approved' if approve else 'rejected'
            changed = db.execute("UPDATE live_requests SET status=?,reviewed_by=?,reviewed_at=? WHERE id=? AND status='pending'",
                (status,interaction.user.id,datetime.now(timezone.utc).isoformat(),self.request_id)).rowcount
            if not changed:
                await interaction.response.send_message("Esta solicitação já foi analisada.", ephemeral=True)
                return
            if approve:
                db.execute("INSERT INTO live_creators VALUES (?,?,?,?,?)", (row[0],row[2],row[3],row[4],row[1]))
        for item in self.children:
            item.disabled = True
        await interaction.response.edit_message(
            content=interaction.message.content + f"\n\n{'✅ APROVADO' if approve else '❌ RECUSADO'} por {interaction.user.mention}.", view=self,
            allowed_mentions=discord.AllowedMentions.none())
        try:
            member = interaction.guild.get_member(row[1])
            if member:
                await member.send("🎥 Seu cadastro de criador no PRIMEIRO MUNDO foi " + ("aprovado! As lives serão anunciadas quando você estiver ao vivo e conectado ao servidor." if approve else "recusado. Procure a administração para esclarecimentos."))
        except (discord.Forbidden, discord.HTTPException):
            pass

    @discord.ui.button(label="Aprovar", style=discord.ButtonStyle.success, custom_id="pm_live_review_approve")
    async def approve(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._decide(interaction, True)

    @discord.ui.button(label="Recusar", style=discord.ButtonStyle.danger, custom_id="pm_live_review_reject")
    async def reject(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._decide(interaction, False)


async def _live_ensure_registration_panel(channel):
    async for message in channel.history(limit=40):
        if message.author == bot.user and message.content.startswith("🎥 **CADASTRO DE CRIADORES — PRIMEIRO MUNDO**"):
            await message.edit(content=LIVE_REGISTRATION_TEXT, view=LiveRegistrationView())
            return
    await channel.send(LIVE_REGISTRATION_TEXT, view=LiveRegistrationView())


LIVE_REGISTRATION_TEXT = (
    "🎥 **CADASTRO DE CRIADORES — PRIMEIRO MUNDO**\n\n"
    "Faz lives de SCUM? Solicite a divulgação automática do seu canal!\n"
    "Clique no botão, escolha YouTube ou Twitch e informe o link, @usuário ou ID do canal e seu SteamID64. "
    "A administração analisará seu pedido.\n\n"
    "🔴 Após a aprovação, o bot anuncia uma vez por transmissão com @everyone "
    "somente quando a live estiver ativa e seu SteamID estiver conectado ao PRIMEIRO MUNDO."
)


@bot.command(name="liveadd")
@commands.guild_only()
@commands.has_permissions(administrator=True)
async def live_add(ctx, platform: str, channel_key: str, steam_id: str, member: discord.Member):
    platform = platform.casefold().strip()
    channel_key = channel_key.strip()
    if platform not in ("youtube", "twitch") or not re.fullmatch(r"\d{17}", steam_id):
        await ctx.send("Uso: `!liveadd youtube UC... STEAMID17 @membro` ou `!liveadd twitch login STEAMID17 @membro`.")
        return
    if platform == "youtube" and not re.fullmatch(r"UC[\w-]{22}", channel_key):
        await ctx.send("Informe o ID do canal YouTube (começa com UC), não o @handle ou link.")
        return
    if platform == "twitch" and not re.fullmatch(r"[a-zA-Z0-9_]{4,25}", channel_key):
        await ctx.send("Informe o login da Twitch, sem link.")
        return
    if platform == "twitch": channel_key = channel_key.lower()
    with _live_db() as db:
        _live_deduplicate(db, ctx.guild.id)
        existing = _live_existing(db, ctx.guild.id, member.id, platform, channel_key, steam_id)
        if existing:
            await ctx.send("⚠️ Este membro, SteamID ou canal já possui cadastro aprovado. Use `!livedel` para remover o registro antigo antes de alterar a vinculação.")
            return
        db.execute("INSERT INTO live_creators VALUES (?,?,?,?,?)",
                   (ctx.guild.id, platform, channel_key, steam_id, member.id))
    await ctx.send(f"✅ Criador cadastrado: {member.mention} · {platform} `{channel_key}`. Divulgação condicionada à live e ao SteamID online.", allowed_mentions=discord.AllowedMentions(users=True, everyone=False, roles=False))


@bot.command(name="livedel")
@commands.guild_only()
@commands.has_permissions(administrator=True)
async def live_del(ctx, platform: str, channel_key: str):
    with _live_db() as db:
        n = db.execute("DELETE FROM live_creators WHERE guild_id=? AND platform=? AND channel_key=?",
                       (ctx.guild.id, platform.lower(), channel_key.lower() if platform.lower()=="twitch" else channel_key)).rowcount
    await ctx.send("✅ Cadastro removido." if n else "Cadastro não encontrado.")


@bot.command(name="livelist")
@commands.guild_only()
@commands.has_permissions(administrator=True)
async def live_list(ctx):
    with _live_db() as db:
        rows = db.execute("SELECT platform,channel_key,steam_id,member_id FROM live_creators WHERE guild_id=?", (ctx.guild.id,)).fetchall()
    await ctx.send("\n".join(f"{r[0]} · `{r[1]}` · Steam `{r[2]}` · <@{r[3]}>" for r in rows)[:1900] if rows else "Nenhum criador cadastrado.", allowed_mentions=discord.AllowedMentions.none())


# Limita consultas caras ao YouTube e evita repetir 429 e expor a chave nos logs.
_LIVE_YOUTUBE_CACHE = {}
_LIVE_YOUTUBE_BACKOFF_UNTIL = 0.0
_LIVE_YOUTUBE_LOCK = threading.RLock()

def _live_youtube(channel_id):
    global _LIVE_YOUTUBE_BACKOFF_UNTIL
    now = time.monotonic()
    with _LIVE_YOUTUBE_LOCK:
        if now < _LIVE_YOUTUBE_BACKOFF_UNTIL:
            return None
        cached = _LIVE_YOUTUBE_CACHE.get(channel_id)
        if cached and now - cached[0] < 900:
            return cached[1]
        if not LIVE_YOUTUBE_KEY:
            return None
        try:
            r = requests.get("https://www.googleapis.com/youtube/v3/search", params={
                "part": "snippet", "channelId": channel_id, "eventType": "live",
                "type": "video", "maxResults": 5, "key": LIVE_YOUTUBE_KEY}, timeout=15)
            if r.status_code in (429, 403):
                # 403 pode indicar quotaExceeded; esperar evita saturar a API.
                _LIVE_YOUTUBE_BACKOFF_UNTIL = time.monotonic() + 3600
                print(f"LIVES YOUTUBE: HTTP {r.status_code}; consultas suspensas por 60 minutos (sem URL/chave).")
                return None
            r.raise_for_status()
            found = None
            for item in r.json().get("items", []):
                vid = item.get("id", {}).get("videoId")
                if vid and item.get("snippet", {}).get("liveBroadcastContent") == "live":
                    found = (vid, item["snippet"].get("title", "Live de SCUM"),
                             f"https://www.youtube.com/watch?v={vid}")
                    break
            _LIVE_YOUTUBE_CACHE[channel_id] = (time.monotonic(), found)
            return found
        except requests.RequestException as error:
            _LIVE_YOUTUBE_BACKOFF_UNTIL = time.monotonic() + 900
            print(f"LIVES YOUTUBE: consulta indisponível ({type(error).__name__}); nova tentativa após 15 minutos.")
            return None


def _live_twitch_token():
    r = requests.post("https://id.twitch.tv/oauth2/token", data={
        "client_id":LIVE_TWITCH_ID, "client_secret":LIVE_TWITCH_SECRET,
        "grant_type":"client_credentials"}, timeout=15)
    r.raise_for_status()
    return r.json()["access_token"]


def _live_twitch(login, token):
    r = requests.get("https://api.twitch.tv/helix/streams", params={"user_login":login},
                     headers={"Client-ID":LIVE_TWITCH_ID,"Authorization":f"Bearer {token}"}, timeout=15)
    r.raise_for_status()
    for stream in r.json().get("data", []):
        if stream.get("type") == "live":
            return str(stream["id"]), stream.get("title", "Live de SCUM"), f"https://www.twitch.tv/{login}"
    return None


async def _live_watch_loop():
    await bot.wait_until_ready()
    while not bot.is_closed():
        try:
            fresh = (LIVE_ONLINE_CHECKED_AT is not None and
                     (datetime.now(timezone.utc)-LIVE_ONLINE_CHECKED_AT).total_seconds() <= 180)
            if fresh and LIVE_ONLINE_STEAM_IDS:
                with _live_db() as db:
                    for (gid,) in db.execute("SELECT DISTINCT guild_id FROM live_creators").fetchall():
                        _live_deduplicate(db, gid)
                    creators = db.execute("SELECT guild_id,platform,channel_key,steam_id,member_id FROM live_creators").fetchall()
                eligible = [r for r in creators if r[3] in LIVE_ONLINE_STEAM_IDS]
                token = None
                if any(r[1] == "twitch" for r in eligible) and LIVE_TWITCH_ID and LIVE_TWITCH_SECRET:
                    token = await asyncio.to_thread(_live_twitch_token)
                for guild_id, platform, key, steam, member_id in eligible:
                    if platform == "youtube" and LIVE_YOUTUBE_KEY:
                        live = await asyncio.to_thread(_live_youtube, key)
                    elif platform == "twitch" and token:
                        live = await asyncio.to_thread(_live_twitch, key, token)
                    else:
                        continue
                    if not live: continue
                    stream_id, title, url = live
                    guild = bot.get_guild(guild_id)
                    channel = discord.utils.get(guild.text_channels, name="🔴・ao-vivo-agora") if guild else None
                    if not channel: continue
                    # Revalidar presença imediatamente antes de anunciar.
                    if (steam not in LIVE_ONLINE_STEAM_IDS or LIVE_ONLINE_CHECKED_AT is None or
                        (datetime.now(timezone.utc)-LIVE_ONLINE_CHECKED_AT).total_seconds() > 180):
                        continue
                    with _live_db() as db:
                        exists = db.execute("SELECT 1 FROM live_announcements WHERE guild_id=? AND platform=? AND stream_id=?",
                                            (guild_id,platform,stream_id)).fetchone()
                        if exists: continue
                        # Reservar antes de enviar para impedir duplicação após deploy concorrente.
                        db.execute("INSERT OR IGNORE INTO live_announcements VALUES (?,?,?,?)",
                                   (guild_id,platform,stream_id,datetime.now(timezone.utc).isoformat()))
                        if not db.execute("SELECT changes()").fetchone()[0]: continue
                    try:
                        safe_title = discord.utils.escape_mentions(discord.utils.escape_markdown(title[:180]))
                        await channel.send(
                            f"@everyone\n🔴 **CRIADOR AO VIVO — PRIMEIRO MUNDO**\n"
                            f"🎥 <@{member_id}> está transmitindo!\n"
                            f"🏝️ Jogando agora no nosso servidor SCUM.\n"
                            f"📺 **{safe_title}**\n🔗 {url}",
                            allowed_mentions=discord.AllowedMentions(everyone=True, users=True, roles=False))
                        print(f"LIVES: anunciado {platform} {stream_id} para {guild_id}")
                    except Exception:
                        # Permite tentar novamente quando o envio ao Discord falhar.
                        with _live_db() as db:
                            db.execute("DELETE FROM live_announcements WHERE guild_id=? AND platform=? AND stream_id=?",
                                       (guild_id,platform,stream_id))
                        raise
        except Exception as error:
            print(f"LIVES: verificação falhou | {type(error).__name__} (detalhes sensíveis omitidos)")
        await asyncio.sleep(LIVE_POLL_SECONDS)

