# ============================================================
# REGISTRO DE VEÍCULOS — FOTOS ORIGINAIS DAS TRANCAS
# Complemento não invasivo: atualiza embeds existentes e futuros
# publicados por esta identidade do bot no canal de registros.
# ============================================================
_VEHICLE_LOCK_IMAGES = {
    "FERRO": "ferro.png", "PRATA": "prata.png", "OURO": "ouro.png",
    "DIAL LOCK": "dial_lock.png", "DIALLOCK": "dial_lock.png",
}

def _vehicle_lock_image(embed):
    """Identifica a tranca inclusive em embeds com campos formatados em Markdown."""
    content = "\n".join([str(embed.title or ""), str(embed.description or "")] +
                        [f"{f.name}\n{f.value}" for f in embed.fields])
    if "TRANC" not in content.upper():
        return None
    # Discord frequentemente utiliza **Tranca** seguido de **PRATA** em outra linha.
    # Remove formatação sem perder os limites das linhas.
    plain = re.sub(r"[`*_~|]", "", content).upper()
    for match in re.finditer(r"TRANC[AÁ]", plain):
        tail = plain[match.end():match.end() + 85]
        # Só aceitar tipo junto ao rótulo; não capturar campos seguintes.
        candidate = re.search(r"\b(DIAL[ \t]*LOCK|PRATA|FERRO|OURO)\b", tail)
        if candidate:
            name = re.sub(r"\s+", " ", candidate.group(1)).strip()
            return _VEHICLE_LOCK_IMAGES.get(name)
    return None

async def _vehicle_lock_picture_loop():
    """Atualiza fotos das trancas ao iniciar e usa miniaturas nos registros novos."""
    await bot.wait_until_ready()
    root = os.path.dirname(os.path.abspath(__file__))
    def lock_path(name):
        return next((p for p in (os.path.join(root, name), os.path.join(root, "imagens", name))
                     if os.path.isfile(p)), None)

    marker = "[TESTE-IMAGEM-TRANCA-PRIMEIRO-MUNDO]"
    # Detecta registros já atualizados também após reinício/deploy;
    # não edita mensagens cuja miniatura e anexo já estão corretos.
    refreshed = set()
    while not bot.is_closed():
        try:
            missing = [name for name in ("ferro.png", "prata.png", "ouro.png", "dial_lock.png")
                       if not lock_path(name)]
            if missing:
                print("TRANCAS IMAGENS: arquivos ausentes: " + ", ".join(missing), flush=True)
                await asyncio.sleep(120)
                continue
            for guild in bot.guilds:
                channel = discord.utils.find(lambda c: "registro-de-veiculos" in c.name, guild.text_channels)
                if channel is None:
                    continue
                found = changed = already = errors = 0
                async for message in channel.history(limit=2000, oldest_first=True):
                    if message.author.id != bot.user.id or not message.embeds:
                        continue
                    if marker in (message.content or "") or message.components:
                        continue
                    embeds = [e.copy() for e in message.embeds]
                    selected = None
                    for e in embeds:
                        filename = _vehicle_lock_image(e)
                        if filename:
                            found += 1
                            selected = (e, filename)
                            break
                    if selected is None:
                        continue
                    if message.id in refreshed:
                        already += 1
                        continue
                    e, filename = selected
                    # Registros já atualizados possuem a miniatura e o anexo
                    # correspondentes. Não reenviar imagens a cada deploy:
                    # isso consumia chamadas de API e gerava rate limits 429.
                    current_thumb = str(getattr(e.thumbnail, "url", "") or "")
                    has_matching_attachment = any(
                        att.filename.lower() == filename.lower()
                        for att in message.attachments
                    )
                    if has_matching_attachment and (
                        current_thumb.startswith("attachment://" + filename)
                        or current_thumb.startswith("https://cdn.discordapp.com/")
                        or current_thumb.startswith("https://media.discordapp.net/")
                    ):
                        refreshed.add(message.id)
                        already += 1
                        continue
                    try:
                        # Descarta somente anexos antigos das trancas. Mantém
                        # outros anexos e todos os dados originais do registro.
                        old_lock_names = {"ferro.png", "prata.png", "ouro.png", "dial_lock.png"}
                        keep = [att for att in message.attachments if att.filename.lower() not in old_lock_names]
                        e.set_image(url=None)
                        e.set_thumbnail(url="attachment://" + filename)
                        f = discord.File(lock_path(filename), filename=filename)
                        try:
                            await message.edit(embeds=embeds, attachments=[*keep, f])
                        finally:
                            f.close()
                        refreshed.add(message.id)
                        changed += 1
                        print(f"TRANCAS IMAGENS: substituída id={message.id} foto={filename}", flush=True)
                    except (discord.HTTPException, discord.Forbidden, TypeError, ValueError) as exc:
                        errors += 1
                        print(f"TRANCAS IMAGENS: falha id={message.id}: {type(exc).__name__}: {exc}", flush=True)
                    await asyncio.sleep(1.5)
                print(f"TRANCAS IMAGENS: canal={channel.name} identificados={found} "
                      f"atualizados={changed} ja_atualizados={already} falhas={errors}", flush=True)
        except Exception as exc:
            print(f"TRANCAS IMAGENS: falha geral: {type(exc).__name__}: {exc}", flush=True)
        # Registros antigos são examinados uma vez por inicialização; registros
        # novos já recebem miniaturas no fluxo de criação. Evita varredura infinita.
        return


# ============================================================
# MAPA PRIMEIRO MUNDO — CONSULTA NO PROPRIO DISCORD
# ============================================================
# Base cartografica comunitaria NerdMaps (projeto declarado Public Domain).
# O desenho do terreno deriva do jogo SCUM e conserva os direitos aplicaveis
# dos respectivos titulares. Fonte: github.com/nerdcave-support/nerdmaps-for-scum
# A imagem acompanha este bot no mesmo diretorio. Sem downloads externos.
MAP_CHANNEL_NAME = "🗺️・mapa-interativo"
MAP_SITE_URL = "https://bot-primeiro-mundo-production.up.railway.app"
MAP_IMAGE_URL = None  # Mapa incluido no pacote; rede nao e necessaria.
MAP_IMAGE_PATH = os.getenv(
    "SCUM_MAP_IMAGE_PATH",
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "scum_mapa_nerdmaps.png"),
)
# Valores publicados no codigo do NerdMaps para ESSA imagem especifica.
# Horizontal: X do SCUM; vertical: Y do SCUM, conforme index.php.
MAP_WORLD_MIN_X, MAP_WORLD_MAX_X = -904800.0, 616818.0
MAP_WORLD_MIN_Y, MAP_WORLD_MAX_Y = -904800.0, 618818.0
MAP_DOWNLOAD_LOCK = threading.Lock()
SCUM_COPIED_COORDS_RE = re.compile(
    r"^\s*\{\s*X\s*=\s*(?P<x>[+-]?\d+(?:\.\d+)?)\s+"
    r"Y\s*=\s*(?P<y>[+-]?\d+(?:\.\d+)?)\s+"
    r"Z\s*=\s*(?P<z>[+-]?\d+(?:\.\d+)?)\s*\|\s*"
    r"P\s*=\s*[+-]?\d+(?:\.\d+)?\s+"
    r"Y\s*=\s*[+-]?\d+(?:\.\d+)?\s+"
    r"R\s*=\s*[+-]?\d+(?:\.\d+)?\s*\}\s*$",
    re.IGNORECASE,
)

def _map_ensure_image():
    # O PNG deve ficar ao lado de bot.py no repositorio do Railway.
    if not os.path.isfile(MAP_IMAGE_PATH):
        raise FileNotFoundError(
            f"Mapa ausente: {MAP_IMAGE_PATH}. Envie scum_mapa_nerdmaps.png junto com bot.py."
        )
    if os.path.getsize(MAP_IMAGE_PATH) < 100_000:
        raise ValueError("Arquivo do mapa incompleto ou invalido")
    return MAP_IMAGE_PATH

def _map_game_to_pixel(x, y, width, height):
    # NerdMaps index.php: gameToPixelX(player.x) -> horizontal,
    # gameToPixelY(player.y) -> vertical. Nao inverter os eixos.
    if not (MAP_WORLD_MIN_X <= x <= MAP_WORLD_MAX_X and MAP_WORLD_MIN_Y <= y <= MAP_WORLD_MAX_Y):
        raise ValueError("Coordenadas fora dos limites publicados para este mapa")
    px = (MAP_WORLD_MAX_X - x) / (MAP_WORLD_MAX_X - MAP_WORLD_MIN_X) * width
    py = (MAP_WORLD_MAX_Y - y) / (MAP_WORLD_MAX_Y - MAP_WORLD_MIN_Y) * height
    return round(px), round(py)

def _map_draw_marker(x, y):
    from PIL import Image, ImageDraw
    path = _map_ensure_image()
    with Image.open(path) as source:
        source.load()
        im = source.convert("RGB")
    px, py = _map_game_to_pixel(x, y, im.width - 1, im.height - 1)
    radius = max(10, min(im.size) // 65)
    draw = ImageDraw.Draw(im)
    draw.ellipse((px-radius-4, py-radius-4, px+radius+4, py+radius+4), fill="white")
    draw.ellipse((px-radius, py-radius, px+radius, py+radius), fill="#ed2939", outline="#5b0000", width=3)
    draw.line((px-radius*2, py, px+radius*2, py), fill="white", width=3)
    draw.line((px, py-radius*2, px, py+radius*2), fill="white", width=3)
    output = BytesIO()
    im.save(output, "PNG")
    output.seek(0)
    return output

class ScumMapCoordinateModal(discord.ui.Modal, title="Consultar coordenadas SCUM"):
    copied = discord.ui.TextInput(
        label="Cole as coordenadas completas (CTRL+C)",
        style=discord.TextStyle.paragraph,
        placeholder="{X=-288799.375 Y=-1091.543 Z=35881.891|P=331.256775 Y=200.162445 R=358.912628}",
        max_length=400,
        required=True,
    )

    async def on_submit(self, interaction: discord.Interaction):
        match = SCUM_COPIED_COORDS_RE.fullmatch(str(self.copied.value))
        if not match:
            await interaction.response.send_message(
                "❌ Formato invalido. Copie a coordenada completa no SCUM usando CTRL+C e cole sem modificar.",
                ephemeral=True,
            )
            return
        x, y, z = (float(match.group(key)) for key in ("x", "y", "z"))
        await interaction.response.defer(ephemeral=True, thinking=True)
        embed = discord.Embed(title="🗺️ MAPA — PRIMEIRO MUNDO", color=discord.Color.green())
        embed.add_field(name="Coordenadas recebidas", value=f"X: `{x:.3f}`\nY: `{y:.3f}`\nZ: `{z:.3f}`", inline=False)
        embed.description = (
            "📍 Localizacao calculada na base cartografica comunitaria NerdMaps."
        )
        try:
            picture = await asyncio.to_thread(_map_draw_marker, x, y)
            file = discord.File(picture, filename="localizacao_scum.png")
            embed.description = "📍 Localizacao marcada no mapa da ilha (base NerdMaps)."
            embed.set_image(url="attachment://localizacao_scum.png")
            await interaction.followup.send(embed=embed, file=file, ephemeral=True)
        except Exception as error:
            logging.getLogger("primeiro_mundo.mapa").exception("Falha ao gerar mapa: %s", error)
            await interaction.followup.send(
                "⚠️ Coordenadas reconhecidas, mas nao foi possivel gerar o mapa. "
                "Confira se scum_mapa_nerdmaps.png esta junto ao bot.py e se Pillow esta instalado.", ephemeral=True,
            )

class ScumMapView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)
        self.add_item(discord.ui.Button(label="Abrir mapa interativo", emoji="🌍", style=discord.ButtonStyle.link, url=MAP_SITE_URL))

    @discord.ui.button(label="Consultar coordenadas", emoji="🗺️", style=discord.ButtonStyle.primary, custom_id="pm:map:coords:v1")
    async def consult(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(ScumMapCoordinateModal())

async def _ensure_scum_map_panel(guild):
    channel = discord.utils.get(guild.text_channels, name=MAP_CHANNEL_NAME)
    if channel is None:
        category = discord.utils.get(guild.categories, name="🌍 COMUNIDADE")
        channel = await guild.create_text_channel(MAP_CHANNEL_NAME, category=category, reason="Mapa PRIMEIRO MUNDO")
    embed = discord.Embed(
        title="🗺️ MAPA INTERATIVO — PRIMEIRO MUNDO",
        description="🌍 **Abrir mapa interativo:** visualize a ilha, cole suas coordenadas e use o zoom.\n\n"
                    "🗺️ **Consultar coordenadas:** consulta privada diretamente no Discord.",
        color=discord.Color.green(),
    )
    # Nao varre/edita historico antigo em cada inicializacao.
    async for message in channel.history(limit=20):
        if message.author.id == bot.user.id and message.embeds and message.embeds[0].title == embed.title:
            # Atualiza apenas o painel antigo, uma unica vez. Evita edicoes
            # repetidas e preserva as mensagens de outros modulos.
            already_linked = any(
                getattr(component, "url", None) == MAP_SITE_URL
                for row in message.components for component in getattr(row, "children", [])
            )
            if not already_linked:
                await message.edit(embed=embed, view=ScumMapView())
            return
    await channel.send(embed=embed, view=ScumMapView())

@bot.event
async def on_ready():

    print("=" * 60)

    print(
        f"BOT ONLINE: {bot.user} | ID: {bot.user.id}"
    )

    print(
        f"Servidores conectados: {len(bot.guilds)}"
    )

    print("=" * 60)

    if not getattr(
        bot,
        "_persistent_views_loaded",
        False
    ):
        bot.add_view(
            TicketView()
        )

        bot.add_view(
            CloseTicketView()
        )

        bot.add_view(
            SupportView()
        )
        bot.add_view(InsurancePublicView())
        bot.add_view(ScumMapView())
        bot.add_view(FinanceView())
        bot.add_view(LiveRegistrationView())
        try:
            with _live_db() as db:
                pending_lives = db.execute("SELECT id,staff_message_id FROM live_requests WHERE status='pending' AND staff_message_id IS NOT NULL").fetchall()
            for req_id, msg_id in pending_lives:
                bot.add_view(LiveReviewView(req_id), message_id=msg_id)
            print(f"LIVES: {len(pending_lives)} solicitações pendentes restauradas.")
        except Exception as exc:
            print(f"LIVES: falha ao restaurar aprovações: {exc}")
        # Views com IDs por solicitação precisam ser registradas novamente após
        # cada deploy. Sem isso, botões antigos exibem 'não respondeu a tempo'.
        try:
            with INSURANCE_DB_LOCK:
                db=_insurance_db()
                try:
                    saved=db.execute('''SELECT id,status,staff_message_id FROM insurance_requests
                        WHERE status IN ('pending','active','expired') AND staff_message_id IS NOT NULL''').fetchall()
                finally: db.close()
            for saved_row in saved:
                if saved_row['status']=='pending':
                    bot.add_view(InsuranceReviewView(saved_row['id']),message_id=saved_row['staff_message_id'])
                else:
                    bot.add_view(InsuranceActiveView(saved_row['id']),message_id=saved_row['staff_message_id'])
            print(f'SEGUROS: {len(saved)} painéis persistentes registrados no Discord.')
        except Exception as error:
            print(f'SEGUROS: erro ao restaurar botões: {type(error).__name__}: {error}')

        bot._persistent_views_loaded = True

    if not getattr(bot, '_technical_error_handler_installed', False):
        handler = _DiscordTechnicalErrorHandler()
        handler.setFormatter(logging.Formatter('%(name)s: %(levelname)s: %(message)s'))
        logging.getLogger('discord').addHandler(handler)
        logging.getLogger('primeiro_mundo.ftp').addHandler(handler)
        bot._technical_handler = handler
        asyncio.create_task(_technical_rate_limit_recovery_watch(handler))
        bot._technical_error_handler_installed = True

    for guild in bot.guilds:
        try:
            await setup_guild(guild)
            await _ensure_scum_map_panel(guild)

        except Exception as error:
            print(
                f"ERRO em {guild.name}: "
                f"{type(error).__name__}: {error}"
            )

    # Teste opcional: ativar somente quando necessário via variável Railway.
    if os.getenv('TECH_LOG_STARTUP_TEST', '0') == '1' and not getattr(bot, '_technical_log_startup_confirmed', False):
        for guild in bot.guilds:
            channel = discord.utils.get(guild.text_channels, name=TECH_LOG_CHANNEL_NAME)
            if channel is None:
                print(f'LOGS TÉCNICOS: canal não encontrado em {guild.name}', flush=True)
                continue
            try:
                await channel.send('🟢 **Monitor técnico ativo**\nO bot iniciou e o envio de alertas para este canal foi confirmado.', allowed_mentions=discord.AllowedMentions.none())
                print(f'LOGS TÉCNICOS: teste enviado ao canal {channel.name} em {guild.name}', flush=True)
            except (discord.Forbidden, discord.HTTPException) as exc:
                print(f'LOGS TÉCNICOS: FALHA ao enviar teste: {type(exc).__name__}: {exc}', flush=True)
        bot._technical_log_startup_confirmed = True

    # As imagens dos registros antigos já foram aplicadas. Não varrer nem
    # editar o histórico em cada deploy: os PATCH repetidos geravam HTTP 429.
    # Recuperação manual excepcional: VEHICLE_LOCK_HISTORY_REPAIR=1 no Railway.
    if os.getenv("VEHICLE_LOCK_HISTORY_REPAIR", "0") == "1" and not getattr(bot, "_vehicle_lock_pictures_started", False):
        bot._vehicle_lock_pictures_started = True
        asyncio.create_task(_vehicle_lock_picture_loop())
    else:
        print("TRANCAS IMAGENS: varredura histórica desativada; registros existentes preservados.", flush=True)

    if not getattr(bot, "_v21_supervisor_started", False):
        bot._v21_supervisor_started = True
        asyncio.create_task(scum_v21_supervisor_loop())

    if not getattr(bot, "_obituary_loop_started", False):
        bot._obituary_loop_started = True
        asyncio.create_task(scum_obituary_loop())

    if not getattr(bot, "_island_archive_started", False):
        bot._island_archive_started = True
        asyncio.create_task(scum_island_archive_loop())

    if not getattr(bot, "_island_maintenance_started", False):
        bot._island_maintenance_started = True
        asyncio.create_task(scum_island_maintenance_loop())

    if not getattr(bot, "_island_reports_started", False):
        bot._island_reports_started = True
        asyncio.create_task(scum_island_reports_loop())

    if not getattr(bot, "_island_interactions_started", False):
        bot._island_interactions_started = True
        asyncio.create_task(scum_island_interactions_loop())

    for guild in bot.guilds:
        asyncio.create_task(_insurance_setup_safe(guild))

    for guild in bot.guilds:
        try: await _finance_setup(guild)
        except Exception as error: print(f'FINANCEIRO SETUP: {guild.name}: {type(error).__name__}: {error}')

    if not getattr(bot, "_insurance_loop_started", False):
        bot._insurance_loop_started = True
        asyncio.create_task(_insurance_loop())

    if not getattr(bot, "_access_started", False):
        bot._access_started = True
        asyncio.create_task(scum_access_loop())

    if not getattr(bot, "_live_watch_started", False):
        bot._live_watch_started = True
