# ============================================================
# !STATUS
# ============================================================

@bot.command()
async def status(ctx):

    data = await query_scum_server()

    if data["online"]:
        prefix = "🟡" if data.get("stale") else "🟢"
        await ctx.send(
            f"{prefix} **SCUM ONLINE** — "
            f"`{data['players']}/{data['max_players']}` jogadores. "
            f"Fonte: **{data.get('source', 'desconhecida')}**"
        )
    else:
        await ctx.send(
            "🟠 **SCUM SEM NOVA LEITURA** — "
            "não foi possível confirmar o estado agora. "
            "Isso não significa necessariamente que o servidor esteja offline."
        )


