# ============================================================
# !LIMPAR
# ============================================================

@bot.command()
@commands.guild_only()
@commands.has_permissions(
    manage_messages=True
)
async def limpar(
    ctx,
    quantidade: int
):

    quantidade = max(
        1,
        min(quantidade, 100)
    )

    deleted = await ctx.channel.purge(
        limit=quantidade + 1
    )

    await ctx.send(
        f"🧹 {max(len(deleted) - 1, 0)} mensagens removidas.",
        delete_after=5
    )


