# ============================================================
# !EXPULSAR
# ============================================================

@bot.command()
@commands.guild_only()
@commands.has_permissions(
    kick_members=True
)
async def expulsar(
    ctx,
    member: discord.Member,
    *,
    motivo="Sem motivo informado"
):

    if member == ctx.guild.owner:
        await ctx.send(
            "❌ Não é possível expulsar o dono do servidor."
        )
        return

    if member == ctx.author:
        await ctx.send(
            "❌ Você não pode expulsar a si mesmo."
        )
        return

    if member.top_role >= ctx.guild.me.top_role:
        await ctx.send(
            "❌ Não posso moderar esse membro por causa da hierarquia de cargos."
        )
        return

    await member.kick(
        reason=motivo
    )

    await ctx.send(
        f"👢 {member.mention} foi expulso."
    )

    await send_log(
        ctx.guild,
        f"👢 **EXPULSÃO**\n"
        f"👤 Jogador: {member}\n"
        f"🛡️ Staff: {ctx.author}\n"
        f"📝 Motivo: {motivo}"
    )


