# ============================================================
# !TIMEOUT
# ============================================================

@bot.command()
@commands.guild_only()
@commands.has_permissions(
    moderate_members=True
)
async def timeout(
    ctx,
    member: discord.Member,
    minutos: int,
    *,
    motivo="Sem motivo informado"
):

    if minutos < 1:
        minutos = 1

    if minutos > 40320:
        minutos = 40320

    if member == ctx.guild.owner:
        await ctx.send(
            "❌ Não é possível aplicar timeout no dono do servidor."
        )
        return

    if member.top_role >= ctx.guild.me.top_role:
        await ctx.send(
            "❌ Não posso moderar esse membro por causa da hierarquia."
        )
        return

    until = (
        discord.utils.utcnow()
        + timedelta(minutes=minutos)
    )

    await member.timeout(
        until,
        reason=motivo
    )

    await ctx.send(
        f"⏱️ {member.mention} recebeu timeout "
        f"por **{minutos} minutos**."
    )

    await send_log(
        ctx.guild,
        f"⏱️ **TIMEOUT**\n"
        f"👤 Jogador: {member}\n"
        f"🛡️ Staff: {ctx.author}\n"
        f"⏰ Duração: {minutos} minutos\n"
        f"📝 Motivo: {motivo}"
    )


# ============================================================
# ERROS
# ============================================================

@bot.event
async def on_command_error(
    ctx,
    error
):

    if isinstance(
        error,
        commands.CommandNotFound
    ):
        return

    if isinstance(
        error,
        commands.MissingPermissions
    ):
        await ctx.send(
            "❌ Você não possui permissão para usar este comando.",
            delete_after=5
        )
        return

    if isinstance(
        error,
        commands.MissingRequiredArgument
    ):
        await ctx.send(
            f"❌ Faltou informar: `{error.param.name}`.",
            delete_after=8
        )
        return

    if isinstance(
        error,
        commands.BadArgument
    ):
        await ctx.send(
            "❌ Não consegui identificar um dos argumentos informados.",
            delete_after=8
        )
        return

    if isinstance(
        error,
        commands.NoPrivateMessage
    ):
        await ctx.send(
            "❌ Este comando só pode ser usado no servidor.",
            delete_after=5
        )
        return

    print(
        "COMMAND ERROR:",
        type(error).__name__,
        error
    )


