# INICIALIZAÇÃO
# ============================================================

if not TOKEN:
    raise RuntimeError(
        "DISCORD_TOKEN não foi encontrado. "
        "Configure a variável de ambiente antes de iniciar o bot."
    )


if not _ensure_single_instance():
    raise SystemExit(0)

bot.run(TOKEN)
